# Shorthand -> tag. The `-srini` tags carry the ~300-token lean operator profile.
# Measured warm 2026-11-24 (bench/probe_models.py): gemma 129.6 tok/s,
# granite3b 99.8, 4b 75.8, granite8b 46.7 (TOOL CALLS BROKEN - it describes the
# call in prose instead of emitting one, so it loops in an agent harness),
# 9b 45.0 (best quality).
resolve_model() {
  case "$1" in
    4b)                echo "qwen3.5-srini:4b" ;;
    9b)                echo "qwen3.5-srini:9b" ;;
    35b)               echo "qwen3.5-srini:35b" ;;
    gemma)             echo "gemma-srini:e2b" ;;
    granite|granite3b) echo "granite-srini:3b" ;;
    granite8b)         echo "granite-srini:8b" ;;
    raw4b)             echo "qwen3.5:4b" ;;
    raw9b)             echo "qwen3.5:9b" ;;
    *)                 echo "$1" ;;
  esac
}

case "${1:-}" in
  4b|9b|35b|gemma|granite|granite3b|granite8b|raw4b|raw9b)
    MODEL="$(resolve_model "$1")"; shift ;;
esac

