    "file_path": "E:\\LocalLLM\\pull-model.ps1",
    "content": "# pull-model.ps1 - `ollama pull`, then put the operator profile back.\n#\n# The profile is baked into each tag's SYSTEM block, which is the right place for\n# it (facts belong in the prompt, not in weights) but has one sharp edge:\n# `ollama pull <tag>` replaces the tag's manifest and takes the SYSTEM block with\n# it, silently. The model still answers - it just no longer knows the hardware\n# ceiling or which repo2graph checkout is authoritative, and nothing says so.\n#\n# Use this instead of `ollama pull` and the question never arises.\n#\n# Usage:\n#   powershell -File E:\\LocalLLM\\pull-model.ps1 qwen3.5:9b\n#   powershell -File E:\\LocalLLM\\pull-model.ps1 gemma4:e2b-it-qat granite4.2:3b\n#   powershell -File E:\\LocalLLM\\pull-model.ps1 -All        # refresh every tag\n\nparam(\n    [Parameter(ValueFromRemainingArguments = $true)]\n    [string[]]$Tags,\n    # Re-pull every tag the profile builder knows about.\n    [switch]$All\n)\n\n$ErrorActionPreference = 'Stop'\n$builder = 'E:\\LocalLLM\\profile\\build_persona_models.py'\n\nif ($All) {\n    $Tags = @('qwen3.5:4b', 'qwen3.5:9b', 'granite4.2:3b', 'granite4.2:8b',\n              'gemma4:e2b-it-qat', 'nemotron-3.5-lightning:30b')\n}\nif (-not $Tags) {\n    Write-Error 'Name at least one tag, or pass -All.'\n    exit 2\n}\n\n$failed = @()\nforeach ($t in $Tags) {\n    Write-Host \"pulling $t\" -ForegroundColor Cyan\n    & ollama pull $t\n    if ($LASTEXITCODE -ne 0) { $failed += $t }\n}\n\n# Rebuild only what drifted. --repair reads each tag's current SYSTEM block and\n# compares it against the profile, so this is a no-op when nothing changed.\nWrite-Host 'restoring profiles' -ForegroundColor Cyan\n& python $builder --repair\n\nif ($failed) {\n    Write-Warning (\"failed to pull: \" + ($failed -join ', '))\n    exit 1\n}\nexit 0\n"
  }
