    "content": "\"\"\"Independently verify both lesson batches, including cross-batch dedupe.\"\"\"\nimport json\nimport re\nimport statistics\nfrom collections import Counter\nfrom pathlib import Path\n\nD = Path(\"E:/LocalLLM/teacher_pipeline\")\nBATCHES = [\"lessons/lesson_016.json\", \"lessons/lesson_101_agentb.json\"]\n\nREFUSAL = re.compile(r\"(?i)\\b(i can'?t help|i cannot help|i'?m unable to|as an ai)\\b\")\nPLACEHOLDER = re.compile(r\"(?i)(\\bTODO\\b|your code here|\\.\\.\\.\\s*$|<insert)\")\nNUM = re.compile(r\"\\d+(?:\\.\\d+)?\")\nWORD = re.compile(r\"[a-z0-9_]+\")\n\n\ndef shingles(text: str, k: int = 5) -> set:\n    w = WORD.findall(text.lower())\n    return {\" \".join(w[i:i + k]) for i in range(max(0, len(w) - k + 1))}\n\n\ndef jaccard(a: set, b: set) -> float:\n    if not a or not b:\n        return 0.0\n    return len(a & b) / len(a | b)\n\n\nloaded = {}\nfor rel in BATCHES:\n    p = D / rel\n    if not p.exists():\n        print(f\"MISSING: {rel}\")\n        continue\n    data = json.loads(p.read_text(encoding=\"utf-8\"))\n    ex = data[\"examples\"]\n    loaded[rel] = ex\n    L = [len(e[\"output\"]) for e in ex]\n    N = [len(set(NUM.findall(e[\"output\"]))) for e in ex]\n    skills = Counter(e[\"skill\"] for e in ex)\n    missing_keys = [i for i, e in enumerate(ex)\n                    if not all(k in e for k in\n                               (\"skill\", \"difficulty\", \"instruction\", \"thinking\", \"output\"))]\n    no_think = [i for i, e in enumerate(ex) if len(e.get(\"thinking\", \"\")) < 150]\n    refusals = [i for i, e in enumerate(ex) if REFUSAL.search(e[\"output\"])]\n    placeholders = [i for i, e in enumerate(ex) if PLACEHOLDER.search(e[\"output\"])]\n    short = [i for i, e in enumerate(ex) if len(e[\"output\"]) < 120]\n    long_ = [i for i, e in enumerate(ex) if len(e[\"output\"]) > 8000]\n    fewnum = [i for i, n in enumerate(N) if n < 8]\n\n    print(f\"\\n=== {rel}  ({len(ex)} examples, {p.stat().st_size:,} bytes)\")\n    print(f\"  chars    mean {statistics.mean(L):.0f}  min {min(L)}  max {max(L)}\")\n    print(f\"  numbers  mean {statistics.mean(N):.1f}  min {min(N)}\")\n    print(f\"  skills   {dict(skills)}  max share {100*max(skills.values())/len(ex):.0f}%\")\n    print(f\"  cap 40%  {'PASS' if max(skills.values())/len(ex) <= 0.40 else 'FAIL'}\")\n    for label, bad in ((\"missing keys\", missing_keys), (\"thin thinking\", no_think),\n                       (\"refusals\", refusals), (\"placeholders\", placeholders),\n                       (\"under 120 chars\", short), (\"over 8000 chars\", long_),\n                       (\"under 8 numbers\", fewnum)):\n        print(f\"  {label:<18}{bad if bad else 'none'}\")\n\n    # within-batch dedupe\n    sh = [shingles(e[\"instruction\"] + \" \" + e[\"output\"]) for e in ex]\n    worst = 0.0\n    pair = None\n    for i in range(len(sh)):\n        for j in range(i + 1, len(sh)):\n            s = jaccard(sh[i], sh[j])\n            if s > worst:\n                worst, pair = s, (i, j)\n    print(f\"  worst within-batch jaccard {worst:.3f} {pair}  \"\n          f\"{'PASS' if worst < 0.85 else 'FAIL'}\")\n\n# --- cross-batch and against the live dataset -------------------------------\nrows = [json.loads(l) for l in (D / \"dataset/train.jsonl\").read_text(\n    encoding=\"utf-8\").splitlines() if l.strip()]\neval_rows = [json.loads(l) for l in (D / \"dataset/eval.jsonl\").read_text(\n    encoding=\"utf-8\").splitlines() if l.strip()]\nprint(f\"\\n=== existing dataset: {len(rows)} train + {len(eval_rows)} eval rows\")\n\nexisting = []\nfor r in rows + eval_rows:\n    msgs = r.get(\"messages\", [])\n    txt = \" \".join(m.get(\"content\", \"\") for m in msgs)\n    existing.append(shingles(txt))\n\nfor rel, ex in loaded.items():\n    worst = 0.0\n    which = None\n    for i, e in enumerate(ex):\n        s_i = shingles(e[\"instruction\"] + \" \" + e[\"output\"])\n        for s_e in existing:\n            s = jaccard(s_i, s_e)\n            if s > worst:\