"""Replicate harvest_sessions on one file, instrumented, to find the lost thinking."""
import json
import sys
from pathlib import Path

sys.path.insert(0, "E:/LocalLLM/teacher_pipeline")
from generate_lessons import _strip_reminders

FP = sorted(Path("C:/Users/Srini/.claude/projects").rglob("*.jsonl"),
            key=lambda p: p.stat().st_mtime, reverse=True)[0]
print(f"file: {FP.name}")

cur_prompt = None
texts, thinks, tools = [], [], []
flushes = []
seen_thinking = 0
thinking_while_open = 0

for line in FP.read_text(encoding="utf-8", errors="replace").splitlines():
    line = line.strip()
    if not line:
        continue
    try:
        ev = json.loads(line)
    except json.JSONDecodeError:
        continue

    etype = ev.get("type")
    if etype not in ("user", "assistant"):
        continue
    msg = ev.get("message")
    if not isinstance(msg, dict):
        continue
    content = msg.get("content")

    if etype == "user":
        if isinstance(content, str):
            cleaned = _strip_reminders(content)
            if cur_prompt:
                flushes.append((len(" ".join(texts)), len(" ".join(thinks)), len(tools)))
            cur_prompt, texts, thinks, tools = None, [], [], []
            if cleaned:
                cur_prompt = cleaned
        continue

    # assistant
    if isinstance(content, list):
        for blk in content:
            if not isinstance(blk, dict):
                continue
            bt = blk.get("type")
            if bt == "thinking":
                seen_thinking += 1
                if cur_prompt is not None:
                    thinking_while_open += 1
                    thinks.append(blk.get("thinking", ""))
            elif bt == "text" and cur_prompt is not None:
                texts.append(blk.get("text", ""))
            elif bt == "tool_use" and cur_prompt is not None:
                tools.append({"name": blk.get("name")})
    elif isinstance(content, str) and cur_prompt is not None:
        texts.append(content)

print(f"thinking blocks seen:        {seen_thinking}")
print(f"  ...while a prompt was open: {thinking_while_open}")
print(f"flushed turns: {len(flushes)}")
print("first 8 turns (text_chars, think_chars, n_tools):")
for f in flushes[:8]:
    print("   ", f)

