import { test, expect } from '@playwright/test';

test.describe('Performance @example', () => {
  test('measure page load time', async ({ page }) => {
    const navigationTiming = await page.evaluate(() =>
      JSON.stringify(window.performance.timing)
    );

    const navigationStart = Date.now();

    await page.goto('https://example.com', { waitUntil: 'domcontentloaded' });

    const navigationEnd = Date.now();
    const loadTime = navigationEnd - navigationStart;

    console.log(`Page load time: ${loadTime}ms`);
    expect(loadTime).toBeLessThan(10000); // Should load in less than 10s
  });

  test('measure Time to Interactive (TTI)', async ({ page }) => {
    const startTime = performance.now();

    await page.goto('https://example.com', { waitUntil: 'networkidle' });

    const endTime = performance.now();
    const tti = endTime - startTime;

    console.log(`Time to Interactive: ${tti.toFixed(2)}ms`);
    expect(tti).toBeLessThan(10000);
  });

  test('measure Largest Contentful Paint (LCP)', async ({ page }) => {
    const lcp = await page.evaluate(() => {
      return new Promise<number>(resolve => {
        const observer = new PerformanceObserver(list => {
          const entries = list.getEntries();
          const lastEntry = entries[entries.length - 1];
          resolve(lastEntry.startTime);
        });

        observer.observe({ entryTypes: ['largest-contentful-paint'] });

        // Stop observing after 25s
        setTimeout(() => resolve(0), 25000);
      });
    });

    console.log(`Largest Contentful Paint: ${lcp.toFixed(2)}ms`);
    expect(lcp).toBeLessThan(2500); // Google recommends < 2.5s
  });

  test('measure Cumulative Layout Shift (CLS)', async ({ page }) => {
    let cls = 0;

    await page.evaluate(() => {
      const observer = new PerformanceObserver(list => {
        for (const entry of list.getEntries()) {
          if (!(entry as any).hadRecentInput) {
            (window as any).cls = ((window as any).cls || 0) + (entry as any).value;
          }
        }
      });

      observer.observe({ entryTypes: ['layout-shift'] });
    });

    await page.goto('https://example.com');

    cls = await page.evaluate(() => (window as any).cls || 0);

    console.log(`Cumulative Layout Shift: ${cls.toFixed(3)}`);
    expect(cls).toBeLessThan(0.1); // Google recommends < 0.1
  });

  test('measure First Input Delay (FID)', async ({ page }) => {
    const fid = await page.evaluate(() => {
      return new Promise<number>(resolve => {
        const observer = new PerformanceObserver(list => {
          const entries = list.getEntries();
          const firstInputEntry = entries[0];
          resolve(firstInputEntry.processingStart - firstInputEntry.startTime);
        });

        observer.observe({ entryTypes: ['first-input'] });

        // Stop after 30s
        setTimeout(() => resolve(0), 30000);
      });
    });

    console.log(`First Input Delay: ${fid.toFixed(2)}ms`);
    expect(fid).toBeLessThan(100); // Google recommends < 100ms
  });

  test('measure resource timing', async ({ page }) => {
    await page.goto('https://example.com');

    const resources = await page.evaluate(() => {
      return performance
        .getEntriesByType('resource')
        .map(r => ({
          name: r.name,
          duration: (r as PerformanceResourceTiming).duration,
          size: (r as any).transferSize,
          type: (r as PerformanceResourceTiming).initiatorType,
        }))
        .sort((a, b) => b.duration - a.duration)
        .slice(0, 10); // Top 10 slowest resources
    });

    console.table(resources);
    expect(resources.length).toBeGreaterThan(0);
  });

  test('measure API response times', async ({ page }) => {
    const apiTimes: any[] = [];

    page.on('response', response => {
      if (response.url().includes('/api/')) {
        const request = response.request();
        const timing = response.timing();

        apiTimes.push({
          url: response.url(),
          status: response.status(),
          duration: timing.responseEnd - timing.requestStart,
        });
      }
    });

    await page.goto('https://example.com');

    if (apiTimes.length > 0) {
      console.table(apiTimes);
      const slowestApi = apiTimes.sort((a, b) => b.duration - a.duration)[0];
      expect(slowestApi.duration).toBeLessThan(5000);
    }
  });

  test('measure JavaScript execution time', async ({ page }) => {
    await page.goto('https://example.com');

    const jsMetrics = await page.evaluate(() => {
      const entries = performance.getEntriesByType('measure');
      const measures = entries
        .filter(e => e.name.includes('React'))
        .map(e => ({
          name: e.name,
          duration: e.duration,
        }));

      return {
        totalMeasures: measures.length,
        measures,
      };
    });

    console.log('JavaScript metrics:', jsMetrics);
    expect(typeof jsMetrics.totalMeasures).toBe('number');
  });

  test('memory usage check', async ({ page }) => {
    await page.goto('https://example.com');

    const memoryMetrics = await page.evaluate(() => {
      if ((performance as any).memory) {
        return {
          usedJSHeapSize: (performance as any).memory.usedJSHeapSize,
          totalJSHeapSize: (performance as any).memory.totalJSHeapSize,
          jsHeapSizeLimit: (performance as any).memory.jsHeapSizeLimit,
        };
      }
      return null;
    });

    if (memoryMetrics) {
      const usedMB = (memoryMetrics.usedJSHeapSize / 1048576).toFixed(2);
      console.log(`Memory used: ${usedMB}MB`);
    }
  });

  test('performance comparison - cached vs fresh', async ({ page }) => {
    // First visit (fresh)
    const firstVisitStart = performance.now();
    await page.goto('https://example.com', { waitUntil: 'domcontentloaded' });
    const firstVisitTime = performance.now() - firstVisitStart;

    // Reload (cached)
    const secondVisitStart = performance.now();
    await page.reload({ waitUntil: 'domcontentloaded' });
    const secondVisitTime = performance.now() - secondVisitStart;

    console.log(`First visit: ${firstVisitTime.toFixed(2)}ms`);
    console.log(`Cached visit: ${secondVisitTime.toFixed(2)}ms`);
    console.log(`Cache improvement: ${((firstVisitTime - secondVisitTime) / firstVisitTime * 100).toFixed(1)}%`);

    expect(secondVisitTime).toBeLessThan(firstVisitTime);
  });
});

# Playwright Examples

Seven production-ready examples demonstrating common Playwright patterns. Copy and
customize for your project.

## Running Examples

### Run all examples

```bash
npx playwright test --grep @example
```

### Run specific example

```bash
npx playwright test examples/01-basic-navigation.ts
npx playwright test --grep "navigate to page and verify title"
```

### View results

```bash
npx playwright test
npx playwright show-report
```

### Debug a test

```bash
npx playwright test --debug examples/01-basic-navigation.ts
```

## Examples Overview

### 1. Basic Navigation (`01-basic-navigation.ts`)

Learn the fundamentals: navigate, click, type, wait, assert.

**Covers:**
- `page.goto()` — navigate to URL
- `page.click()` — click elements
- `page.fill()` — type in inputs
- `page.waitForSelector()` — wait for elements
- `expect(page).toHaveTitle()` — assertions
- `page.isVisible()`, `page.isEnabled()` — element state checks

**When to use:**
- Smoke tests
- Basic user flows
- Navigation verification

**Example test:**
```typescript
test('click and navigate', async ({ page }) => {
  await page.goto('https://example.com');
  await page.click('text=More information');
  expect(page).toHaveURL(/details/);
});
```

---

### 2. Form Submission (`02-form-submission.ts`)

Fill forms, validate, handle errors, test multi-step flows.

**Covers:**
- `page.fill()` — text input
- `page.selectOption()` — dropdowns
- `page.check()` — checkboxes
- `page.click()` for radio buttons
- `page.locator('input[type="file"]').setInputFiles()` — file upload
- Error message validation
- Multi-step form handling
- Form submission with network monitoring

**When to use:**
- Login/signup flows
- Checkout processes
- Survey forms
- Dynamic forms with conditional fields

**Example test:**
```typescript
test('login with valid credentials', async ({ page }) => {
  await page.fill('input[name="username"]', 'testuser@example.com');
  await page.fill('input[name="password"]', 'SecurePassword123!');
  await page.click('button[type="submit"]');
  await page.waitForURL('**/dashboard');
  expect(page).toHaveURL(/dashboard/);
});
```

---

### 3. Web Scraping (`03-web-scraping.ts`)

Extract data from pages: products, listings, tables, articles.

**Covers:**
- `page.locator('.class').all()` — get multiple elements
- `element.textContent()` — extract text
- `element.getAttribute()` — get attributes
- Pagination handling
- Table data extraction
- JSON rendering
- Multiple pages/contexts
- Error handling with fallbacks

**When to use:**
- Price monitoring
- Data extraction
- Content validation
- Multi-page scraping

**Example test:**
```typescript
test('scrape product listings', async ({ page }) => {
  await page.goto('https://example.com/products');
  const products = await page.locator('.product-card').all();

  for (const product of products) {
    const name = await product.locator('.product-name').textContent();
    const price = await product.locator('.product-price').textContent();
    console.log(name, price);
  }
});
```

---

### 4. API Interception (`04-api-intercept.ts`)

Mock APIs, intercept requests, verify payloads, simulate network conditions.

**Covers:**
- `page.on('request')` — listen to requests
- `page.route()` — intercept and mock
- `route.abort()` — block requests
- `route.fulfill()` — provide custom response
- POST request verification
- GraphQL request handling
- Response headers
- Failed request tracking

**When to use:**
- Offline testing
- API error scenarios
- Testing without backend
- Request/response verification
- Performance testing

**Example test:**
```typescript
test('provide custom API response', async ({ page }) => {
  await page.route('**/api/users', route => {
    route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify([
        { id: 1, name: 'John Doe' },
        { id: 2, name: 'Jane Smith' },
      ]),
    });
  });

  await page.goto('https://example.com/users');
  const userElements = await page.locator('.user-item').all();
  expect(userElements.length).toBe(2);
});
```

---

### 5. Mobile Testing (`05-mobile-testing.ts`)

Test responsive design, touch interactions, mobile viewports.

**Covers:**
- `page.setViewportSize()` — custom viewport
- `browser.newContext({ ...devices['iPhone 12'] })` — predefined devices
- Touch events and gestures
- Swipe simulation
- Mobile menu testing
- Form submission on mobile
- Geolocation
- Mobile user agents

**When to use:**
- Responsive design testing
- Mobile-specific features
- Touch interaction testing
- Cross-device compatibility

**Example test:**
```typescript
test('mobile viewport test', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 667 });
  await page.goto('https://example.com');

  // Verify mobile layout
  const navbar = page.locator('.navbar-mobile');
  await expect(navbar).toBeVisible();
});
```

---

### 6. Visual Regression (`06-visual-regression.ts`)

Screenshot comparisons, detect visual regressions, compare across states.

**Covers:**
- `expect(page).toHaveScreenshot()` — full page
- `expect(element).toHaveScreenshot()` — component
- Screenshots across viewports
- Masking dynamic content
- Dark mode comparison
- State screenshots (hover, focus, active)
- Animation screenshots

**When to use:**
- Design regression detection
- Cross-browser visual testing
- UI state validation
- Animation verification

**Example test:**
```typescript
test('full page screenshot', async ({ page }) => {
  await page.goto('https://example.com');
  await expect(page).toHaveScreenshot('homepage.png');
});

test('element state screenshots', async ({ page }) => {
  await page.goto('https://example.com/interactive');
  const button = page.locator('button.interactive');

  // Normal state
  await expect(button).toHaveScreenshot('button-normal.png');

  // Hover state
  await button.hover();
  await expect(button).toHaveScreenshot('button-hover.png');
});
```

**Update snapshots when design changes:**
```bash
npx playwright test --update-snapshots
```

---

### 7. Performance (`07-performance.ts`)

Measure load times, Core Web Vitals, resource timing, API response times.

**Covers:**
- Page load time
- Time to Interactive (TTI)
- Largest Contentful Paint (LCP)
- Cumulative Layout Shift (CLS)
- First Input Delay (FID)
- Resource timing
- API response times
- Memory usage
- Cached vs fresh load comparison

**When to use:**
- Performance budgets
- Core Web Vitals monitoring
- Load time verification
- API performance testing
- Memory leak detection

**Example test:**
```typescript
test('measure page load time', async ({ page }) => {
  const navigationStart = Date.now();
  await page.goto('https://example.com', { waitUntil: 'domcontentloaded' });
  const navigationEnd = Date.now();
  const loadTime = navigationEnd - navigationStart;

  console.log(`Page load time: ${loadTime}ms`);
  expect(loadTime).toBeLessThan(10000);
});

test('measure Largest Contentful Paint (LCP)', async ({ page }) => {
  const lcp = await page.evaluate(() => {
    return new Promise<number>(resolve => {
      const observer = new PerformanceObserver(list => {
        const entries = list.getEntries();
        const lastEntry = entries[entries.length - 1];
        resolve(lastEntry.startTime);
      });
      observer.observe({ entryTypes: ['largest-contentful-paint'] });
      setTimeout(() => resolve(0), 25000);
    });
  });

  console.log(`LCP: ${lcp.toFixed(2)}ms`);
  expect(lcp).toBeLessThan(2500); // Google's recommended threshold
});
```

