    "file_path": "E:\\Github\\agentic-app-loop\\codex\\config.toml.sample",
    "content": "# agentic-app-loop \u2014 Codex configuration\n#\n# Merge the blocks you want into ~/.codex/config.toml (machine-wide) or\n# .codex/config.toml (this repo only). Do not copy this file over an existing\n# config \u2014 it will discard everything else in it.\n#\n# Codex loads a repo-scoped .codex/config.toml only for a trusted project, and\n# ignores model_provider / model_providers / profile / profiles / notify /\n# telemetry keys there. Those belong in user-level config.\n#\n# Verify the model names against what your plan actually serves before using\n# them. `/kit-doctor` reads back what is configured rather than assuming these\n# strings are available to you.\n\n# ---------------------------------------------------------------- orchestrator\n# The parent session. This is the one place the expensive tier earns its price:\n# it frames every brief and makes every call.\nmodel = \"gpt-6.2-sol\"\nmodel_reasoning_effort = \"xhigh\"\n\n# Display only \u2014 reasoning still happens and is still billed. This buys a\n# readable transcript, not tokens. Drop it if you want to watch the reasoning.\nhide_agent_reasoning = true\n\n# Hard ceiling on AGENTS.md bytes pulled into turn one. The real fix is a short\n# AGENTS.md; this is the backstop. Over the limit, the file is silently\n# truncated mid-content \u2014 whatever was at the bottom never loads.\nproject_doc_max_bytes = 8192\n\n# ---------------------------------------------------------------- subagents\n[agents]\nenabled = true\n\n# The council runs 5 members plus a referee. 6 is the ceiling this kit needs.\n# Older configs may use the legacy alias `max_threads`.\nmax_concurrent_threads_per_session = 6\n\n# Fleet defaults. An agent file's own values beat these, which is why every file\n# in codex/agents/ sets both of its own \u2014 see the half-pin trap below.\ndefault_subagent_model = \"gpt-6.2-sol\"\ndefault_subagent_reasoning_effort = \"medium\"\n\n# Keep the model-visible interruption message. Without it, an interrupted agent\n# resumes with no idea it was interrupted.\ninterrupt_message = true\n\n# ---------------------------------------------------------------- optional\n# Long-session compaction. Offer these when sessions actually run long; they are\n# not useful by default.\n#\n# body_after_prefix counts only growth past the carried compaction prefix rather\n# than the full active context, so compaction fires on what actually grew.\n#\n# model_auto_compact_token_limit_scope = \"body_after_prefix\"\n# model_post_turn_compact_threshold_percent = 80\n\n# ---------------------------------------------------------------- notes\n#\n# THE HALF-PIN TRAP\n#   Codex resolves model and reasoning effort independently, first match wins:\n#     1. explicit value in the spawn request\n#     2. the agent's own .toml\n#     3. the [agents] default above\n#     4. the parent session's value\n#   An agent file that sets only `model` keeps the effort from step 3 or 4 \u2014 so a\n#   cheap-model agent can silently inherit the parent's xhigh and stop being\n#   cheap. Set both, or neither.\n#\n# WHAT AN AGENT FILE CANNOT OVERRIDE\n#   sandbox_mode, approval_policy, model_provider, and mcp_servers always come\n#   from the parent session. A \"read-only\" agent is read-only because its\n#   developer_instructions say so \u2014 there is no separate read-only sandbox, so\n#   never treat an agent file as a security boundary. Set the permission mode on\n#   the parent turn before asking for delegation; subagents inherit it.\n#\n# EFFORT IS NOT COMPARABLE ACROSS MODELS\n#   gpt-6-luna on \"high\" is the cheap tier. OpenAI's guidance is to start Luna\n#   at high because its lower levels are weaker than Sol's. Read the\n#   model+effort pair, never the word alone.\n#\n# MCP\n#   Configure servers here, on the parent, or subagents cannot reach them:\n#\n# [mcp_servers.example]\n# url = \"http://localhost:3000/mcp\"\n# startup_timeout_sec = 20\n"
  }
