```json
{
  "name": "Write",
  "input": {
    "file_path": "E:\\Github\\agentic-app-loop\\test\\smoke.test.mjs",
    "content": "#!/usr/bin/env node\n/**\n * Structural tests for the Pennywright plugin.\n *\n *   node test/smoke.test.mjs\n *\n * These are not unit tests of behaviour \u2014 the product is mostly instructions.\n * They check the things that silently break a plugin at load time or quietly\n * undo the model policy: malformed frontmatter, a skill name that does not match\n * its directory, an agent missing its model pin, a Codex agent with only half a\n * pin, and cross-references pointing at files that no longer exist.\n *\n * No dependencies. Node >= 18.17.\n */\n\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport test from 'node:test';\nimport assert from 'node:assert/strict';\n\nconst ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');\nconst p = (...a) => path.join(ROOT, ...a);\nconst read = (f) => fs.readFileSync(f, 'utf8');\nconst ls = (d) => (fs.existsSync(d) ? fs.readdirSync(d) : []);\n\n/** Split YAML-ish frontmatter without a dependency. Returns {fm, body}. */\nfunction frontmatter(src) {\n  const m = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---\\r?\\n?/.exec(src);\n  if (!m) return { fm: null, body: src };\n  const fm = {};\n  let key = null;\n  for (const line of m[1].split(/\\r?\\n/)) {\n    const kv = /^([A-Za-z_][A-Za-z0-9_]*):\\s*(.*)$/.exec(line);\n    if (kv) { key = kv[1]; fm[key] = kv[2]; }\n    else if (key && /^\\s+\\S/.test(line)) fm[key] = `${fm[key]} ${line.trim()}`.trim();\n  }\n  return { fm, body: src.slice(m[0].length) };\n}\n\nconst SKILL_DIRS = ls(p('skills')).filter((n) => fs.existsSync(p('skills', n, 'SKILL.md')));\nconst AGENT_FILES = ls(p('agents')).filter((n) => n.endsWith('.md'));\nconst COMMAND_FILES = ls(p('commands')).filter((n) => n.endsWith('.md'));\nconst CODEX_AGENTS = ls(p('codex', 'agents')).filter((n) => n.endsWith('.toml'));\n\n// Keep these in step with penny-kit/SKILL.md and doctor-checks.md, which quote\n// the counts to the user.\nconst EXPECTED = { skills: 19, agents: 14, commands: 7, codexAgents: 14 };\n\n// ----------------------------------------------------------------- inventory\n\ntest('inventory matches the documented counts', () => {\n  assert.equal(SKILL_DIRS.length, EXPECTED.skills, `skills: ${SKILL_DIRS.join(', ')}`);\n  assert.equal(AGENT_FILES.length, EXPECTED.agents, `agents: ${AGENT_FILES.join(', ')}`);\n  assert.equal(COMMAND_FILES.length, EXPECTED.commands, `commands: ${COMMAND_FILES.join(', ')}`);\n  assert.equal(CODEX_AGENTS.length, EXPECTED.codexAgents, `codex agents: ${CODEX_AGENTS.join(', ')}`);\n});\n\ntest('the four workflow skills exist', () => {\n  for (const n of ['penny', 'penny-build', 'penny-council', 'penny-kit']) {\n    assert.ok(SKILL_DIRS.includes(n), `missing skill: ${n}`);\n  }\n  assert.equal(SKILL_DIRS.filter((n) => n.startsWith('miser-')).length, 15);\n});\n\n// -------------------------------------------------------------------- skills\n\ntest('every skill has valid frontmatter whose name matches its directory', () => {\n  for (const dir of SKILL_DIRS) {\n    const { fm } = frontmatter(read(p('skills', dir, 'SKILL.md')));\n    assert.ok(fm, `${dir}: no frontmatter`);\n    assert.equal(fm.name, dir, `${dir}: frontmatter name is \"${fm.name}\"`);\n    assert.ok(fm.description, `${dir}: no description`);\n    // The description is the only thing loaded every session, so it has to\n    // actually say when to fire. Too short and the model never reaches for it.\n    assert.ok(fm.description.length > 60, `${dir}: description too short to route on`);\n    assert.ok(fm.description.length < 1400, `${dir}: description is a standing per-session cost`);\n  }\n});\n\n// -------------------------------------------------------------------- agents\n\n/** The model policy: no subagent runs on Opus, and every one is pinned. */\ntest('every Claude agent pins a model, and none of them is opus', () => {\n  for (const f of AGENT_FILES) {\n    const { fm } = frontmatter(read(p('agents', f)));\n    assert.ok(fm, `${f}: no frontmatter`);\n    assert.ok(fm.name, `${f}: no name`);\n    assert.ok(fm.description, `${f}: no description`);\n    assert.ok(fm.model, `${f}: no model pin \u2014 it would inherit the orchestrator's`);\n    assert.ok(\n      ['sonnet', 'haiku'].includes(fm.model),\n      `${f}: model is \"${fm.model}\" \u2014 subagents run sonnet or haiku (see penny-kit/references/model-policy.md)`,\n    );\n  }\n});\n\ntest('agent names are unique and match their filenames', () => {\n  const seen = new Set();\n  for (const f of AGENT_FILES) {\n    const { fm } = frontmatter(read(p('agents', f)));\n    assert.equal(fm.name, f.replace(/\\.md$/, ''), `${f}: name does not match filename`);\n    assert.ok(!seen.has(fm.name), `duplicate agent name: ${fm.name}`);\n    seen.add(fm.name);\n    assert.ok(!fm.name.includes(':'), `${f}: \":\" is reserved for plugin-scoped ids`);\n  }\n});\n\ntest('haiku agents do not set effort', () => {\n  // Effort levels are model-dependent and the haiku alias has pointed at models\n  // that reject the parameter. Omitting it lets the agent launch either way.\n  for (const f of AGENT_FILES) {\n    const { fm } = frontmatter(read(p('agents', f)));\n    if (fm.model === 'haiku') {\n      assert.equal(fm.effort, undefined, `${f}: haiku agent sets effort: ${fm.effort}`);\n    }\n  }\n});\n\ntest('sonnet agents set a valid effort', () => {\n  for (const f of AGENT_FILES) {\n    const { fm } = frontmatter(read(p('agents', f)));\n    if (fm.model === 'sonnet') {\n      assert.ok(fm.effort, `${f}: sonnet agent with no effort \u2014 it resolves from a lower-priority source`);\n      assert.ok(['low', 'medium', 'high', 'xhigh', 'max'].includes(fm.effort), `${f}: bad effort \"${fm.effort}\"`);\n    }\n  }\n});\n\ntest('every agent is bounded by maxTurns and a tools allowlist', () => {\n  for (const f of AGENT_FILES) {\n    const { fm } = frontmatter(read(p('agents', f)));\n    assert.ok(fm.maxTurns, `${f}: no maxTurns \u2014 a looping agent bills every turn at full context`);\n    assert.ok(Number(fm.maxTurns) > 0 && Number(fm.maxTurns) <= 100, `${f}: implausible maxTurns ${fm.maxTurns}`);\n    assert.ok(fm.tools, `${f}: no tools allowlist \u2014 the allowlist is the token budget`);\n  }\n});\n\ntest('read-only agents cannot write', () => {\n  // scout-agent is the only agent that must be incapable of editing, because it\n  // is spawned speculatively and its brief is the only thing bounding it.\n  const { fm } = frontmatter(read(p('agents', 'scout-agent.md')));\n  assert.ok(!/\\bWrite\\b|\\bEdit\\b/.test(fm.tools), `scout-agent tools include a write tool: ${fm.tools}`);\n});\n\n// --------------------------------------------------------------- codex agents\n\ntest('every Codex agent has the three required fields', () => {\n  for (const f of CODEX_AGENTS) {\n    const src = read(p('codex', 'agents', f));\n    for (const key of ['name', 'description', 'developer_instructions']) {\n      assert.match(src, new RegExp(`^${key}\\\\s*=`, 'm'), `${f}: missing required field \"${key}\"`);\n    }\n  }\n});\n\ntest('every Codex agent pins model AND effort together', () => {\n  // The half-pin trap: Codex resolves the two independently, so a file setting\n  // only `model` keeps an effort resolved from the [agents] default or the\n  // parent \u2014 and a cheap-model agent silently inherits the parent's xhigh.\n  for (const f of CODEX_AGENTS) {\n    const src = read(p('codex', 'agents', f));\n    const hasModel = /^model\\s*=/m.test(src);\n    const hasEffort = /^model_reasoning_effort\\s*=/m.test(src);\n    assert.equal(hasModel, hasEffort, `${f}: sets one of model/model_reasoning_effort but not both`);\n    assert.ok(hasModel, `${f}: no model pin`);\n  }\n});\n\ntest('Codex agent TOML has balanced multi-line strings', () => {\n  for (const f of CODEX_AGENTS) {\n    const src = read(p('codex', 'agents', f));\n    const n = (src.match(/\"\"\"/g) || []).length;\n    assert.equal(n % 2, 0, `${f}: unbalanced \"\"\" (${n})`);\n  }\n});\n\ntest('Codex agent top-level keys precede any table header', () => {\n  // TOML puts every bare key after a [table] header inside that table, which\n  // would silently move developer_instructions out of the agent definition.\n  for (const f of CODEX_AGENTS) {\n    const lines = read(p('codex', 'agents', f)).split(/\\r?\\n/);\n    let sawTable = false;\n    let inString = false;\n    for (const [i, line] of lines.entries()) {\n      if ((line.match(/\"\"\"/g) || []).length % 2 === 1) inString = !inString;\n      if (inString) continue;\n      if (/^\\s*\\[/.test(line)) sawTable = true;\n      else if (sawTable && /^[A-Za-z_][A-Za-z0-9_.]*\\s*=/.test(line)) {\n        assert.fail(`${f}:${i + 1}: top-level key after a table header \u2014 it lands inside the table`);\n      }\n    }\n  }\n});\n\ntest('Codex agent names are unique', () => {\n  const seen = new Set();\n  for (const f of CODEX_AGENTS) {\n    const name = /^name\\s*=\\s*\"([^\"]+)\"/m.exec(read(p('codex', 'agents', f)))?.[1];\n    assert.ok(name, `${f}: unparseable name`);\n    assert.ok(!seen.has(name), `duplicate Codex agent name: ${name}`);\n    seen.add(name);\n  }\n});\n\n// ------------------------------------------------------------------ commands\n\ntest('every command has a description and references a real skill', () => {\n  for (const f of COMMAND_FILES) {\n    const src = read(p('commands', f));\n    const { fm, body } = frontmatter(src);\n    assert.ok(fm, `${f}: no frontmatter`);\n    assert.ok(fm.description, `${f}: no description`);\n    for (const name of body.match(/`(penny[a-z-]*)`\\s+skill/g) || []) {\n      const skill = /`([^`]+)`/.exec(name)[1];\n      assert.ok(SKILL_DIRS.includes(skill), `${f}: references missing skill \"${skill}\"`);\n    }\n  }\n});\n\n// ---------------------------------------------------- cross-reference checks\n\ntest('referenced skill files all exist', () => {\n  // A contract path that does not resolve means a subagent silently runs with no\n  // contract, which is the single worst failure mode in the whole design.\n  const refs = new Set();\n  const walk = (dir) => {\n    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n      const full = path.join(dir, e.name);\n      if (e.isDirectory()) walk(full);\n      else if (/\\.(md|sample)$/.test(e.name)) {\n        for (const m of read(full).matchAll(/`((?:references|templates)\\/[A-Za-z0-9_.-]+\\.md)`/g)) {\n          refs.add([path.dirname(full), m[1]].join('\\0'));\n        }\n      }\n    }\n  };\n  walk(p('skills'));\n  for (const ref of refs) {\n    const [dir, rel] = ref.split('\\0');\n    assert.ok(fs.existsSync(path.join(dir, rel)), `${dir}: references missing ${rel}`);\n  }\n});\n\ntest('no stale pre-rename identifiers remain', () => {\n  const stale = [/\\bagentic-app-loop\\b/, /\\bagent-kit\\b/, /`build-app`/, /\\/kit-(setup|doctor|help)\\b/];\n  const offenders = [];\n  const walk = (dir) => {\n    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n      if (e.name === 'node_modules' || e.name === '.git') continue;\n      const full = path.join(dir, e.name);\n      if (e.isDirectory()) walk(full);\n      else if (/\\.(md|mjs|toml|json|sample)$/.test(e.name)) {\n        const src = read(full);\n        for (const re of stale) {\n          // package.json legitimately carries the repository URL until the\n          // GitHub repo itself is renamed.\n          if (re.test(src) && !full.endsWith('package.json')) {\n            offenders.push(`${path.relative(ROOT, full)}: ${re}`);\n          }\n        }\n      }\n    }\n  };\n  for (const d of ['skills', 'agents', 'commands', 'codex', 'bin', 'reference']) walk(p(d));\n  assert.deepEqual(offenders, [], `stale identifiers:\\n  ${offenders.join('\\n  ')}`);\n});\n\n// -------------------------------------------------------------- runtime bits\n\ntest('bundled scripts and the hook are present and executable as claimed', () => {\n  for (const f of ['scripts/context-report.sh', 'scripts/miser-bench.mjs', 'scripts/rates.json',\n                   'hooks/filter-tool-output.py', 'reference/techniques.md']) {\n    assert.ok(fs.existsSync(p(f)), `missing ${f}`);\n    assert.ok(fs.statSync(p(f)).size > 0, `empty ${f}`);\n  }\n});\n\ntest('manifests agree on the plugin name', () => {\n  const plugin = JSON.parse(read(p('.claude-plugin', 'plugin.json')));\n  const market = JSON.parse(read(p('.claude-plugin', 'marketplace.json')));\n  const pkg = JSON.parse(read(p('package.json')));\n  assert.equal(plugin.name, 'pennywright');\n  assert.equal(pkg.name, 'pennywright');\n  assert.equal(market.plugins[0].name, 'pennywright');\n  assert.ok(pkg.bin.penny, 'package.json does not expose the `penny` binary');\n  assert.ok(fs.existsSync(p(pkg.bin.penny)), `bin target missing: ${pkg.bin.penny}`);\n});\n\ntest('package.json files[] covers every shipped directory', () => {\n  const pkg = JSON.parse(read(p('package.json')));\n  for (const d of ['bin/', 'skills/', 'agents/', 'commands/', 'codex/', 'scripts/', 'hooks/', 'reference/']) {\n    assert.ok(pkg.files.includes(d), `package.json files[] is missing ${d}`);\n  }\n});\n"
  }
}
