#!/usr/bin/env node
/**
 * agentic-app-loop installer.
 *
 *   npx github:Srinivasan-78/agentic-app-loop install          both runtimes it finds
 *   ... install --claude            Claude Code only
 *   ... install --codex             Codex only
 *   ... install --project           repo scope instead of machine scope
 *   ... install --hook              also wire the tool-output filter hook
 *   ... status | doctor | uninstall
 *   ... audit | report --since 7d   the measurement scripts
 *
 * The bare npm name is taken by another author's package, so the `github:` form
 * above is the Node path. No-Node alternative: install by hand, see README.
 *
 * No dependencies. Node >= 18.17. Nothing is written without consent: every
 * mutation is listed first and needs a y/N answer (or --yes).
 */

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import readline from 'node:readline';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const PKG_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const HOME = os.homedir();
const CLAUDE_HOME = process.env.CLAUDE_CONFIG_DIR
  ? path.resolve(process.env.CLAUDE_CONFIG_DIR)
  : path.join(HOME, '.claude');
const CODEX_HOME = process.env.CODEX_HOME
  ? path.resolve(process.env.CODEX_HOME)
  : path.join(HOME, '.codex');
const AGENTS_HOME = path.join(HOME, '.agents');

/** Skills that are portable across runtimes. The loop/council/agent-kit skills
 *  are written against Claude Code's Agent tool and slash commands; Codex gets
 *  the same protocols through AGENTS.md plus the reference files instead. */
const PORTABLE = (name) => name.startsWith('miser-');

// ---------------------------------------------------------------- arg parsing

const argv = process.argv.slice(2);
const cmd = (argv[0] || '').replace(/^--?/, '') || 'help';
const rest = argv.slice(1);
const has = (...names) => names.some((n) => rest.includes(n));
const valueOf = (name, fallback = null) => {
  const eq = rest.find((a) => a.startsWith(name + '='));
  if (eq) return eq.slice(name.length + 1);
  const i = rest.indexOf(name);
  return i !== -1 && rest[i + 1] && !rest[i + 1].startsWith('-') ? rest[i + 1] : fallback;
};

const wantClaude = has('--claude');
const wantCodex = has('--codex');

const opts = {
  scope: has('--project', '-p') ? 'project' : 'user',
  mode: has('--copy') ? 'copy' : has('--link') ? 'link' : 'auto',
  only: (valueOf('--only') || '').split(',').map((s) => s.trim()).filter(Boolean),
  hook: has('--hook'),
  yes: has('--yes', '-y') || !process.stdin.isTTY,
  dryRun: has('--dry-run', '-n'),
  quiet: has('--quiet', '-q'),
};

// ------------------------------------------------------------------ utilities

const C = process.stdout.isTTY && !process.env.NO_COLOR
  ? { dim: (s) => `\x1b[2m${s}\x1b[0m`, b: (s) => `\x1b[1m${s}\x1b[0m`, g: (s) => `\x1b[32m${s}\x1b[0m`, y: (s) => `\x1b[33m${s}\x1b[0m`, r: (s) => `\x1b[31m${s}\x1b[0m` }
  : { dim: (s) => s, b: (s) => s, g: (s) => s, y: (s) => s, r: (s) => s };

const say = (...a) => { if (!opts.quiet) console.log(...a); };
const warn = (...a) => console.error(C.y('!'), ...a);
const die = (msg, code = 1) => { console.error(C.r('error:'), msg); process.exit(code); };

function ask(question) {
  if (opts.yes) return Promise.resolve(true);
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  return new Promise((resolve) => {
    rl.question(`${question} ${C.dim('[y/N]')} `, (a) => { rl.close(); resolve(/^y(es)?$/i.test(a.trim())); });
  });
}

/** npx unpacks into a cache directory that is garbage-collected, so a symlink
 *  into it dangles later. Copy from anywhere volatile, link from a checkout. */
function resolveMode() {
  if (opts.mode !== 'auto') return opts.mode;
  const volatile = /[\\/](_npx|\.npm[\\/]_cacache|node_modules)[\\/]/.test(PKG_ROOT + path.sep);
  return volatile ? 'copy' : 'link';
}

const rmrf = (p) => fs.rmSync(p, { recursive: true, force: true });
const exists = (p) => fs.existsSync(p);
const readJson = (file) => { try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; } };
const backup = (file) => {
  const bak = `${file}.bak-${new Date().toISOString().replace(/[:.]/g, '-')}`;
  fs.copyFileSync(file, bak);
  return bak;
};
const pyBin = process.platform === 'win32' ? 'python' : 'python3';

function describeExisting(dest) {
  let st;
  try { st = fs.lstatSync(dest); } catch { return null; }
  if (st.isSymbolicLink()) {
    let target = '(unreadable)';
    try { target = fs.readlinkSync(dest); } catch { /* ignore */ }
    return { kind: 'link', target, dangling: !exists(dest) };
  }
  return { kind: st.isDirectory() ? 'dir' : 'file' };
}

function place(src, dest, mode) {
  rmrf(dest);
  if (mode === 'link') fs.symlinkSync(src, dest, 'junction');
  else fs.cpSync(src, dest, { recursive: true });
}

function skillNames() {
  const dir = path.join(PKG_ROOT, 'skills');
  if (!exists(dir)) die(`no skills/ directory in ${PKG_ROOT}`);
  let names = fs.readdirSync(dir).filter((n) => exists(path.join(dir, n, 'SKILL.md')));
  if (opts.only.length) {
    const want = new Set(opts.only);
    const missing = [...want].filter((w) => !names.includes(w));
    if (missing.length) die(`unknown skill(s): ${missing.join(', ')}\navailable: ${names.join(', ')}`);
    names = names.filter((n) => want.has(n));
  }
  return names.sort();
}

/** Which runtimes to act on. Explicit flags win; otherwise detect. */
function targets() {
  if (wantClaude || wantCodex) return { claude: wantClaude, codex: wantCodex };
  const claude = exists(CLAUDE_HOME) || !!which('claude');
  const codex = exists(CODEX_HOME) || !!which('codex');
  return { claude, codex };
}

function which(bin) {
  const probe = process.platform === 'win32' ? 'where' : 'command';
  const args = process.platform === 'win32' ? [bin] : ['-v', bin];
  const r = spawnSync(probe, args, { encoding: 'utf8', shell: process.platform !== 'win32' });
  return r.status === 0 ? (r.stdout || '').trim().split(/\r?\n/)[0] : null;
}

// -------------------------------------------------------------------- install

async function install() {
  const t = targets();
  if (!t.claude && !t.codex) {
    die('found neither Claude Code nor Codex on this machine.\n' +
        '       pass --claude or --codex to install anyway.');
  }

  const mode = resolveMode();
  const names = skillNames();
  const plan = [];

  // --- Claude Code -------------------------------------------------------
  const claudeSkills = opts.scope === 'project'
    ? path.join(process.cwd(), '.claude', 'skills')
    : path.join(CLAUDE_HOME, 'skills');
  if (t.claude) {
    for (const name of names) {
      const dest = path.join(claudeSkills, name);
      const was = describeExisting(dest);
      plan.push({
        kind: 'skill', runtime: 'claude', name,
        src: path.join(PKG_ROOT, 'skills', name), dest,
        action: was ? (was.kind === 'link' ? 'relink' : 'replace') : 'install',
      });
    }
  }

  // --- Codex -------------------------------------------------------------
  const codexSkills = opts.scope === 'project'
    ? path.join(process.cwd(), '.agents', 'skills')
    : path.join(AGENTS_HOME, 'skills');
  const codexAgents = opts.scope === 'project'
    ? path.join(process.cwd(), '.codex', 'agents')
    : path.join(CODEX_HOME, 'agents');
  if (t.codex) {
    for (const name of names.filter(PORTABLE)) {
      const dest = path.join(codexSkills, name);
      const was = describeExisting(dest);
      plan.push({
        kind: 'skill', runtime: 'codex', name,
        src: path.join(PKG_ROOT, 'skills', name), dest,
        action: was ? (was.kind === 'link' ? 'relink' : 'replace') : 'install',
      });
    }
    const agentSrc = path.join(PKG_ROOT, 'codex', 'agents');
    for (const f of exists(agentSrc) ? fs.readdirSync(agentSrc).filter((n) => n.endsWith('.toml')) : []) {
      plan.push({
        kind: 'agent', runtime: 'codex', name: f,
        src: path.join(agentSrc, f), dest: path.join(codexAgents, f),
        action: exists(path.join(codexAgents, f)) ? 'replace' : 'install',
      });
    }
  }

  // --- report the plan ---------------------------------------------------
  say(C.b('agentic-app-loop install'));
  say(`  source   ${C.dim(PKG_ROOT)}`);
  say(`  runtimes ${[t.claude && 'claude', t.codex && 'codex'].filter(Boolean).join(', ')}`);
  say(`  scope    ${opts.scope}`);
  say(`  mode     ${mode}${opts.mode === 'auto' ? C.dim(' (auto)') : ''}`);
  say('');
  for (const p of plan) {
    const note = p.action === 'replace' && p.kind === 'skill' ? C.y('  overwrites a real directory') : '';
    say(`  ${p.runtime.padEnd(7)} ${p.action.padEnd(8)} ${p.kind.padEnd(5)} ${p.name}${note}`);
  }
  if (t.codex) {
    say(`  ${'codex'.padEnd(7)} ${'copy'.padEnd(8)} ${'ref'.padEnd(5)} protocol + contract files`);
    say(`  ${'codex'.padEnd(7)} ${'manual'.padEnd(8)} ${'conf'.padEnd(5)} ${C.dim('config.toml / AGENTS.md are NOT written — see next steps')}`);
  }
  if (opts.hook && t.claude) {
    say(`  ${'claude'.padEnd(7)} ${'install'.padEnd(8)} ${'hook'.padEnd(5)} filter-tool-output.py`);
    say(`  ${'claude'.padEnd(7)} ${'edit'.padEnd(8)} ${'conf'.padEnd(5)} settings.json PreToolUse/Bash ${C.dim('(backed up first)')}`);
  }
  say('');

  if (opts.dryRun) { say(C.dim('dry run — nothing written')); return; }

  const replacing = plan.filter((p) => p.action === 'replace' && p.kind === 'skill');
  if (replacing.length) {
    warn(`${replacing.length} real director${replacing.length === 1 ? 'y' : 'ies'} will be replaced: ${replacing.map((p) => p.name).join(', ')}`);
  }
  if (!(await ask(`Write ${plan.length} item${plan.length === 1 ? '' : 's'}${opts.hook ? ' and the hook' : ''}?`))) {
    say('aborted'); return;
  }

  // --- apply -------------------------------------------------------------
  for (const p of plan) {
    fs.mkdirSync(path.dirname(p.dest), { recursive: true });
    if (p.kind === 'agent') { fs.copyFileSync(p.src, p.dest); }
    else { place(p.src, p.dest, mode); }
    say(`  ${C.g('ok')} ${p.runtime} ${p.name}`);
  }

  // Scripts, hooks and reference files must live somewhere durable: in copy
  // mode the package itself is an npx temp dir that gets garbage-collected.
  let kitRoot = PKG_ROOT;
  if (mode === 'copy') {
    kitRoot = path.join(CLAUDE_HOME, 'agentic-app-loop');
    for (const sub of ['scripts', 'hooks', 'reference']) {
      const src = path.join(PKG_ROOT, sub);
      if (!exists(src)) continue;
      place(src, path.join(kitRoot, sub), 'copy');
    }
    say(`  ${C.g('ok')} scripts -> ${kitRoot}`);
  }

  if (t.codex) {
    const refDst = path.join(CODEX_HOME, 'agentic-app-loop', 'references');
    fs.mkdirSync(refDst, { recursive: true });
    const refs = [
      ['skills', 'build-app', 'references', 'phase-contracts.md'],
      ['skills', 'build-app', 'references', 'state-schema.md'],
      ['skills', 'council', 'references', 'council-protocol.md'],
      ['skills', 'agent-kit', 'references', 'model-policy.md'],
    ];
    for (const parts of refs) {
      const src = path.join(PKG_ROOT, ...parts);
      if (exists(src)) fs.copyFileSync(src, path.join(refDst, parts[parts.length - 1]));
    }
    say(`  ${C.g('ok')} codex references -> ${refDst}`);
  }

  if (opts.hook && t.claude) await installHook();

  // --- next steps --------------------------------------------------------
  say('');
  say(C.b('done.'));
  say('');
  say('next:');
  say(`  ${C.dim('#')} the skills call scripts from $AGENT_KIT — export it`);
  say(`  export AGENT_KIT="${kitRoot}"   ${C.dim('# add to ~/.bashrc or ~/.zshrc')}`);
  if (mode === 'copy') say(C.dim('  (copy mode: re-run the installer to pick up a new version)'));
  if (t.claude) {
    say('');
    say(`  ${C.b('claude')}  restart it, then:  ${C.b('/kit-setup')}  then  ${C.b('/kit-doctor')}`);
  }
  if (t.codex) {
    say('');
    say(`  ${C.b('codex')}   two files are deliberately NOT written, because merging them`);
    say(`          wrongly would break your config. Merge them by hand:`);
    say(`            ${path.join(PKG_ROOT, 'codex', 'config.toml.sample')}`);
    say(`              -> ${path.join(CODEX_HOME, 'config.toml')}`);
    say(`            ${path.join(PKG_ROOT, 'codex', 'AGENTS.md.sample')}`);
    say(`              -> ./AGENTS.md  (or ${path.join(CODEX_HOME, 'AGENTS.md')})`);
    say(`          Or let the agent do it: ${C.b('/kit-setup codex')} in Claude Code.`);
  }
}

async function installHook() {
  const src = path.join(PKG_ROOT, 'hooks', 'filter-tool-output.py');
  if (!exists(src)) { warn(`hook source missing: ${src}`); return; }
  const hookDir = path.join(CLAUDE_HOME, 'hooks');
  const dst = path.join(hookDir, 'filter-tool-output.py');
  fs.mkdirSync(hookDir, { recursive: true });
  fs.copyFileSync(src, dst);
  try { fs.chmodSync(dst, 0o755); } catch { /* windows */ }
  say(`  ${C.g('ok')} hook -> ${dst}`);

  const settingsFile = path.join(CLAUDE_HOME, 'settings.json');
  if (exists(settingsFile) && readJson(settingsFile) === null) {
    warn(`${settingsFile} is not valid JSON — leaving it alone. Add the PreToolUse entry by hand.`);
    return;
  }
  const settings = readJson(settingsFile) || {};
  settings.hooks ||= {};
  settings.hooks.PreToolUse ||= [];
  const already = settings.hooks.PreToolUse.some((e) =>
    (e.hooks || []).some((h) => typeof h.command === 'string' && h.command.includes('filter-tool-output.py')));
  if (already) { say(`  ${C.dim('=')} settings.json already wires the hook`); return; }
  settings.hooks.PreToolUse.push({
    matcher: 'Bash',
    hooks: [{ type: 'command', command: `${pyBin} "${dst}"` }],
  });
  if (exists(settingsFile)) say(`  ${C.dim('backup')} ${backup(settingsFile)}`);
  fs.writeFileSync(settingsFile, JSON.stringify(settings, null, 2) + '\n');
  say(`  ${C.g('ok')} settings.json PreToolUse/Bash`);
}

// ------------------------------------------------------------------ uninstall

async function uninstall() {
  const names = new Set(skillNames());
  const roots = [
    path.join(CLAUDE_HOME, 'skills'),
    path.join(process.cwd(), '.claude', 'skills'),
    path.join(AGENTS_HOME, 'skills'),
    path.join(process.cwd(), '.agents', 'skills'),
  ];
  const found = [];
  for (const root of roots) {
    if (!exists(root)) continue;
    for (const n of fs.readdirSync(root)) if (names.has(n)) found.push(path.join(root, n));
  }
  const agentRoots = [path.join(CODEX_HOME, 'agents'), path.join(process.cwd(), '.codex', 'agents')];
  const ours = new Set(exists(path.join(PKG_ROOT, 'codex', 'agents'))
    ? fs.readdirSync(path.join(PKG_ROOT, 'codex', 'agents'))
    : []);
  for (const root of agentRoots) {
    if (!exists(root)) continue;
    for (const f of fs.readdirSync(root)) if (ours.has(f)) found.push(path.join(root, f));
  }

  if (!found.length) { say('nothing to remove'); return; }
  say(C.b('agentic-app-loop uninstall'));
  for (const f of found) say(`  remove ${f}`);
  if (opts.dryRun) { say(C.dim('dry run — nothing removed')); return; }
  if (!(await ask(`Remove ${found.length} item${found.length === 1 ? '' : 's'}?`))) { say('aborted'); return; }
  for (const f of found) { rmrf(f); say(`  ${C.g('ok')} ${path.basename(f)}`); }

  say('');
  say(C.dim('left alone — these hold your own edits, remove by hand if you want:'));
  say(C.dim(`  ${path.join(CLAUDE_HOME, 'agentic-app-loop')}            # copied scripts`));
  say(C.dim(`  ${path.join(CODEX_HOME, 'agentic-app-loop')}             # copied references`));
  say(C.dim(`  ${path.join(CLAUDE_HOME, 'hooks', 'filter-tool-output.py')}   # then drop the PreToolUse entry`));
  say(C.dim(`  settings.json / config.toml / AGENTS.md entries`));
}

// --------------------------------------------------------------------- status

function status() {
  say(C.b('agentic-app-loop status'));
  say(`  package  ${C.dim(PKG_ROOT)}`);
  const names = new Set(skillNames());
  let total = 0;

  const roots = [
    ['claude user   ', path.join(CLAUDE_HOME, 'skills')],
    ['claude project', path.join(process.cwd(), '.claude', 'skills')],
    ['codex  user   ', path.join(AGENTS_HOME, 'skills')],
    ['codex  project', path.join(process.cwd(), '.agents', 'skills')],
  ];
  for (const [label, root] of roots) {
    const found = exists(root) ? fs.readdirSync(root).filter((n) => names.has(n)).sort() : [];
    total += found.length;
    say(`\n  ${label}  ${C.dim(root)}  ${found.length} skill${found.length === 1 ? '' : 's'}`);
    for (const n of found) {
      const info = describeExisting(path.join(root, n));
      const detail = info?.kind === 'link'
        ? (info.dangling ? C.r('DANGLING -> ' + info.target) : C.dim('-> ' + info.target))
        : C.dim('(copy)');
      say(`    ${n.padEnd(18)} ${detail}`);
    }
  }

  for (const [label, root] of [['codex  user   ', path.join(CODEX_HOME, 'agents')],
                               ['codex  project', path.join(process.cwd(), '.codex', 'agents')]]) {
    const n = exists(root) ? fs.readdirSync(root).filter((f) => f.endsWith('.toml')).length : 0;
    say(`\n  ${label}  ${C.dim(root)}  ${n} agent file${n === 1 ? '' : 's'}`);
  }

  const hookDst = path.join(CLAUDE_HOME, 'hooks', 'filter-tool-output.py');
  const settings = readJson(path.join(CLAUDE_HOME, 'settings.json')) || {};
  const wired = (settings.hooks?.PreToolUse || []).some((e) =>
    (e.hooks || []).some((h) => String(h.command || '').includes('filter-tool-output.py')));
  const hookOk = exists(hookDst);
  say('');
  say(`  hook     file ${hookOk ? C.g('present') : C.dim('absent')}   settings.json ${wired ? C.g('wired') : C.dim('not wired')}`);
  if (wired !== hookOk) say(`           ${C.r('MISMATCH')} — the filter is doing nothing. run: install --hook`);
  say(`  skills advertised every session: ~${total * 100} tokens (${total} x ~100)`);
}

// --------------------------------------------------------------------- doctor

function doctor() {
  const rows = [];
  const add = (level, name, detail) => rows.push([level, name, detail]);

  // Section A — the silent killers.
  const forcedEffort = process.env.CLAUDE_CODE_EFFORT_LEVEL;
  const flattens = forcedEffort && !['auto', 'unset'].includes(forcedEffort);
  add(flattens ? 'fail' : 'ok', 'forced effort',
    flattens ? `CLAUDE_CODE_EFFORT_LEVEL=${forcedEffort} overrides every agent's effort — tiers are flat`
             : `CLAUDE_CODE_EFFORT_LEVEL ${forcedEffort || 'unset'}`);

  const forcedModel = process.env.CLAUDE_CODE_SUBAGENT_MODEL_FORCE === '1';
  add(forcedModel ? 'fail' : 'ok', 'forced model',
    forcedModel ? "CLAUDE_CODE_SUBAGENT_MODEL_FORCE=1 overrides every agent's model" : 'not forced');

  const hookDst = path.join(CLAUDE_HOME, 'hooks', 'filter-tool-output.py');
  const settings = readJson(path.join(CLAUDE_HOME, 'settings.json')) || {};
  const wired = (settings.hooks?.PreToolUse || []).some((e) =>
    (e.hooks || []).some((h) => String(h.command || '').includes('filter-tool-output.py')));
  const hookOk = exists(hookDst);
  add(hookOk && wired ? 'ok' : (hookOk || wired) ? 'fail' : 'warn', 'filter hook',
    hookOk && wired ? 'present and wired'
      : wired ? 'settings.json references a file that is not there — every Bash result is unfiltered'
      : hookOk ? 'on disk but settings.json does not reference it — doing nothing'
      : 'not installed (run: install --hook)');

  const kit = process.env.AGENT_KIT || process.env.MISER
    || (exists(path.join(CLAUDE_HOME, 'agentic-app-loop')) ? path.join(CLAUDE_HOME, 'agentic-app-loop') : null);
  add(kit ? 'ok' : 'warn', '$AGENT_KIT', kit || 'unset — the skills\' script paths will not resolve');

  // Half-pinned agents, both runtimes.
  const claudeAgents = path.join(PKG_ROOT, 'agents');
  if (exists(claudeAgents)) {
    const files = fs.readdirSync(claudeAgents).filter((f) => f.endsWith('.md'));
    const half = files.filter((f) => {
      const src = fs.readFileSync(path.join(claudeAgents, f), 'utf8').split(/^---$/m)[1] || '';
      return !/^model:/m.test(src);
    });
    add(half.length ? 'warn' : 'ok', 'claude agents',
      half.length ? `${half.length}/${files.length} without a pinned model: ${half.join(', ')}`
                  : `${files.length} agents, all with a pinned model`);
  }
  for (const root of [path.join(CODEX_HOME, 'agents'), path.join(PKG_ROOT, 'codex', 'agents')]) {
    if (!exists(root)) continue;
    const files = fs.readdirSync(root).filter((f) => f.endsWith('.toml'));
    if (!files.length) continue;
    const half = files.filter((f) => {
      const src = fs.readFileSync(path.join(root, f), 'utf8');
      return /^model\s*=/m.test(src) !== /^model_reasoning_effort\s*=/m.test(src);
    });
    add(half.length ? 'fail' : 'ok', 'codex agents',
      half.length ? `${half.length} set one of model/effort but not both — the unset half inherits the parent: ${half.join(', ')}`
                  : `${files.length} agent files in ${root}, all fully pinned`);
    break;
  }

  // Duplicate skills across roots — paid for twice every session.
  const seen = new Map();
  for (const root of [path.join(CLAUDE_HOME, 'skills'), path.join(process.cwd(), '.claude', 'skills'), path.join(AGENTS_HOME, 'skills')]) {
    if (!exists(root)) continue;
    for (const n of fs.readdirSync(root)) {
      if (!exists(path.join(root, n, 'SKILL.md'))) continue;
      seen.set(n, [...(seen.get(n) || []), root]);
    }
  }
  const dupes = [...seen entries()].filter(([, v]) => v.length > 1).map(([k]) => k);
  add(dupes.length ? 'warn' : 'ok', 'duplicate skills',
    dupes.length ? `advertised twice: ${dupes.join(', ')}` : 'none');

  // Stale advice from an earlier tokenmiser install.
  const mtt = settings.env?.MAX_THINKING_TOKENS ?? process.env.MAX_THINKING_TOKENS;
  add(mtt ? 'warn' : 'ok', 'MAX_THINKING_TOKENS',
    mtt ? `=${mtt} — ignored on adaptive-reasoning models, so it caps nothing. Use effort instead.` : 'not set');

  // Environment.
  const nodeOk = Number(process.versions.node.split('.')[0]) >= 18;
  add(nodeOk ? 'ok' : 'fail', 'node', `${process.versions.node}${nodeOk ? '' : ' — need >= 18.17'}`);
  const py = spawnSync(pyBin, ['--version'], { encoding: 'utf8' });
  add(py.status === 0 ? 'ok' : 'warn', 'python',
    py.status === 0 ? (py.stdout || py.stderr || '').trim() : `${pyBin} missing — the filter hook needs it`);

  const projects = path.join(CLAUDE_HOME, 'projects');
  const sessions = exists(projects)
    ? fs.readdirSync(projects).reduce((n, p) => {
        try { return n + fs.readdirSync(path.join(projects, p)).filter((f) => f.endsWith('.jsonl')).length; } catch { return n; }
      }, 0)
    : 0;
  add(sessions > 0 ? 'ok' : 'warn', 'session logs',
    sessions > 0 ? `${sessions} found` : 'none — there is nothing to measure yet');

  // --- print -------------------------------------------------------------
  const paint = { ok: C.g('ok  '), warn: C.y('warn'), fail: C.r('fail'), skip: C.dim('skip') };
  say(C.b('agentic-app-loop doctor'));
  for (const [level, name, detail] of rows) {
    say(`  ${paint[level]} ${name.padEnd(20)} ${level === 'ok' ? C.dim(detail) : detail}`);
  }
  const worst = rows.find(([l]) => l === 'fail') || rows.find(([l]) => l === 'warn');
  say('');
  if (worst) say(`highest-value fix: ${worst[1]} — ${worst[2]}`);
  else say(C.g('all checks passed.'));
  say(C.dim('for the measured half (cache share, per-turn tokens): run `report --since 7d`'));
  say(C.dim('in-session, pair this with /context, /usage and /cost'));
}

// ------------------------------------------------------- pass-through scripts

function passthrough(script, extra = []) {
  const file = path.join(PKG_ROOT, 'scripts', script);
  if (!exists(file)) die(`missing ${file}`);
  const isNode = script.endsWith('.mjs');
  const r = spawnSync(isNode ? process.execPath : 'bash', [file, ...extra, ...rest], {
    stdio: 'inherit',
    env: { ...process.env, AGENT_KIT: process.env.AGENT_KIT || PKG_ROOT, MISER: process.env.MISER || PKG_ROOT },
  });
  process.exit(r.status ?? 1);
}

// ----------------------------------------------------------------------- help

function help() {
  say(`${C.b('agentic-app-loop')} — orchestration + token kit for Claude Code and Codex

${C.b('install')}
  npx github:Srinivasan-78/agentic-app-loop install    both runtimes it finds
  loop install --claude | --codex          one runtime only
  loop install --hook                      also wire the tool-output filter
  loop install --project                   repo scope (./.claude, ./.codex)
  loop install --only miser-read,miser-git a subset of skills
  loop install --copy | --link             force copy or symlink (default: auto)
  loop install --dry-run                   print the plan, write nothing
  loop install --yes                       no prompt (implied when not a TTY)

${C.b('manage')}
  loop status                              what is installed, where, token cost
  loop doctor                              config checks, including the silent killers
  loop uninstall [--project]               remove what this installed

${C.b('measure')}
  loop audit                               always-on context report
  loop report --since 7d                   per-turn token usage from session logs
  loop bench <...>                         the full bench script

${C.dim('Codex config.toml and AGENTS.md are never written automatically — merging')}
${C.dim('them wrongly breaks your setup. The installer prints the two paths to')}
${C.dim('merge by hand, or run /kit-setup in Claude Code and let the agent do it.')}`);
}

// ------------------------------------------------------------------ dispatch

const table = {
  install, i: install,
  uninstall, remove: uninstall, rm: uninstall,
  status, ls: status, list: status,
  doctor,
  audit: () => passthrough('context-report.sh'),
  report: () => passthrough('miser-bench.mjs', ['report']),
  bench: () => passthrough('miser-bench.mjs'),
  help, h: help,
  version: () => say(readJson(path.join(PKG_ROOT, 'package.json'))?.version ?? 'unknown'),
  v: () => say(readJson(path.join(PKG_ROOT, 'package.json'))?.version ?? 'unknown'),
};

const fn = table[cmd];
if (!fn) { console.error(C.r(`unknown command: ${cmd}`)); help(); process.exit(1); }
await fn();

