test('Codex agent definition keys precede any table header', () => {
  // TOML puts every bare key after a [table] header inside that table. Keys
  // that belong to a table (features.apps, skills.config) are fine there; the
  // five that define the agent are not, and TOML would silently reparent them.
  const MUST_BE_TOP = /^(name|description|developer_instructions|model|model_reasoning_effort)\s*=/;
  for (const f of CODEX_AGENTS) {
