#!/usr/bin/env node
/** Pennywright repo audit. Run from the repo root. Reports issues; fixes nothing. */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const p = (...a) => path.join(ROOT, ...a);
const read = (f) => fs.readFileSync(f, 'utf8');
const ls = (d) => (fs.existsSync(d) ? fs.readdirSync(d) : []);
const issues = [];
const add = (cat, msg) => issues.push(`[${cat}] ${msg}`);

function fm(src) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(src);
  if (!m) return null;
  const o = {};
  let k = null;
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^([A-Za-z_][A-Za-z0-9_]*):\s*(.*)$/.exec(line);
    if (kv) { k = kv[1]; o[k] = kv[2]; }
    else if (k && /^\s+\S/.test(line)) o[k] = `${o[k]} ${line.trim()}`.trim();
  }
  return o;
}

const walk = (dir, out = []) => {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (['.git', 'node_modules'].includes(e.name)) continue;
    const f = path.join(dir, e.name);
    e.isDirectory() ? walk(f, out) : out.push(f);
  }
  return out;
};
const ALL = walk(ROOT);
const rel = (f) => path.relative(ROOT, f).replace(/\\/g, '/');

// ---------------------------------------------------------------- 1. skills
const SKILLS = ls(p('skills')).filter((n) => fs.existsSync(p('skills', n, 'SKILL.md')));
for (const d of SKILLS) {
  const f = fm(read(p('skills', d, 'SKILL.md')));
  if (!f) { add('skill', `${d}: no frontmatter`); continue; }
  if (f.name !== d) add('skill', `${d}: frontmatter name="${f.name}" != dir`);
  if (!f.description) add('skill', `${d}: no description`);
  const extra = Object.keys(f).filter((k) => !['name', 'description', 'allowed-tools', 'license'].includes(k));
  if (extra.length) add('skill', `${d}: unknown frontmatter keys: ${extra.join(', ')}`);
}

// ---------------------------------------------------------------- 2. agents
// Fields the Claude Code subagent schema accepts.
const AGENT_OK = new Set(['name', 'description', 'tools', 'disallowedTools', 'model', 'permissionMode',
  'maxTurns', 'autoCompactWindow', 'skills', 'mcpServers', 'hooks', 'memory', 'background',
  'omitClaudeMd', 'effort', 'isolation', 'color', 'initialPrompt', 'experimental']);
const COLORS = new Set(['red', 'blue', 'green', 'yellow', 'purple', 'orange', 'pink', 'cyan']);
const AGENTS = ls(p('agents')).filter((n) => n.endsWith('.md'));
const agentNames = new Set();
for (const a of AGENTS) {
  const f = fm(read(p('agents', a)));
  if (!f) { add('agent', `${a}: no frontmatter`); continue; }
  const base = a.replace(/\.md$/, '');
  if (f.name !== base) add('agent', `${a}: name="${f.name}" != filename`);
  agentNames.add(f.name);
  for (const k of Object.keys(f)) if (!AGENT_OK.has(k)) add('agent', `${a}: invalid field "${k}"`);
  if (!f.model) add('agent', `${a}: no model pin`);
  else if (!['sonnet', 'haiku'].includes(f.model)) add('agent', `${a}: model="${f.model}" (policy: sonnet|haiku)`);
  if (f.model === 'haiku' && f.effort) add('agent', `${a}: haiku must not set effort (=${f.effort})`);
  if (f.model === 'sonnet' && !f.effort) add('agent', `${a}: sonnet without effort`);
  if (f.effort && !['low', 'medium', 'high', 'xhigh', 'max'].includes(f.effort)) add('agent', `${a}: bad effort "${f.effort}"`);
  if (!f.maxTurns) add('agent', `${a}: no maxTurns`);
  else if (!/^\d+$/.test(f.maxTurns)) add('agent', `${a}: maxTurns not an integer: ${f.maxTurns}`);
  if (!f.tools) add('agent', `${a}: no tools allowlist`);
  if (f.color && !COLORS.has(f.color)) add('agent', `${a}: bad color "${f.color}"`);
  if (f.omitClaudeMd && !['true', 'false'].includes(f.omitClaudeMd)) add('agent', `${a}: omitClaudeMd not bool`);
}

// -------------------------------------------------------------- 3. commands
const CMDS = ls(p('commands')).filter((n) => n.endsWith('.md'));
const CMD_OK = new Set(['description', 'argument-hint', 'allowed-tools', 'model', 'disable-model-invocation', 'name']);
for (const c of CMDS) {
  const src = read(p('commands', c));
  const f = fm(src);
  if (!f) { add('command', `${c}: no frontmatter`); continue; }
  if (!f.description) add('command', `${c}: no description`);
  for (const k of Object.keys(f)) if (!CMD_OK.has(k)) add('command', `${c}: invalid field "${k}"`);
  if (/\$ARGUMENTS/.test(src) === false && !/penny-help|penny-doctor/.test(c)) {
    add('command', `${c}: no $ARGUMENTS placeholder`);
  }
}

// ----------------------------------------------------------- 4. codex agents
const CTOML = ls(p('codex', 'agents')).filter((n) => n.endsWith('.toml'));
const codexNames = new Set();
for (const t of CTOML) {
  const src = read(p('codex', 'agents', t));
  for (const k of ['name', 'description', 'developer_instructions']) {
    if (!new RegExp(`^${k}\\s*=`, 'm').test(src)) add('codex', `${t}: missing required "${k}"`);
  }
  const hasM = /^model\s*=/m.test(src), hasE = /^model_reasoning_effort\s*=/m.test(src);
  if (hasM !== hasE) add('codex', `${t}: half-pinned (model=${hasM} effort=${hasE})`);
  if ((src.match(/"""/g) || []).length % 2) add('codex', `${t}: unbalanced """`);
  const nm = /^name\s*=\s*"([^"]+)"/m.exec(src)?.[1];
  if (!nm) add('codex', `${t}: unparseable name`);
  else { if (codexNames.has(nm)) add('codex', `duplicate codex name ${nm}`); codexNames.add(nm); }
  const eff = /^model_reasoning_effort\s*=\s*"([^"]+)"/m.exec(src)?.[1];
  if (eff && !['low', 'medium', 'high', 'xhigh', 'max', 'ultra'].includes(eff)) add('codex', `${t}: bad effort "${eff}"`);
  // agent-defining keys must precede any [table]
  let sawTable = false, inStr = false;
  src.split(/\r?\n/).forEach((line, i) => {
    if ((line.match(/"""/g) || []).length % 2) inStr = !inStr;
    if (inStr) return;
    if (/^\s*\[/.test(line)) { sawTable = true; return; }
    if (sawTable && /^(name|description|developer_instructions|model|model_reasoning_effort)\s*=/.test(line)) {
      add('codex', `${t}:${i + 1}: agent key after a [table] header`);
    }
  });
}

// ------------------------------------------------- 5. dangling file references
for (const f of ALL.filter((x) => /\.(md|sample)$/.test(x))) {
  const src = read(f);
  const dir = path.dirname(f);
  for (const m of src.matchAll(/`((?:references|templates)\/[A-Za-z0-9_.\-]+\.md)`/g)) {
    if (!fs.existsSync(path.join(dir, m[1]))) add('ref', `${rel(f)}: missing ${m[1]}`);
  }
  // repo-root-relative paths in backticks
  for (const m of src.matchAll(/`((?:skills|agents|commands|codex|scripts|hooks|reference)\/[A-Za-z0-9_.\-\/]*\.(?:md|mjs|sh|py|json|toml|sample))`/g)) {
    if (!fs.existsSync(p(m[1]))) add('ref', `${rel(f)}: missing path ${m[1]}`);
  }
  // markdown links to local files
  for (const m of src.matchAll(/\]\((?!https?:|#)([^)]+)\)/g)) {
    const t = m[1].split('#')[0];
    if (t && !fs.existsSync(path.join(dir, t))) add('link', `${rel(f)}: broken link ${t}`);
  }
}

// ------------------------------------------------------ 6. agent-name mentions
for (const f of ALL.filter((x) => /\.(md|sample)$/.test(x))) {
  const src = read(f);
  for (const m of src.matchAll(/`(council-[a-z]+|[a-z]+-agent)`/g)) {
    if (!agentNames.has(m[1])) add('agentref', `${rel(f)}: references unknown agent \`${m[1]}\``);
  }
  for (const m of src.matchAll(/`(council_[a-z]+|[a-z]+_agent)`/g)) {
    if (!codexNames.has(m[1])) add('agentref', `${rel(f)}: references unknown codex agent \`${m[1]}\``);
  }
}

// ------------------------------------------------------- 7. skill-name mentions
for (const f of ALL.filter((x) => /\.(md|sample)$/.test(x))) {
  const src = read(f);
  for (const m of src.matchAll(/`\/(penny[a-z-]*|miser-[a-z]+)`/g)) {
    const n = m[1];
    const isCmd = CMDS.includes(`${n}.md`);
    const isSkill = SKILLS.includes(n);
    if (!isCmd && !isSkill) add('skillref', `${rel(f)}: /${n} is neither a command nor a skill`);
  }
}

// ---------------------------------------------------------- 8. stale identifiers
const STALE = [
  [/\bagentic-app-loop\b/, 'old repo/product name'],
  [/\bagent-kit\b/, 'old skill name'],
  [/`build-app`/, 'old skill name'],
  [/\/kit-(setup|doctor|help)\b/, 'old command name'],
  [/bin\/(penny|loop)\.mjs/, 'deleted installer'],
  [/npx (github:|tokenmiser)/, 'deleted install path'],
  [/@authormark v1 -- do not remove/, 'removed watermark'],
  [/\bAUTHORSHIP\.(json|log)\b/, 'deleted file'],
  [/REUSE\.toml/, 'deleted file'],
  [/package\.json files\[\]/, 'deleted file'],
];
for (const f of ALL.filter((x) => /\.(md|sample|toml|json|sh|py|mjs)$/.test(x))) {
  const src = read(f);
  for (const [re, why] of STALE) if (re.test(src)) add('stale', `${rel(f)}: ${re} (${why})`);
}

// ------------------------------------------------------------- 9. counts in docs
const counts = { skills: SKILLS.length, agents: AGENTS.length, commands: CMDS.length, codex: CTOML.length,
  miser: SKILLS.filter((s) => s.startsWith('miser-')).length };
const kit = read(p('skills', 'penny-kit', 'SKILL.md'));
const doc = read(p('skills', 'penny-kit', 'references', 'doctor-checks.md'));
if (!new RegExp(`${counts.skills} skills`).test(kit)) add('count', `penny-kit/SKILL.md does not state "${counts.skills} skills"`);
if (!new RegExp(`\\b${counts.skills}\\b`).test(doc.match(/\| B11 \|.*/)?.[0] || '')) add('count', `doctor-checks B11 skill count != ${counts.skills}`);
if (!new RegExp(`\\b${counts.agents}\\b`).test(doc.match(/\| B10 \|.*/)?.[0] || '')) add('count', `doctor-checks B10 agent count != ${counts.agents}`);
if (!new RegExp(`\\b${counts.codex}\\b`).test(doc.match(/\| C6 \|.*/)?.[0] || '')) add('count', `doctor-checks C6 codex count != ${counts.codex}`);

// --------------------------------------------------- 10. model policy coherence
const policy = read(p('skills', 'penny-kit', 'references', 'model-policy.md'));
for (const a of AGENTS) {
  const f = fm(read(p('agents', a)));
  const base = a.replace(/\.md$/, '').replace(/-agent$/, '').replace(/^council-/, '');
  if (!new RegExp(base, 'i').test(policy)) add('policy', `${a}: "${base}" not mentioned in model-policy.md tiers`);
}
if (/opus/.test(policy.split('### Tiers')[1]?.split('Opus never runs')[0] || '')) {
  // orchestrator row legitimately says opus; only flag a subagent row
}

// -------------------------------------------------------------- 11. scripts run
if (!fs.existsSync(p('scripts', 'rates.json'))) add('script', 'scripts/rates.json missing');
else { try { JSON.parse(read(p('scripts', 'rates.json'))); } catch (e) { add('script', `rates.json invalid: ${e.message}`); } }
for (const j of ['.claude-plugin/plugin.json', '.claude-plugin/marketplace.json']) {
  try { JSON.parse(read(p(j))); } catch (e) { add('json', `${j} invalid: ${e.message}`); }
}
const plug = JSON.parse(read(p('.claude-plugin', 'plugin.json')));
const mkt = JSON.parse(read(p('.claude-plugin', 'marketplace.json')));
if (plug.name !== 'pennywright') add('json', `plugin.json name="${plug.name}"`);
if (mkt.plugins?.[0]?.name !== 'pennywright') add('json', `marketplace plugin name="${mkt.plugins?.[0]?.name}"`);

// ------------------------------------------------------------ 12. codex samples
const cfgS = read(p('codex', 'config.toml.sample'));
const agS = read(p('codex', 'AGENTS.md.sample'));
for (const nm of codexNames) {
  if (!agS.includes(nm)) add('codex', `AGENTS.md.sample never mentions agent "${nm}"`);
}
if (!/\[agents\]/.test(cfgS)) add('codex', 'config.toml.sample has no [agents] block');

// ------------------------------------------------------------------ 13. hygiene
for (const f of ALL.filter((x) => /\.(md|sample|toml|json)$/.test(x))) {
  const src = read(f);
  if (/\r\n/.test(src)) add('eol', `${rel(f)}: CRLF line endings`);
  if (/[ \t]+$/m.test(src)) add('ws', `${rel(f)}: trailing whitespace`);
  if (src.length && !src.endsWith('\n')) add('eof', `${rel(f)}: no trailing newline`);
  if (/\bTODO\b|\bFIXME\b|\bXXX\b|<placeholder>|TBD/.test(src)) add('todo', `${rel(f)}: contains a TODO/placeholder marker`);
}

// ------------------------------------------------------------------- report
console.log(`scanned ${ALL.length} files | skills ${counts.skills} agents ${counts.agents} commands ${counts.commands} codex ${counts.codex} miser ${counts.miser}`);
if (!issues.length) { console.log('\nNO ISSUES'); process.exit(0); }
const byCat = {};
for (const i of issues) { const c = i.match(/^\[(\w+)\]/)[1]; (byCat[c] ||= []).push(i); }
console.log(`\n${issues.length} ISSUES in ${Object.keys(byCat).length} categories\n`);
for (const [c, list] of Object.entries(byCat).sort((a, b) => b[1].length - a[1].length)) {
  console.log(`--- ${c} (${list.length})`);
  for (const i of list.slice(0, 25)) console.log('  ' + i.replace(/^\[\w+\] /, ''));
  if (list.length > 25) console.log(`  ... +${list.length - 25} more`);
}
process.exit(1);

