    "content": "#!/usr/bin/env node
/**
 * Pennywright repo audit — the maintainer's consistency check.
 *
 *   node tools/audit.mjs          # from the repo root
 *
 * Exits 0 when clean, 1 with a grouped report otherwise. Reports; fixes nothing.
 *
 * This repo is prose, not software: there is nothing to unit-test, because the
 * product is instructions a model reads. What CAN break is consistency — a skill
 * whose frontmatter name no longer matches its directory (it silently stops
 * loading), an agent that lost its model pin (it inherits the orchestrator's
 * Opus), a Codex agent with only half a pin (the unset half inherits the
 * parent's xhigh), a contract path that no longer resolves (the subagent spawns
 * anyway and runs with no contract at all), or an index that no longer lists
 * everything it claims to.
 *
 * Those are the failure modes this checks. They are all invisible at a glance
 * and all of them make the kit quietly worse rather than loudly broken.
 *
 * No dependencies. Node >= 18.
 */

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const p = (...a) => path.join(ROOT, ...a);
const read = (f) => fs.readFileSync(f, 'utf8');
const ls = (d) => (fs.existsSync(d) ? fs.readdirSync(d) : []);
const issues = [];
const add = (cat, msg) => issues.push({ cat, msg });

if (!fs.existsSync(p('skills')) || !fs.existsSync(p('.claude-plugin'))) {
  console.error('error: run this from the Pennywright repo root.');
  process.exit(2);
}

/** Minimal YAML-ish frontmatter parser. Handles `key: value` and folded blocks. */
function fm(src) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(src);
  if (!m) return null;
  const o = {};
  let k = null;
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^([A-Za-z_][A-Za-z0-9_-]*):\s*(.*)$/.exec(line);
    if (kv) { k = kv[1]; o[k] = kv[2]; }
    else if (k && /^\s+\S/.test(line)) o[k] = `${o[k]} ${line.trim()}`.trim();
  }
  return o;
}

const walk = (dir, out = []) => {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (['.git', 'node_modules'].includes(e.name)) continue;
    const f = path.join(dir, e.name);
    e.isDirectory() ? walk(f, out) : out.push(f);
  }
  return out;
};
const ALL = walk(ROOT);
const rel = (f) => path.relative(ROOT, f).replace(/\\/g, '/');
const DOCS = ALL.filter((x) => /\.(md|sample)$/.test(x));

const SKILLS = ls(p('skills')).filter((n) => fs.existsSync(p('skills', n, 'SKILL.md')));
const AGENTS = ls(p('agents')).filter((n) => n.endsWith('.md'));
const CMDS = ls(p('commands')).filter((n) => n.endsWith('.md'));
const CTOML = ls(p('codex', 'agents')).filter((n) => n.endsWith('.toml'));
const MISER = SKILLS.filter((s) => s.startsWith('miser-'));

// ------------------------------------------------------------------- 1. skills
for (const d of SKILLS) {
  const f = fm(read(p('skills', d, 'SKILL.md')));
  if (!f) { add('skill', `${d}: no frontmatter`); continue; }
  if (f.name !== d) add('skill', `${d}: frontmatter name="${f.name}" != directory (it will not load)`);
  if (!f.description) { add('skill', `${d}: no description`); continue; }
  for (const k of Object.keys(f)) {
    if (!['name', 'description', 'allowed-tools', 'license'].includes(k)) add('skill', `${d}: unknown frontmatter key "${k}"`);
  }
  // The description is the only part loaded every session: it is both the
  // routing signal and the standing cost.
  if (f.description.length < 60) add('skill', `${d}: description too short to route on`);
  if (f.description.length > 1400) add('skill', `${d}: description is an outsized per-session cost`);
}

// ------------------------------------------------------------------- 2. agents
const AGENT_FIELDS = new Set(['name', 'description', 'tools', 'disallowedTools', 'model', 'permissionMode',
  'maxTurns', 'autoCompactWindow', 'skills', 'mcpServers', 'hooks', 'memory', 'background',
  'omitClaudeMd', 'effort', 'isolation', 'color', 'initialPrompt', 'experimental']);
const COLORS = new Set(['red', 'blue', 'green', 'yellow', 'purple', 'orange', 'pink', 'cyan']);
const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'];
const agentNames = new Set();

for (const a of AGENTS) {
  const f = fm(read(p('agents', a)));
  if (!f) { add('agent', `${a}: no frontmatter`); continue; }
  if (f.name !== a.replace(/\.md$/, '')) add('agent', `${a}: name="${f.name}" != filename`);
  if (agentNames.has(f.name)) add('agent', `duplicate agent name "${f.name}"`);
  agentNames.add(f.name);
  if (f.name?.includes(':')) add('agent', `${a}: ":" is reserved for plugin-scoped ids`);
  for (const k of Object.keys(f)) if (!AGENT_FIELDS.has(k)) add('agent', `${a}: field "${k}" is not in the subagent schema`);

  if (!f.model) add('agent', `${a}: no model pin — it inherits the orchestrator's Opus`);
  else if (!['sonnet', 'haiku'].includes(f.model)) add('agent', `${a}: model="${f.model}" (policy allows sonnet|haiku only)`);
  // Effort levels are model-dependent; the haiku alias has pointed at models
  // that reject the parameter, so omitting it keeps the agent launchable.
  if (f.model === 'haiku' && f.effort) add('agent', `${a}: haiku must not set effort (="${f.effort}")`);
  if (f.model === 'sonnet' && !f.effort) add('agent', `${a}: sonnet without effort resolves from a lower-priority source`);
  if (f.effort && !EFFORTS.includes(f.effort)) add('agent', `${a}: invalid effort "${f.effort}"`);
  if (!f.maxTurns) add('agent', `${a}: no maxTurns — a looping agent bills every turn at full context`);
  else if (!/^\d+$/.test(f.maxTurns) || +f.maxTurns < 1 || +f.maxTurns > 100) add('agent', `${a}: implausible maxTurns "${f.maxTurns}"`);
  if (!f.tools) add('agent', `${a}: no tools allowlist — the allowlist is the token budget`);
  if (f.color && !COLORS.has(f.color)) add('agent', `${a}: invalid color "${f.color}"`);
  if (f.omitClaudeMd && !['true', 'false'].includes(f.omitClaudeMd)) add('agent', `${a}: omitClaudeMd must be true|false`);
}

// scout-agent is spawned speculatively; its brief is the only thing bounding it,
// so it must be structurally incapable of editing.
{
  const f = fm(read(p('agents', 'scout-agent.md')) || '');
  if (f && /\bWrite\b|\bEdit\b/.test(f.tools || '')) add('agent', `scout-agent: tools include a write tool (${f.tools})`);
}

// ----------------------------------------------------------------- 3. commands
const CMD_FIELDS = new Set(['description', 'argument-hint', 'allowed-tools', 'model', 'disable-model-invocation', 'name']);
for (const c of CMDS) {
  const src = read(p('commands', c));
  const f = fm(src);
  if (!f) { add('command', `${c}: no frontmatter`); continue; }
  if (!f.description) add('command', `${c}: no description`);
  for (const k of Object.keys(f)) if (!CMD_FIELDS.has(k)) add('command', `${c}: field "${k}" is not a command field`);
  // Commands that take input must interpolate it.
  if (f['argument-hint'] && !/\$ARGUMENTS/.test(src)) add('command', `${c}: declares argument-hint but never uses $ARGUMENTS`);
  for (const m of src.matchAll(/`([a-z][a-z-]*)`\s+skill/g)) {
    if (!SKILLS.includes(m[1])) add('command', `${c}: references missing skill "${m[1]}"`);
  }
  for (const m of src.matchAll(/`([a-z-]+-agent)`/g)) {
    if (!agentNames.has(m[1])) add('command', `${c}: references missing agent "${m[1]}"`);
  }
}

// ------------------------------------------------------------- 4. codex agents
const codexNames = new Set();
const CODEX_TIERS = { 'gpt-6.2-sol': ['xhigh', 'high', 'medium'], 'gpt-6-luna': ['high'] };
for (const t of CTOML) {
  const src = read(p('codex', 'agents', t));
  for (const k of ['name', 'description', 'developer_instructions']) {
    if (!new RegExp(`^${k}\\s*=`, 'm').test(src)) add('codex', `${t}: missing required field "${k}"`);
  }
  // The half-pin trap: Codex resolves model and effort independently, so a file
  // setting only `model` keeps an effort from the [agents] default or the parent.
  const hasM = /^model\s*=/m.test(src), hasE = /^model_reasoning_effort\s*=/m.test(src);
  if (hasM !== hasE) add('codex', `${t}: half-pinned — sets ${hasM ? 'model' : 'effort'} but not the other`);
  if (!hasM) add('codex', `${t}: no model pin`);
  if ((src.match(/"""/g) || []).length % 2) add('codex', `${t}: unbalanced """ block`);

  const nm = /^name\s*=\s*"([^"]+)"/m.exec(src)?.[1];
  if (!nm) add('codex', `${t}: unparseable name`);
  else { if (codexNames.has(nm)) add('codex', `duplicate codex agent name "${nm}"`); codexNames.add(nm); }

  const mdl = /^model\s*=\s*"([^"]+)"/m.exec(src)?.[1];
  const eff = /^model_reasoning_effort\s*=\s*"([^"]+)"/m.exec(src)?.[1];
  if (mdl && eff) {
    if (!CODEX_TIERS[mdl]) add('tier', `codex/${t}: model "${mdl}" is not one of the documented tiers`);
    else if (!CODEX_TIERS[mdl].includes(eff)) add('tier', `codex/${t}: "${mdl}" + "${eff}" is not a documented tier pair`);
  }

  // TOML puts a bare key after a [table] header INSIDE that table, which would
  // silently reparent developer_instructions out of the agent definition.
  let sawTable = false, inStr = false;
  src.split(/\r?\n/).forEach((line, i) => {
    if ((line.match(/"""/g) || []).length % 2) inStr = !inStr;
    if (inStr) return;
    if (/^\s*\[/.test(line)) { sawTable = true; return; }
    if (sawTable && /^(name|description|developer_instructions|model|model_reasoning_effort)\s*=/.test(line)) {
      add('codex', `${t}:${i + 1}: agent-defining key after a [table] header — TOML reparents it`);
    }
  });
}

// ------------------------------------------------- 5. references and links
for (const f of DOCS) {
  const src = read(f);
  const dir = path.dirname(f);
  // Skill-relative reference paths resolve against the skill directory.
  if (rel(f).startsWith('skills/')) {
    for (const m of src.matchAll(/`((?:references|templates)\/[A-Za-z0-9_.\-]+\.md)`/g)) {
      if (!fs.existsSync(path.join(dir, m[1]))) add('ref', `${rel(f)}: missing ${m[1]}`);
    }
  }
  // Repo-root-relative paths quoted in backticks.
  for (const m of src.matchAll(/`((?:skills|agents|commands|codex|scripts|hooks|reference|tools)\/[A-Za-z0-9_.\-/]*\.(?:md|mjs|sh|py|json|toml|sample))`/g)) {
    if (!fs.existsSync(p(m[1]))) add('ref', `${rel(f)}: missing path ${m[1]}`);
  }
  // Markdown links to local files.
  for (const m of src.matchAll(/\]\((?!https?:|#|mailto:)([^)]+)\)/g)) {
    const target = m[1].split('#')[0];
    if (target && !fs.existsSync(path.join(dir, target))) add('link', `${rel(f)}: broken link ${target}`);
  }
  // Agent names mentioned in prose must exist.
  for (const m of src.matchAll(/`(council-[a-z]+|[a-z]+-agent)`/g)) {
    if (!agentNames.has(m[1])) add('nameref', `${rel(f)}: unknown agent \`${m[1]}\``);
  }
  for (const m of src.matchAll(/`(council_[a-z]+|[a-z]+_agent)`/g)) {
    if (!codexNames.has(m[1])) add('nameref', `${rel(f)}: unknown codex agent \`${m[1]}\``);
  }
  // Slash references must be a real command or skill.
  for (const m of src.matchAll(/`\/(penny[a-z-]*|miser-[a-z]+)`/g)) {
    if (!CMDS.includes(`${m[1]}.md`) && !SKILLS.includes(m[1])) {
      add('nameref', `${rel(f)}: /${m[1]} is neither a command nor a skill`);
    }
  }
}

// --------------------------------------------------- 6. README anchors
{
  const src = read(p('README.md'));
  const slugs = new Set();
  for (const m of src.matchAll(/^#{1,6}\s+(.+)$/gm)) {
    slugs.add(m[1].trim().toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-'));
  }
  for (const m of src.matchAll(/\]\(#([a-z0-9-]+)\)/g)) {
    if (!slugs.has(m[1])) add('anchor', `README.md: table-of-contents link #${m[1]} matches no heading`);
  }
}

// ------------------------------------------- 7. tier coherence across documents
{
  // Parse the Claude tier table only — the Codex table has three columns.
  // Columns: | Tier | Who | Model | Effort | [Why] |
  const rows = (txt) => {
    const claudeOnly = txt.split(/###\s+Codex/)[0];
    const clean = (c) => c.replace(/[`*]/g, '').replace(/\(unset\)|—|–/g, '').trim();
    const out = {};
    for (const line of claudeOnly.split(/\r?\n/)) {
      if (!/^\|/.test(line)) continue;
      const cells = line.split('|').slice(1, -1).map((c) => c.trim());
      if (cells.length < 4) continue;
      const tier = clean(cells[0]).toLowerCase();
      if (!['orchestrator', 'judgment', 'craft', 'hands'].includes(tier)) continue;
      out[tier] = { model: clean(cells[2]) || undefined, effort: clean(cells[3]) || undefined };
    }
    return out;
  };
  const policy = rows(read(p('skills', 'penny-kit', 'references', 'model-policy.md')));
  const readme = rows(read(p('README.md')));

  for (const tier of ['orchestrator', 'judgment', 'craft', 'hands']) {
    if (!policy[tier]) { add('tier', `model-policy.md: no "${tier}" row found`); continue; }
    if (!readme[tier]) { add('tier', `README.md: no "${tier}" row found`); continue; }
    if (policy[tier].model !== readme[tier].model) {
      add('tier', `${tier}: model differs — policy=${policy[tier].model} README=${readme[tier].model}`);
    }
    if ((policy[tier].effort || '') !== (readme[tier].effort || '')) {
      add('tier', `${tier}: effort differs — policy=${policy[tier].effort || '(unset)'} README=${readme[tier].effort || '(unset)'}`);
    }
  }

  // Each agent's pins must match the tier its role belongs to. Adding an agent
  // means adding it here — the audit says so rather than passing silently.
  const TIER_OF = {
    'plan-agent': 'judgment', 'review-agent': 'judgment', 'council-architect': 'judgment',
    'council-skeptic': 'judgment', 'council-referee': 'judgment',
    'test-agent': 'craft', 'implement-agent': 'craft', 'verify-agent': 'craft',
    'improve-agent': 'craft', 'council-pragmatist': 'craft',
    'remember-agent': 'hands', 'scout-agent': 'hands',
    'council-operator': 'hands', 'council-economist': 'hands',
  };
  for (const a of AGENTS) {
    const f = fm(read(p('agents', a)));
    const tier = TIER_OF[f?.name];
    if (!tier) { add('tier', `${a}: not in tools/audit.mjs TIER_OF — add it with its tier`); continue; }
    const want = policy[tier];
    if (!want) continue;
    if (f.model !== want.model) add('tier', `${a}: model=${f.model} but the ${tier} tier is ${want.model}`);
    if ((f.effort || undefined) !== (want.effort || undefined)) {
      add('tier', `${a}: effort=${f.effort || '(unset)'} but the ${tier} tier is ${want.effort || '(unset)'}`);
    }
  }
}

// --------------------------------------------------- 8. index completeness
{
  // Every agent must be reachable: named by some skill or command.
  const haystack = [...SKILLS.flatMap((s) => walk(p('skills', s))), ...CMDS.map((c) => p('commands', c))]
    .filter((f) => f.endsWith('.md')).map(read).join('\n');
  for (const n of agentNames) {
    if (!haystack.includes(n)) add('orphan', `agent "${n}" is never referenced by any skill or command`);
  }
  // Every miser skill must appear in its own index and in the README.
  const help = read(p('skills', 'miser-help', 'SKILL.md'));
  const readme = read(p('README.md'));
  for (const m of MISER) {
    if (m !== 'miser-help' && !help.includes(m)) add('index', `miser-help does not list ${m}`);
    if (!readme.includes(m)) add('index', `README does not list ${m}`);
  }
  // Every command must appear in the kit's help index.
  const kit = read(p('skills', 'penny-kit', 'SKILL.md'));
  for (const c of CMDS) {
    const n = c.replace(/\.md$/, '');
    if (!kit.includes(`/${n}`)) add('index', `penny-kit help does not list /${n}`);
  }
}

// ------------------------------------------------------- 9. documented counts
{
  const kit = read(p('skills', 'penny-kit', 'SKILL.md'));
  const doc = read(p('skills', 'penny-kit', 'references', 'doctor-checks.md'));
  const row = (id) => doc.match(new RegExp(`\\| ${id} \\|.*`))?.[0] || '';
  if (!new RegExp(`${SKILLS.length} skills`).test(kit)) add('count', `penny-kit/SKILL.md does not state "${SKILLS.length} skills"`);
  if (!new RegExp(`\\b${SKILLS.length}\\b`).test(row('B11'))) add('count', `doctor-checks B11 != ${SKILLS.length} skills`);
  if (!new RegExp(`\\b${AGENTS.length}\\b`).test(row('B10'))) add('count', `doctor-checks B10 != ${AGENTS.length} agents`);
  if (!new RegExp(`\\b${CTOML.length}\\b`).test(row('C6'))) add('count', `doctor-checks C6 != ${CTOML.length} codex agents`);
  if (!new RegExp(`\\b${MISER.length}\\b`).test(row('C8'))) add('count', `doctor-checks C8 != ${MISER.length} miser skills`);
}

// ----------------------------------------------------- 10. manifests and data
for (const j of ['.claude-plugin/plugin.json', '.claude-plugin/marketplace.json', 'scripts/rates.json']) {
  if (!fs.existsSync(p(j))) { add('json', `${j} missing`); continue; }
  try { JSON.parse(read(p(j))); } catch (e) { add('json', `${j} is invalid JSON: ${e.message}`); }
}
try {
  const plug = JSON.parse(read(p('.claude-plugin', 'plugin.json')));
  const mkt = JSON.parse(read(p('.claude-plugin', 'marketplace.json')));
  if (plug.name !== 'pennywright') add('json', `plugin.json name="${plug.name}"`);
  if (mkt.plugins?.[0]?.name !== 'pennywright') add('json', `marketplace plugin name="${mkt.plugins?.[0]?.name}"`);
  if (mkt.plugins?.[0]?.source !== './') add('json', `marketplace source="${mkt.plugins?.[0]?.source}"`);
} catch { /* reported above */ }

for (const f of ['scripts/context-report.sh', 'scripts/miser-bench.mjs', 'hooks/filter-tool-output.py', 'reference/techniques.md']) {
  if (!fs.existsSync(p(f))) add('substrate', `${f} missing — a skill invokes it`);
  else if (!fs.statSync(p(f)).size) add('substrate', `${f} is empty`);
}

// --------------------------------------------------------- 11. codex samples
{
  const cfg = read(p('codex', 'config.toml.sample'));
  const ag = read(p('codex', 'AGENTS.md.sample'));
  for (const nm of codexNames) if (!ag.includes(nm)) add('codex', `AGENTS.md.sample never mentions agent "${nm}"`);
  if (!/\[agents\]/.test(cfg)) add('codex', 'config.toml.sample has no [agents] block');
  if (!/model_reasoning_effort/.test(cfg)) add('codex', 'config.toml.sample never sets model_reasoning_effort');
}

// ------------------------------------------------------- 12. stale identifiers
const STALE = [
  [/\bagentic-app-loop\b/, 'pre-rename repo/product name'],
  [/\bagent-kit\b/, 'pre-rename skill name'],
  [/`build-app`/, 'pre-rename skill name'],
  [/\/kit-(setup|doctor|help)\b/, 'pre-rename command name'],
  [/bin\/(penny|loop)\.mjs/, 'deleted installer'],
  [/npx (github:|tokenmiser)/, 'deleted install path'],
  [/\bmiser-setup\b/, 'removed skill'],
  [/@authormark v1 -- do not remove/, 'removed watermark header'],
  [/\bAUTHORSHIP\.(json|log)\b/, 'deleted file'],
  [/\bREUSE\.toml\b/, 'deleted file'],
];
for (const f of ALL.filter((x) => /\.(md|sample|toml|json|sh|py|mjs)$/.test(x))) {
  if (rel(f) === 'tools/audit.mjs') continue;   // this file names them on purpose
  const src = read(f);
  for (const [re, why] of STALE) if (re.test(src)) add('stale', `${rel(f)}: ${re.source} (${why})`);
}

// -------------------------------------------------------------- 13. hygiene
for (const f of ALL.filter((x) => /\.(md|sample|toml|json)$/.test(x))) {
  const src = read(f);
  if (/\r\n/.test(src)) add('hygiene', `${rel(f)}: CRLF line endings`);
  if (/[ \t]+$/m.test(src)) add('hygiene', `${rel(f)}: trailing whitespace`);
  if (src.length && !src.endsWith('\n')) add('hygiene', `${rel(f)}: no trailing newline`);
  if (/(^|\s)(TODO|FIXME|XXX):|<placeholder>|\bTBD\b/i.test(src)) add('hygiene', `${rel(f)}: unresolved marker`);
}
// Templates are copied verbatim into the user's repo: nothing of ours in them.
for (const d of SKILLS) {
  for (const t of ls(p('skills', d, 'templates'))) {
    if (/@authormark|Copyright \(c\)/.test(read(p('skills', d, 'templates', t)))) {
      add('hygiene', `skills/${d}/templates/${t}: carries a header — it is copied into the user's repo`);
    }
  }
}

// ---------------------------------------------------------------- report
const head = `scanned ${ALL.length} files | skills ${SKILLS.length} (${MISER.length} miser) `
  + `| agents ${AGENTS.length} | commands ${CMDS.length} | codex ${CTOML.length}`;
console.log(head);

if (!issues.length) { console.log('\nNO ISSUES'); process.exit(0); }

const byCat = {};
for (const i of issues) (byCat[i.cat] ||= []).push(i.msg);
console.log(`\n${issues.length} ISSUE${issues.length === 1 ? '' : 'S'} in ${Object.keys(byCat).length} categor${Object.keys(byCat).length === 1 ? 'y' : 'ies'}\n`);
for (const [cat, list] of Object.entries(byCat).sort((a, b) => b[1].length - a[1].length)) {
  console.log(`--- ${cat} (${list.length})`);
  for (const m of list.slice(0, 25)) console.log(`  ${m}`);
  if (list.length > 25) console.log(`  ... +${list.length - 25} more`);
}
process.exit(1);
"
  }
}
