param(
    # Main model. qwen3.5:9b is the quality/speed sweet spot on 8 GB VRAM.
    # Accepts shorthand: 4b / 9b / 35b.
    [string]$Model      = 'qwen3.5:9b',
    # Small/fast model Claude Code uses for cheap background tasks.
    [string]$SmallModel = 'qwen3.5:4b',
    [string]$BaseUrl    = 'http://localhost:11434/v1',
    # Run against the real Anthropic API, scrubbing local routing first.
    [switch]$Cloud,
    # Print what this shell would actually talk to, then exit.
    [switch]$Doctor,
    # Pass extra args straight through to `claude`.
    [Parameter(ValueFromRemainingArguments = $true)]
    [string[]]$ClaudeArgs
)

$ErrorActionPreference = 'Stop'

# Shorthand so `cclocal 35b` works.
if ($Model      -match '^(4b|9b|35b)$') { $Model      = "qwen3.5:$Model" }
if ($SmallModel -match '^(4b|9b|35b)$') { $SmallModel = "qwen3.5:$SmallModel" }

# --- Local-routing env vars, in one place ----------------------------------
$routingVars = @(
    'ANTHROPIC_BASE_URL', 'ANTHROPIC_MODEL', 'ANTHROPIC_SMALL_FAST_MODEL',
    'ANTHROPIC_DEFAULT_OPUS_MODEL', 'ANTHROPIC_DEFAULT_SONNET_MODEL',
    'ANTHROPIC_DEFAULT_HAIKU_MODEL', 'CLAUDE_CODE_MAX_OUTPUT_TOKENS'
)

if ($Doctor) {
    Write-Host ''
    Write-Host '  Claude Code routing in THIS shell' -ForegroundColor Cyan
    Write-Host '  ---------------------------------'
    if ($env:ANTHROPIC_BASE_URL) {
        Write-Host "  ANTHROPIC_BASE_URL = $env:ANTHROPIC_BASE_URL   -> LOCAL"
    } else {
        Write-Host '  ANTHROPIC_BASE_URL = (unset)                 -> CLOUD'
    }
    $m = if ($env:ANTHROPIC_MODEL) { $env:ANTHROPIC_MODEL } else { '(unset)' }
    Write-Host "  ANTHROPIC_MODEL    = $m"
    Write-Host ''
    # A local model name with no local endpoint is the exact broken combination.
    if (-not $env:ANTHROPIC_BASE_URL -and $env:ANTHROPIC_MODEL -like 'qwen*') {
        Write-Host '  BROKEN: a local model name is pointed at the cloud API.' -ForegroundColor Red
        Write-Host "  Fix: run 'ccloud' for cloud, or 'cclocal' for local." -ForegroundColor Red
        Write-Host ''
    }
    Write-Host '  Ollama:'
    try {
        $v = Invoke-RestMethod -Uri 'http://127.0.0.1:11434/api/version' -TimeoutSec 3
        Write-Host "    running - version $($v.version)" -ForegroundColor Green
    } catch {
        Write-Host '    NOT running (cclocal will start it for you)' -ForegroundColor Yellow
    }
    Write-Host ''
    exit 0
}

if ($Cloud) {
    # Scrub every local-routing var. Without this, a stale ANTHROPIC_MODEL left
    # in the shell sends a local model name (qwen3.5:9b) to api.anthropic.com,
    # which 404s with "model may not exist or you may not have access to it".
    foreach ($v in $routingVars) {
        Remove-Item "Env:\$v" -ErrorAction SilentlyContinue
    }
    Write-Host ''
    Write-Host '  Claude Code -> CLOUD (real Anthropic API)' -ForegroundColor Cyan
    Write-Host ''
    claude @ClaudeArgs
    exit $LASTEXITCODE
}

