{
  "name": "Write",
  "input": {
    "file_path": "E:\\immich-app\\progress.sh",
    "content": "#!/usr/bin/env bash\n# Immich indexing progress. Usage: bash progress.sh [seconds_between_samples]\n# Run with no args for a one-shot snapshot, or e.g. \"bash progress.sh 60\" to watch.\n\nQ() { docker exec immich_postgres psql -U postgres -d immich -tAc \"$1\" 2>/dev/null | tr -d ' \\r'; }\n\nsnapshot() {\n  TOTAL=$(Q \"select count(*) from asset;\")\n  META=$(Q  \"select count(*) from asset_job_status where \\\"metadataExtractedAt\\\" is not null;\")\n  THUMB=$(Q \"select count(*) from asset_file where type='thumbnail';\")\n  FACES=$(Q \"select count(*) from asset_job_status where \\\"facesRecognizedAt\\\" is not null;\")\n  SMART=$(Q \"select count(*) from smart_search;\")\n  PEOPLE=$(Q \"select count(*) from person;\")\n  OCR=$(Q   \"select count(*) from asset_job_status where \\\"ocrAt\\\" is not null;\")\n}\n\nbar() { # bar <done> <total>\n  local d=$1 t=$2 w=32\n  [ \"${t:-0}\" -eq 0 ] && { printf \"n/a\"; return; }\n  local f=$(( d * w / t )) p=$(( d * 100 / t ))\n  printf \"[\"\n  for ((i=0;i<w;i++)); do [ $i -lt $f ] && printf \"#\" || printf \".\"; done\n  printf \"] %3d%%  %s/%s\" \"$p\" \"$d\" \"$t\"\n}\n\nshow() {\n  echo \"  metadata     $(bar \"${META:-0}\"  \"$TOTAL\")\"\n  echo \"  thumbnails   $(bar \"${THUMB:-0}\" \"$TOTAL\")\"\n  echo \"  faces        $(bar \"${FACES:-0}\" \"$TOTAL\")\"\n  echo \"  smart search $(bar \"${SMART:-0}\" \"$TOTAL\")\"\n  echo \"  ocr          $(bar \"${OCR:-0}\"   \"$TOTAL\")\"\n  echo \"  people found: ${PEOPLE:-0}\"\n}\n\nINTERVAL=${1:-0}\n\nsnapshot\necho \"=== Immich indexing progress  ($(date '+%H:%M:%S')) ===\"\nshow\n\nif [ \"$INTERVAL\" -gt 0 ] 2>/dev/null; then\n  while true; do\n    P_META=$META; P_THUMB=$THUMB; P_FACES=$FACES; P_SMART=$SMART\n    sleep \"$INTERVAL\"\n    snapshot\n    echo\n    echo \"=== $(date '+%H:%M:%S')  (last ${INTERVAL}s) ===\"\n    show\n    RATE=$(( (THUMB - P_THUMB) ))\n    if [ \"$RATE\" -gt 0 ]; then\n      LEFT=$(( TOTAL - THUMB ))\n      ETA=$(( LEFT * INTERVAL / RATE / 60 ))\n      echo \"  rate: ${RATE} thumbs/${INTERVAL}s  ->  ~${ETA} min remaining for thumbnails\"\n    fi\n    if [ \"${THUMB:-0}\" -ge \"${TOTAL:-1}\" ] && [ \"${SMART:-0}\" -ge \"${TOTAL:-1}\" ]; then\n      echo \"  ALL DONE\"; break\n    fi\n  done\nfi\n\necho\necho \"=== GPU ===\"\ndocker exec immich_machine_learning nvidia-smi \\\n  --query-gpu=utilization.gpu,utilization.encoder,memory.used \\\n  --format=csv,noheader 2>/dev/null | sed 's/^/  compute\\/encoder\\/vram: /'\n"
  }
