# Verifies the offline setup for Actual Budget.  No admin required.

$exe     = "$env:LOCALAPPDATA\Programs\desktop-electron\Actual.exe"
$dataDir = "$env:APPDATA\Actual"
$docDir  = "$env:USERPROFILE\Documents\Actual"
$ok      = $true

function Check($label, $pass, $detail) {
    if ($pass) { Write-Host "[ OK ] $label" -ForegroundColor Green }
    else       { Write-Host "[FAIL] $label" -ForegroundColor Red; $script:ok = $false }
    if ($detail) { Write-Host "       $detail" -ForegroundColor DarkGray }
}

Write-Host "`n=== Actual Budget offline check ===`n"

Check 'Actual.exe installed' (Test-Path $exe) $exe
Check 'Budget files directory exists' (Test-Path $docDir) $docDir

# Sync server must be unconfigured (local-only mode)
$storePath = Join-Path $dataDir 'global-store.json'
if (Test-Path $storePath) {
    $store = Get-Content $storePath -Raw | ConvertFrom-Json
    $noServer = ($null -eq $store.'server-url') -and ($null -eq $store.syncServerConfig)
    Check 'No sync server configured' $noServer "server-url = $($store.'server-url')"
} else {
    Check 'No sync server configured' $false 'global-store.json not found (app not yet launched)'
}

# Firewall rules
foreach ($dir in 'Outbound', 'Inbound') {
    $name = "Actual Budget - Block $dir"
    $rule = Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue
    $live = $rule -and $rule.Enabled -eq 'True' -and $rule.Action -eq 'Block'
    Check "Firewall rule: $name" $live $(if ($rule) { "Enabled=$($rule.Enabled) Action=$($rule.Action)" } else { 'rule missing - run block-actual-internet.ps1 as Administrator' })
}

# Budget files on disk
if (Test-Path $docDir) {
    $budgets = Get-ChildItem $docDir -Directory
    Write-Host "`nBudgets found: $($budgets.Count)"
    foreach ($b in $budgets) {
        $db = Join-Path $b.FullName 'db.sqlite'
        $size = if (Test-Path $db) { "{0:N0} KB" -f ((Get-Item $db).Length / 1KB) } else { 'no db.sqlite' }
        Write-Host "  - $($b.Name)  ($size)"
    }
