    "file_path": "E:\\LocalLLM\\run-claude-local.ps1",
    "content": "# run-claude-local.ps1 - Point Claude Code at your LOCAL model for zero-cost offline work.\n#\n# Verified on this machine: Ollama 0.40.16 serves a native Anthropic-compatible\n# /v1/messages endpoint (it even returns `thinking` content blocks), so no\n# translation proxy is needed. ANTHROPIC_BASE_URL can target Ollama directly.\n#\n# Usage:\n#   powershell -ExecutionPolicy Bypass -File E:\\LocalLLM\\run-claude-local.ps1\n#   powershell -ExecutionPolicy Bypass -File E:\\LocalLLM\\run-claude-local.ps1 -Model qwen3.5:35b\n#\n# The env vars are scoped to the launched process only - your normal `claude`\n# in other terminals keeps using the real Anthropic API.\n\nparam(\n    # Main model. qwen3.5:9b is the quality/speed sweet spot on 8 GB VRAM.\n    [string]$Model      = 'qwen3.5:9b',\n    # Small/fast model Claude Code uses for cheap background tasks.\n    [string]$SmallModel = 'qwen3.5:4b',\n    [string]$BaseUrl    = 'http://localhost:11434/v1',\n    # Pass extra args straight through to `claude`.\n    [Parameter(ValueFromRemainingArguments = $true)]\n    [string[]]$ClaudeArgs\n)\n\n$ErrorActionPreference = 'Stop'\n\n# --- Make sure the local server is actually up ------------------------------\ntry {\n    $null = Invoke-RestMethod -Uri 'http://127.0.0.1:11434/api/version' -TimeoutSec 3\n} catch {\n    Write-Host 'Ollama is not running - starting it...' -ForegroundColor Yellow\n    & powershell -ExecutionPolicy Bypass -File \"$PSScriptRoot\\start-ollama.ps1\"\n}\n\n# --- Make sure the requested model exists locally ---------------------------\n$tags = (Invoke-RestMethod -Uri 'http://127.0.0.1:11434/api/tags' -TimeoutSec 10).models.name\nforeach ($m in @($Model, $SmallModel)) {\n    if ($tags -notcontains $m) {\n        Write-Error \"Model '$m' is not installed. Run:  ollama pull $m`nInstalled: $($tags -join ', ')\"\n        exit 1\n    }\n}\n\n# --- Route Claude Code at the local endpoint -------------------------------\n$env:ANTHROPIC_BASE_URL   = $BaseUrl\n# Ollama ignores the key, but the SDK requires a non-empty value.\n$env:ANTHROPIC_AUTH_TOKEN = 'local-no-key-needed'\n$env:ANTHROPIC_API_KEY    = 'local-no-key-needed'\n\n$env:ANTHROPIC_MODEL                  = $Model\n$env:ANTHROPIC_SMALL_FAST_MODEL       = $SmallModel\n$env:ANTHROPIC_DEFAULT_OPUS_MODEL     = $Model\n$env:ANTHROPIC_DEFAULT_SONNET_MODEL   = $Model\n$env:ANTHROPIC_DEFAULT_HAIKU_MODEL    = $SmallModel\n\n# Don't phone home while running fully offline.\n$env:CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC = '1'\n$env:DISABLE_TELEMETRY        = '1'\n$env:DISABLE_ERROR_REPORTING  = '1'\n# 8 GB VRAM holds one model at a time; keep the context honest.\n$env:CLAUDE_CODE_MAX_OUTPUT_TOKENS = '8192'\n\nWrite-Host ''\nWrite-Host '  Claude Code -> LOCAL model' -ForegroundColor Green\nWrite-Host \"  endpoint : $BaseUrl\"\nWrite-Host \"  model    : $Model   (small: $SmallModel)\"\nWrite-Host '  cost     : $0.00 - nothing leaves this machine' -ForegroundColor Green\nWrite-Host ''\nWrite-Host '  Expect degraded agentic behaviour vs real Claude: a 9B model is' -ForegroundColor DarkYellow\nWrite-Host '  weaker at multi-step tool calling and long-context planning.' -ForegroundColor DarkYellow\nWrite-Host '  Closing that gap is exactly what teacher_pipeline/ is for.' -ForegroundColor DarkYellow\nWrite-Host ''\n\nclaude @ClaudeArgs\n"
  }
}
