    "content": "#!/usr/bin/env bash\n# run-claude-local.sh - Point Claude Code at your LOCAL model (bash / WSL2 / git-bash).\n#\n# Ollama 0.40.16 serves a native Anthropic-compatible /v1/messages endpoint, so\n# ANTHROPIC_BASE_URL can target it directly - no translation proxy required.\n#\n# Usage:\n#   ./run-claude-local.sh                      # qwen3.5:9b\n#   MODEL=qwen3.5:35b ./run-claude-local.sh    # the MoE wildcard\n#\n# From WSL2, Windows' localhost is not the WSL localhost. Either run\n# `ollama serve` inside WSL too, or set:\n#   OLLAMA_URL=http://$(ip route show default | awk '{print $3}'):11434\n\nset -euo pipefail\n\nMODEL=\"${MODEL:-qwen3.5:9b}\"\nSMALL_MODEL=\"${SMALL_MODEL:-qwen3.5:4b}\"\nOLLAMA_URL=\"${OLLAMA_URL:-http://localhost:11434}\"\n\nif ! curl -sf --max-time 3 \"${OLLAMA_URL}/api/version\" >/dev/null; then\n  echo \"ERROR: no Ollama server at ${OLLAMA_URL}\" >&2\n  echo \"  Windows: powershell -ExecutionPolicy Bypass -File E:\\\\LocalLLM\\\\start-ollama.ps1\" >&2\n  echo \"  WSL/Linux: ollama serve &\" >&2\n  exit 1\nfi\n\ninstalled=$(curl -sf --max-time 10 \"${OLLAMA_URL}/api/tags\" \\\n  | python3 -c 'import json,sys; print(\" \".join(m[\"name\"] for m in json.load(sys.stdin).get(\"models\",[])))')\n\nfor m in \"$MODEL\" \"$SMALL_MODEL\"; do\n  case \" $installed \" in\n    *\" $m \"*) ;;\n    *) echo \"ERROR: model '$m' not installed. Run: ollama pull $m\" >&2\n       echo \"Installed: $installed\" >&2; exit 1 ;;\n  esac\ndone\n\nexport ANTHROPIC_BASE_URL=\"${OLLAMA_URL}/v1\"\n# Ollama ignores the key but the SDK requires a non-empty value.\nexport ANTHROPIC_AUTH_TOKEN=\"local-no-key-needed\"\nexport ANTHROPIC_API_KEY=\"local-no-key-needed\"\n\nexport ANTHROPIC_MODEL=\"$MODEL\"\nexport ANTHROPIC_SMALL_FAST_MODEL=\"$SMALL_MODEL\"\nexport ANTHROPIC_DEFAULT_OPUS_MODEL=\"$MODEL\"\nexport ANTHROPIC_DEFAULT_SONNET_MODEL=\"$MODEL\"\nexport ANTHROPIC_DEFAULT_HAIKU_MODEL=\"$SMALL_MODEL\"\n\nexport CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1\nexport DISABLE_TELEMETRY=1\nexport DISABLE_ERROR_REPORTING=1\nexport CLAUDE_CODE_MAX_OUTPUT_TOKENS=8192\n\ncat <<EOF\n\n  Claude Code -> LOCAL model\n  endpoint : ${ANTHROPIC_BASE_URL}\n  model    : ${MODEL}   (small: ${SMALL_MODEL})\n  cost     : \\$0.00 - nothing leaves this machine\n\n  Expect degraded agentic behaviour vs real Claude: a 9B model is weaker at\n  multi-step tool calling and long-context planning. Closing that gap is\n  exactly what teacher_pipeline/ is for.\n\nEOF\n\nexec claude \"$@\"\n"
  }
