{
  "name": "Write",
  "input": {
    "file_path": "E:\\LocalLLM\\teacher_pipeline\\curriculum.yaml",
    "content": "# curriculum.yaml - What the Student must learn from the Teacher.\n#\n# This file is the single source of truth for the whole pipeline:\n#   generate_lessons.py  reads `skills` to know what examples to synthesize\n#   grade_student.py     reads `rubric` + `eval` to know how to score\n#   train_student.py     reads `training` for the VRAM-calibrated hyperparameters\n#\n# Calibrated for: RTX 4060 Ti 8 GB | Ryzen 7 5700X | 64 GB RAM | WSL2 Ubuntu\n\nmeta:\n  student_model: qwen3.5:4b                      # served (Ollama tag)\n  student_hf_repo: unsloth/Qwen3.5-4B            # trained (HF repo, 4-bit QLoRA)\n  teacher: claude-opus-5                          # Claude, acting as Teacher\n  daily_driver: qwen3.5:9b                        # untouched by training\n  created: 2026-11-22\n  version: 1\n\n# ---------------------------------------------------------------------------\n# DOMAIN - set during Phase 4. Everything downstream keys off this.\n# ---------------------------------------------------------------------------\ndomain:\n  name: \"TBD\"\n  description: \"TBD - set in Phase 4\"\n  # Stacks/tools the Student is expected to be fluent in.\n  stacks: []\n\n# ---------------------------------------------------------------------------\n# SKILLS - one block per competency. `weight` controls how many examples\n# generate_lessons.py synthesizes for it (relative share of the batch).\n# `difficulty` ladders: lessons start easy and escalate across micro-epochs.\n# ---------------------------------------------------------------------------\nskills: []\n#  - id: tool_call_format\n#    name: \"Exact tool-call formatting\"\n#    weight: 3\n#    difficulty: [easy, medium, hard]\n#    description: >\n#      Emit tool calls with precise JSON schema adherence - correct names,\n#      no invented parameters, no prose wrapped around the call.\n#    must_include: [\"valid JSON\", \"no hallucinated params\"]\n\n# ---------------------------------------------------------------------------\n# RUBRIC - how grade_student.py scores an answer. Weights must sum to 1.0.\n# ---------------------------------------------------------------------------\nrubric:\n  weights:\n    accuracy: 0.45      # is the substance correct?\n    reasoning: 0.25     # is the chain-of-thought sound, not just the answer?\n    formatting: 0.20    # does it match the required output shape exactly?\n    conciseness: 0.10   # no padding, no restating the question\n  pass_threshold: 0.70  # below this, the skill is logged as weak\n  scale: 5              # per-criterion scoring is 0-5, normalized to 0-1\n\n# ---------------------------------------------------------------------------\n# DATA GENERATION\n# ---------------------------------------------------------------------------\ngeneration:\n  batch_size: 25                 # examples per lesson batch\n  include_thinking: true         # preserve the Teacher's CoT in the target\n  thinking_tag: \"think\"          # wrapped as <think>...</think> in training text\n  min_chars: 120                 # reject stubs\n  max_chars: 12000               # reject runaway outputs\n  dedupe:\n    method: minhash_jaccard      # near-duplicate detection, not just exact\n    threshold: 0.85              # >= this Jaccard similarity = duplicate\n    shingle_size: 5              # word n-gram size for shingling\n  quality_filters:\n    require_thinking: true       # a target with no CoT is low-signal\n    reject_refusals: true\n    reject_placeholders: true    # \"TODO\", \"...\", \"your code here\"\n    max_per_skill_ratio: 0.40    # no single skill may dominate the batch\n\n# ---------------------------------------------------------------------------\n# EVALUATION\n# ---------------------------------------------------------------------------\neval:\n  holdout_ratio: 0.20            # fraction of generated examples kept unseen\n  n_eval_prompts: 20             # per grading run\n  temperature: 0.3               # low, for score stability across runs\n  think: true                    # grade the reasoning channel too\n  max_tokens: 2048\n  # Compare each run against the previous to catch regression / forgetting.\n  regression_guard:\n    enabled: true\n    max_drop: 0.05               # >5% score drop on a previously-passing skill\n                                 # = likely catastrophic forgetting; halt.\n\n# ---------------------------------------------------------------------------\n# TRAINING - QLoRA hyperparameters calibrated to 8 GB VRAM.\n# These numbers are deliberately conservative; peak usage ~6 GB leaves\n# headroom for the Windows desktop compositor sharing the card.\n# ---------------------------------------------------------------------------\ntraining:\n  max_seq_length: 2048           # 4096 will OOM at batch 2 on 8 GB\n  load_in_4bit: true             # QLoRA - the base stays quantized\n  dtype: bfloat16                # Ada (RTX 4060 Ti) supports bf16 natively\n\n  lora:\n    r: 16                        # 16 is the sweet spot for small incremental runs\n    alpha: 32                    # 2x r\n    dropout: 0.0                 # Unsloth's fast path requires 0\n    bias: none\n    target_modules:\n      - q_proj\n      - k_proj\n      - v_proj\n      - o_proj\n      - gate_proj\n      - up_proj\n      - down_proj\n    use_rslora: true             # rank-stabilized: steadier at low LR\n    use_gradient_checkpointing: unsloth\n\n  batch:\n    per_device_train_batch_size: 2\n    gradient_accumulation_steps: 8   # effective batch = 16\n    dataloader_num_workers: 2\n\n  optim:\n    optimizer: adamw_8bit        # paged 8-bit optimizer; saves ~1 GB\n    learning_rate: 2.0e-4        # start of the cosine ramp-down\n    min_learning_rate: 5.0e-5    # floor - the cosine decays to this\n    lr_scheduler_type: cosine\n    warmup_ratio: 0.03\n    weight_decay: 0.01\n    max_grad_norm: 0.3           # low clip: guards against loss spikes\n    num_train_epochs: 2          # a \"micro-epoch\" pass over the new batch\n    seed: 3407\n\n  # --- anti-catastrophic-forgetting -----------------------------------------\n  # The core defence is structural: LoRA only (base weights frozen), a low LR\n  # floor, and replaying old examples alongside new ones.\n  forgetting_guard:\n    replay_ratio: 0.30           # 30% of each batch is resampled older data\n    train_on_responses_only: true  # mask the prompt; don't train on user turns\n    resume_from_last_adapter: true # stack lessons rather than restarting\n    eval_before_and_after: true    # grade_student.py runs on both sides\n\n  checkpointing:\n    save_steps: 25\n    save_total_limit: 4\n    output_dir: ./adapters\n\n  export:\n    merge_to_16bit: true\n    gguf_quant: q4_k_m           # matches the served daily-driver quant\n    gguf_dir: ./gguf\n    ollama_tag: qwen3.5-student  # :v1, :v2, ... per lesson\n"
  }
}
