```json
{
  "name": "Write",
  "input": {
    "file_path": "E:\\LocalLLM\\teacher_pipeline\\generate_lessons.py",
    "content": "#!/usr/bin/env python3\n\"\"\"\ngenerate_lessons.py - Turn Teacher output into a clean training set.\n\nTwo ways in:\n\n  1. HARVEST - scrape real Claude Code sessions off disk. These are the\n     highest-signal examples you have, because they are the Teacher solving\n     *your* actual problems, with real tool calls.\n         python generate_lessons.py harvest --limit 200\n\n  2. INGEST - load a batch of curated examples Claude authored directly\n     (Phase 4 writes lessons_batch_01.json this way).\n         python generate_lessons.py ingest --file lessons/lesson_01.json\n\nBoth paths run the same pipeline:\n     normalize -> quality filter -> near-duplicate dedupe -> train/eval split\n\nOutput:\n     dataset/train.jsonl   dataset/eval.jsonl   dataset/rejected.jsonl\n\nEvery record keeps the Teacher's reasoning trace and exact tool-call JSON -\nthat formatting fidelity is most of what the Student needs to learn.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport os\nimport random\nimport re\nimport sys\nfrom collections import Counter\nfrom dataclasses import dataclass, field, asdict\nfrom pathlib import Path\n\ntry:\n    import yaml\nexcept ImportError:\n    sys.exit(\"Missing dependency: pip install pyyaml\")\n\nHERE = Path(__file__).resolve().parent\nCURRICULUM = HERE / \"curriculum.yaml\"\nDATASET = HERE / \"dataset\"\nRAW = HERE / \"raw_sessions\"\n\n# Where Claude Code keeps its session transcripts on this machine.\nCLAUDE_PROJECTS = Path(os.path.expanduser(\"~\")) / \".claude\" / \"projects\"\n\nPLACEHOLDER_PAT = re.compile(\n    r\"\\b(TODO|FIXME|your code here|insert .{0,20} here|\\.\\.\\.\\s*$|<placeholder>)\",\n    re.IGNORECASE | re.MULTILINE,\n)\nREFUSAL_PAT = re.compile(\n    r\"\\b(I can'?t help with|I'm (unable|not able) to|I won'?t|I cannot assist|\"\n    r\"As an AI language model)\\b\",\n    re.IGNORECASE,\n)\n\n\n# ---------------------------------------------------------------------------\n# Data model\n# ---------------------------------------------------------------------------\n@dataclass\nclass Example:\n    \"\"\"One Teacher->Student training example.\"\"\"\n\n    instruction: str\n    output: str\n    thinking: str = \"\"\n    system: str = \"\"\n    skill: str = \"general\"\n    difficulty: str = \"medium\"\n    tool_calls: list = field(default_factory=list)\n    source: str = \"synthetic\"\n    tags: list = field(default_factory=list)\n\n    def fingerprint(self) -> str:\n        \"\"\"Stable id for exact-duplicate detection.\"\"\"\n        return hashlib.sha256(\n            (self.instruction.strip() + \"||\" + self.output.strip()).encode(\"utf-8\")\n        ).hexdigest()[:16]\n\n    def to_record(self, thinking_tag: str = \"think\") -> dict:\n        \"\"\"Chat-format record. The CoT is embedded so SFT learns to produce it.\"\"\"\n        target = self.output.strip()\n        if self.thinking.strip():\n            target = (\n                f\"<{thinking_tag}>\\n{self.thinking.strip()}\\n</{thinking_tag}>\\n\\n\"\n                + target\n            )\n        messages = []\n        if self.system.strip():\n            messages.append({\"role\": \"system\", \"content\": self.system.strip()})\n        messages.append({\"role\": \"user\", \"content\": self.instruction.strip()})\n        messages.append({\"role\": \"assistant\", \"content\": target})\n        return {\n            \"messages\": messages,\n            \"meta\": {\n                \"skill\": self.skill,\n                \"difficulty\": self.difficulty,\n                \"source\": self.source,\n                \"has_thinking\": bool(self.thinking.strip()),\n                \"has_tool_calls\": bool(self.tool_calls),\n                \"fingerprint\": self.fingerprint(),\n                \"tags\": self.tags,\n            },\n        }\n\n\n# ---------------------------------------------------------------------------\n# Near-duplicate detection (MinHash-free Jaccard over word shingles)\n# ---------------------------------------------------------------------------\ndef shingles(text: str, k: int) -> set[str]:\n    words = re.findall(r\"\\w+\", text.lower())\n    if len(words) < k:\n        return {\" \".join(words)} if words else set()\n    return {\" \".join(words[i : i + k]) for i in range(len(words) - k + 1)}\n\n\ndef jaccard(a: set[str], b: set[str]) -> float:\n    if not a or not b:\n        return 0.0\n    inter = len(a & b)\n    return inter / (len(a) + len(b) - inter)\n\n\ndef dedupe(examples: list[Example], threshold: float, k: int) -> tuple[list, list]:\n    \"\"\"Drop exact and near-duplicates. Keeps the first occurrence.\n\n    O(n^2) over shingle sets. Fine for the batch sizes here (hundreds);\n    swap in datasketch MinHashLSH if the set ever reaches tens of thousands.\n    \"\"\"\n    kept: list[Example] = []\n    kept_shingles: list[set[str]] = []\n    seen_fp: set[str] = set()\n    rejected: list[tuple[Example, str]] = []\n\n    for ex in examples:\n        fp = ex.fingerprint()\n        if fp in seen_fp:\n            rejected.append((ex, \"exact_duplicate\"))\n            continue\n        sh = shingles(ex.instruction + \" \" + ex.output, k)\n        dup_of = None\n        for i, prev in enumerate(kept_shingles):\n            if jaccard(sh, prev) >= threshold:\n                dup_of = i\n                break\n        if dup_of is not None:\n            rejected.append((ex, f\"near_duplicate_of_{dup_of}\"))\n            continue\n        seen_fp.add(fp)\n        kept.append(ex)\n        kept_shingles.append(sh)\n\n    return kept, rejected\n\n\n# ---------------------------------------------------------------------------\n# Quality filtering\n# ---------------------------------------------------------------------------\ndef quality_check(ex: Example, cfg: dict) -> str | None:\n    \"\"\"Return a rejection reason, or None if the example passes.\"\"\"\n    g = cfg[\"generation\"]\n    q = g[\"quality_filters\"]\n    body = ex.output.strip()\n\n    if len(body) < g[\"min_chars\"]:\n        return f\"too_short({len(body)}<{g['min_chars']})\"\n    if len(body) > g[\"max_chars\"]:\n        return f\"too_long({len(body)}>{g['max_chars']})\"\n    if not ex.instruction.strip():\n        return \"empty_instruction\"\n    if q.get(\"require_thinking\") and not ex.thinking.strip():\n        return \"missing_thinking\"\n    if q.get(\"reject_refusals\") and REFUSAL_PAT.search(body):\n        return \"refusal\"\n    if q.get(\"reject_placeholders\") and PLACEHOLDER_PAT.search(body):\n        return \"placeholder\"\n    # Any fenced JSON that claims to be a tool call must actually parse.\n    for block in re.findall(r\"```json\\s*(.*?)```\", body, re.DOTALL):\n        try:\n            json.loads(block)\n        except json.JSONDecodeError as e:\n            return f\"invalid_json_block({e.msg})\"\n    return None\n\n\ndef enforce_skill_balance(examples: list[Example], max_ratio: float) -> tuple[list, list]:\n    \"\"\"Stop one skill from swamping the batch, which skews the LoRA.\"\"\"\n    if not examples:\n        return [], []\n    cap = max(1, int(len(examples) * max_ratio))\n    counts: Counter = Counter()\n    kept, rejected = [], []\n    for ex in examples:\n        if counts[ex.skill] >= cap:\n            rejected.append((ex, f\"skill_over_cap({ex.skill}>{cap})\"))\n            continue\n        counts[ex.skill] += 1\n        kept.append(ex)\n    return kept, rejected\n\n\n# ---------------------------------------------------------------------------\n# Source 1: harvest real Claude Code transcripts\n# ---------------------------------------------------------------------------\ndef harvest_sessions(limit: int, min_output_chars: int = 400) -> list[Example]:\n    \"\"\"Mine ~/.claude/projects/**/*.jsonl for Teacher turns worth learning from.\n\n    Claude Code writes one JSONL per session: each line is an event with a\n    `message` holding role + content blocks. We pair each user turn with the\n    assistant turn that answered it, preserving thinking blocks and tool_use\n    blocks verbatim.\n    \"\"\"\n    if not CLAUDE_PROJECTS.exists():\n        print(f\"  no transcripts at {CLAUDE_PROJECTS}\", file=sys.stderr)\n        return []\n\n    files = sorted(\n        CLAUDE_PROJECTS.rglob(\"*.jsonl\"), key=lambda p: p.stat().st_mtime, reverse=True\n    )\n    print(f\"  scanning {len(files)} transcript file(s)\")\n    out: list[Example] = []\n\n    for fp in files:\n        if len(out) >= limit:\n            break\n        try:\n            lines = fp.read_text(encoding=\"utf-8\", errors=\"replace\").splitlines()\n        except OSError:\n            continue\n\n        pending_user: str | None = None\n        for line in lines:\n            if len(out) >= limit:\n                break\n            line = line.strip()\n            if not line:\n                continue\n            try:\n                ev = json.loads(line)\n            except json.JSONDecodeError:\n                continue\n\n            msg = ev.get(\"message\")\n            if not isinstance(msg, dict):\n                continue\n            role = msg.get(\"role\")\n            content = msg.get(\"content\")\n\n            text_parts, think_parts, tool_calls = [], [], []\n            if isinstance(content, str):\n                text_parts.append(content)\n            elif isinstance(content, list):\n                for blk in content:\n                    if not isinstance(blk, dict):\n                        continue\n                    btype = blk.get(\"type\")\n                    if btype == \"text\":\n                        text_parts.append(blk.get(\"text\", \"\"))\n                    elif btype == \"thinking\":\n                        think_parts.append(blk.get(\"thinking\", \"\"))\n                    elif btype == \"tool_use\":\n                        tool_calls.append(\n                            {\"name\": blk.get(\"name\"), \"input\": blk.get(\"input\")}\n                        )\n                    # tool_result blocks are deliberately skipped: they are\n                    # environment output, not Teacher behaviour to imitate.\n\n            text = \"\\n\".join(t for t in text_parts if t).strip()\n\n            if role == \"user\":\n                # Skip tool-result-only turns and system reminders.\n                if text and \"<system-reminder>\" not in text:\n                    pending_user = text\n                continue\n\n            if role == \"assistant\" and pending_user:\n                thinking = \"\\n\".join(think_parts).strip()\n                # Render tool calls into the target so formatting is learned.\n                body = text\n                if tool_calls:\n                    rendered = \"\\n\\n\".join(\n                        f\"```json\\n{json.dumps(tc, indent=2)}\\n```\" for tc in tool_calls\n                    )\n                    body = (body + \"\\n\\n\" + rendered).strip()\n                if len(body) >= min_output_chars:\n                    out.append(\n                        Example(\n                            instruction=pending_user,\n                            output=body,\n                            thinking=thinking,\n                            skill=\"harvested_session\",\n                            source=f\"session:{fp.stem[:8]}\",\n                            tool_calls=tool_calls,\n                            tags=[\"real_session\"],\n                        )\n                    )\n                pending_user = None\n\n    print(f\"  harvested {len(out)} candidate pair(s)\")\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Source 2: ingest a curated JSON batch\n# ---------------------------------------------------------------------------\ndef load_batch(path: Path) -> list[Example]:\n    data = json.loads(path.read_text(encoding=\"utf-8\"))\n    items = data[\"examples\"] if isinstance(data, dict) else data\n    out = []\n    for d in items:\n        out.append(\n            Example(\n                instruction=d.get(\"instruction\") or d.get(\"prompt\", \"\"),\n                output=d.get(\"output\") or d.get(\"response\", \"\"),\n                thinking=d.get(\"thinking\", \"\"),\n                system=d.get(\"system\", \"\"),\n                skill=d.get(\"skill\", \"general\"),\n                difficulty=d.get(\"difficulty\", \"medium\"),\n                tool_calls=d.get(\"tool_calls\", []),\n                source=d.get(\"source\", f\"curated:{path.stem}\"),\n                tags=d.get(\"tags\", []),\n            )\n        )\n    print(f\"  loaded {len(out)} curated example(s) from {path.name}\")\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Pipeline\n# ---------------------------------------------------------------------------\ndef write_jsonl(path: Path, records: list[dict], append: bool) -> int:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    mode = \"a\" if (append and path.exists()) else \"w\"\n    with path.open(mode, encoding=\"utf-8\") as f:\n        for r in records:\n            f.write(json.dumps(r, ensure_ascii=False) + \"\\n\")\n    with path.open(encoding=\"utf-8\") as f:\n        return sum(1 for _ in f)\n\n\ndef existing_fingerprints(path: Path) -> set[str]:\n    \"\"\"So repeated runs never re-add examples already in the training set.\"\"\"\n    fps: set[str] = set()\n    if not path.exists():\n        return fps\n    with path.open(encoding=\"utf-8\") as f:\n        for line in f:\n            try:\n                fps.add(json.loads(line)[\"meta\"][\"fingerprint\"])\n            except Exception:\n                continue\n    return fps\n\n\ndef run(examples: list[Example], cfg: dict, append: bool, dry_run: bool) -> dict:\n    gen = cfg[\"generation\"]\n    stats: Counter = Counter()\n    rejected_all: list[tuple[Example, str]] = []\n\n    print(f\"\\n[1/4] quality filtering {len(examples)} example(s)\")\n    passed = []\n    for ex in examples:\n        reason = quality_check(ex, cfg)\n        if reason:\n            rejected_all.append((ex, reason))\n            stats[f\"reject:{reason.split('(')[0]}\"] += 1\n        else:\n            passed.append(ex)\n    print(f\"      {len(passed)} passed, {len(examples) - len(passed)} rejected\")\n\n    print(f\"[2/4] deduplicating (jaccard >= {gen['dedupe']['threshold']})\")\n    deduped, dup_rejects = dedupe(\n        passed, gen[\"dedupe\"][\"threshold\"], gen[\"dedupe\"][\"shingle_size\"]\n    )\n    rejected_all += dup_rejects\n    print(f\"      {len(deduped)} unique, {len(dup_rejects)} duplicate(s) dropped\")\n\n    # Drop anything already present in train.jsonl from earlier lessons.\n    known = existing_fingerprints(DATASET / \"train.jsonl\") | existing_fingerprints(\n        DATASET / \"eval.jsonl\"\n    )\n    if known:\n        before = len(deduped)\n        fresh, stale = [], []\n        for ex in deduped:\n            (fresh if ex.fingerprint() not in known else stale).append(ex)\n        rejected_all += [(e, \"already_in_dataset\") for e in stale]\n        deduped = fresh\n        print(f\"      {before - len(deduped)} already in dataset, {len(deduped)} new\")\n\n    print(f\"[3/4] enforcing skill balance (max {gen['quality_filters']['max_per_skill_ratio']:.0%}/skill)\")\n    balanced, bal_rejects = enforce_skill_balance(\n        deduped, gen[\"quality_filters\"][\"max_per_skill_ratio\"]\n    )\n    rejected_all += bal_rejects\n    print(f\"      {len(balanced)} kept, {len(bal_rejects)} over cap\")\n\n    print(f\"[4/4] splitting (holdout {cfg['eval']['holdout_ratio']:.0%})\")\n    random.seed(cfg[\"training\"][\"optim\"][\"seed\"])\n    random.shuffle(balanced)\n    n_eval = int(len(balanced) * cfg[\"eval\"][\"holdout_ratio\"])\n    eval_set, train_set = balanced[:n_eval], balanced[n_eval:]\n\n    tag = gen[\"thinking_tag\"]\n    if dry_run:\n        print(\"\\n(dry run - nothing written)\")\n    else:\n        n_tr = write_jsonl(DATASET / \"train.jsonl\",\n                           [e.to_record(tag) for e in train_set], append)\n        n_ev = write_jsonl(DATASET / \"eval.jsonl\",\n                           [e.to_record(tag) for e in eval_set], append)\n        write_jsonl(\n            DATASET / \"rejected.jsonl\",\n            [{\"reason\": r, **asdict(e)} for e, r in rejected_all],\n            append,\n        )\n        print(f\"\\n  dataset/train.jsonl  +{len(train_set):4d}  (total {n_tr})\")\n        print(f\"  dataset/eval.jsonl   +{len(eval_set):4d}  (total {n_ev})\")\n        print(f\"  dataset/rejected.jsonl +{len(rejected_all):2d}  (audit trail)\")\n\n    by_skill = Counter(e.skill for e in balanced)\n    with_cot = sum(1 for e in balanced if e.thinking.strip())\n    print(f\"\\n  with reasoning traces: {with_cot}/{len(balanced)}\")\n    print(f\"  by skill: {dict(by_skill)}\")\n    if rejected_all:\n        print(f\"  top rejection reasons: {dict(Counter(r.split('(')[0] for _, r in rejected_all).most_common(5))}\")\n\n    return {\"train\": len(train_set), \"eval\": len(eval_set), \"rejected\": len(rejected_all)}\n\n\ndef main() -> int:\n    p = argparse.ArgumentParser(description=__doc__,\n                                formatter_class=argparse.RawDescriptionHelpFormatter)\n    sub = p.add_subparsers(dest=\"cmd\", required=True)\n\n    h = sub.add_parser(\"harvest\", help=\"Mine real Claude Code sessions.\")\n    h.add_argument(\"--limit\", type=int, default=200)\n    h.add_argument(\"--min-chars\", type=int, default=400)\n\n    i = sub.add_parser(\"ingest\", help=\"Load a curated JSON batch.\")\n    i.add_argument(\"--file\", required=True, type=Path)\n\n    s = sub.add_parser(\"stats\", help=\"Summarize the current dataset.\")\n\n    for sp in (h, i):\n        sp.add_argument(\"--no-append\", action=\"store_true\",\n                        help=\"Overwrite the dataset instead of appending.\")\n        sp.add_argument(\"--dry-run\", action=\"store_true\")\n\n    args = p.parse_args()\n    cfg = yaml.safe_load(CURRICULUM.read_text(encoding=\"utf-8\"))\n\n    if args.cmd == \"stats\":\n        for name in (\"train\", \"eval\", \"rejected\"):\n            fp = DATASET / f\"{name}.jsonl\"\n            if not fp.exists():\n                print(f\"{name:9s}: (none)\")\n                continue\n            rows = [json.loads(l) for l in fp.read_text(encoding=\"utf-8\").splitlines() if l.strip()]\n            print(f\"{name:9s}: {len(rows)} rows\")\n            if name != \"rejected\" and rows:\n                sk = Counter(r.get(\"meta\", {}).get(\"skill\", \"?\") for r in rows)\n                cot = sum(1 for r in rows if r.get(\"meta\", {}).get(\"has_thinking\"))\n                print(f\"           skills={dict(sk)}  with_cot={cot}\")\n        return 0\n\n    if args.cmd == \"harvest\":\n        print(\"Harvesting real Claude Code sessions...\")\n        examples = harvest_sessions(args.limit, args.min_chars)\n    else:\n        path = args.file if args.file.is_absolute() else HERE / args.file\n        if not path.exists():\n            sys.exit(f\"no such file: {path}\")\n        examples = load_batch(path)\n\n    if not examples:\n        print(\"No examples found. Nothing to do.\")\n        return 1\n\n    run(examples, cfg, append=not args.no_append, dry_run=args.dry_run)\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"
