xample, if it is substantial.\"\"\"\n            nonlocal cur_prompt, texts, thinks, tools\n            if cur_prompt:\n                body = \"\\n\\n\".join(t for t in texts if t.strip()).strip()\n                if tools:\n                    rendered = \"\\n\\n\".join(\n                        f\"```json\\n{json.dumps(tc, indent=2)}\\n```\" for tc in tools\n                    )\n                    body = (body + \"\\n\\n\" + rendered).strip()\n                if len(body) >= min_output_chars:\n                    out.append(\n                        Example(\n                            instruction=cur_prompt,\n                            output=body,\n                            thinking=\"\\n\\n\".join(t for t in thinks if t.strip()).strip(),\n                            skill=\"harvested_session\",\n                            source=f\"session:{fp.stem[:8]}\",\n                            tool_calls=tools,\n                            tags=[\"real_session\"] + ([\"tool_use\"] if tools else []),\n                        )\n                    )\n            cur_prompt, texts, thinks, tools = None, [], [], []\n\n        for line in lines:\n            if len(out) >= limit:\n                break\n            line = line.strip()\n            if not line:\n                continue\n            try:\n                ev = json.loads(line)\n            except json.JSONDecodeError:\n                continue\n\n            etype = ev.get(\"type\")\n            if etype not in (\"user\", \"assistant\"):\n                continue  # mode/attachment/file-history bookkeeping events\n            msg = ev.get(\"message\")\n            if not isinstance(msg, dict):\n                continue\n            content = msg.get(\"content\")\n\n            if etype == \"user\":\n                # String content == a real prompt, and it ends the previous turn.\n                if isinstance(content, str):\n                    cleaned = _strip_reminders(content)\n                  