def _strip_reminders(text: str) -> str:
    """Drop <system-reminder> blocks - harness noise, not user intent."""
    return re.sub(r"<system-reminder>.*?</system-reminder>", "", text, flags=re.DOTALL).strip()


def harvest_sessions(limit: int, min_output_chars: int = 400) -> list[Example]:
    """Mine ~/.claude/projects/**/*.jsonl for Teacher turns worth learning from.

    Transcript shape, verified against real sessions on this machine:
      * A genuine user prompt has `message.content` as a **string**.
      * A tool result has `message.content` as a **list** of `tool_result`
        blocks - that is environment output, not user intent, so it does not
        start a new turn.
      * One logical assistant reply is split across **many** streamed events,
        each carrying some mix of `thinking`, `text` and `tool_use` blocks.

    So a training pair is: one string-content user prompt, plus every assistant
    block that follows it until the next string-content user prompt. We
    concatenate those, keeping the reasoning trace and the exact tool-call JSON.
    """
    if not CLAUDE_PROJECTS.exists():
        print(f"  no transcripts at {CLAUDE_PROJECTS}", file=sys.stderr)
        return []

    files = sorted(
        CLAUDE_PROJECTS.rglob("*.jsonl"), key=lambda p: p.stat().st_mtime, reverse=True
    )
    print(f"  scanning {len(files)} transcript file(s)")
    out: list[Example] = []

    for fp in files:
        if len(out) >= limit:
            break
        try:
            lines = fp.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            continue

        # Accumulators for the assistant reply currently being assembled.
        cur_prompt: str | None = None
        texts: list[str] = []
        thinks: list[str] = []
        tools: list[dict] = []

        def flush() -> None:
            """Emit the assembled turn as one Example, if it is substantial."""
            nonlocal cur_prompt, texts, thinks, tools
            if cur_prompt:
                body = "\n\n".join(t for t in texts if t.strip()).strip()
                if tools:
                    rendered = "\n\n".join(
                        f"```json\n{json.dumps(tc, indent=2)}\n```" for tc in tools
                    )
                    body = (body + "\n\n" + rendered).strip()
                if len(body) >= min_output_chars:
                    out.append(
                        Example(
                            instruction=cur_prompt,
                            output=body,
                            thinking="\n\n".join(t for t in thinks if t.strip()).strip(),
                            skill="harvested_session",
                            source=f"session:{fp.stem[:8]}",
                            tool_calls=tools,
                            tags=["real_session"] + (["tool_use"] if tools else []),
                        )
                    )
            cur_prompt, texts, thinks, tools = None, [], [], []

        for line in lines:
            if len(out) >= limit:
                break
            line = line.strip()
            if not line:
                continue
            try:
                ev = json.loads(line)
            except json.JSONDecodeError:
                continue

            etype = ev.get("type")
            if etype not in ("user", "assistant"):
                continue  # mode/attachment/file-history bookkeeping events
            msg = ev.get("message")
            if not isinstance(msg, dict):
                continue
            content = msg.get("content")

            if etype == "user":
                # String content == a real prompt, and it ends the previous turn.
                if isinstance(content, str):
                    cleaned = _strip_reminders(content)
                    flush()
                    if cleaned:
                        cur_prompt = cleaned
                # list content == tool_result; ignore, the turn continues.
                continue

            # assistant event: accumulate its blocks into the current turn
            if cur_prompt is None:
                continue
            if isinstance(content, str):
                texts.append(content)
            elif isinstance(content, list):
                for blk in content:
                    if not isinstance(blk, dict):
                        continue
                    btype = blk.get("type")
                    if btype == "text":
                        texts.append(blk.get("text", ""))
                    elif btype == "thinking":
                        thinks.append(blk.get("thinking", ""))
                    elif btype == "tool_use":
                        tools.append({"name": blk.get("name"), "input": blk.get("input")})

        flush()  # don't lose the final turn of the session

    print(f"  harvested {len(out)} candidate pair(s)")
    return out

