import re, os, glob

root = os.getcwd()
md_files = glob.glob("**/*.md", recursive=True)
md_files = [m for m in md_files if "node_modules" not in m and ".git" not in m]

link_re = re.compile(r'\]\(([^)]+)\)')
img_re = re.compile(r'<img[^>]*src="([^"]+)"')

broken = []
for md in md_files:
    try:
        text = open(md, encoding="utf-8").read()
    except Exception as e:
        continue
    base = os.path.dirname(md)
    for m in link_re.finditer(text):
        target = m.group(1).split(' ')[0]
        if target.startswith(('http://','https://','mailto:','#')):
            continue
        # strip anchor
        path_part = target.split('#')[0]
        if not path_part:
            continue
        if path_part.startswith('/'):
            full = os.path.join(root, path_part.lstrip('/'))
        else:
            full = os.path.normpath(os.path.join(base, path_part))
        if not os.path.exists(full):
            broken.append((md, target, full))
    for m in img_re.finditer(text):
        target = m.group(1)
        if target.startswith(('http://','https://','data:')):
            continue
        path_part = target.split('#')[0]
        full = os.path.normpath(os.path.join(base, path_part))
        if not os.path.exists(full):
            broken.append((md, target, full))

for b in broken:
    print(b)
print("TOTAL", len(broken))
