function SizeOf($p) {
  if (-not $p) { return $null }
  if (-not (Test-Path -LiteralPath $p)) { return $null }
  $m = Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue |
       Measure-Object -Property Length -Sum
  return @($m.Sum, $m.Count)
}

$rows = @()
