    foreach ($d in @('C','D','E')) {
      $m = Get-ChildItem -LiteralPath "${d}:\`$Recycle.Bin" -Recurse -Force -File -ErrorAction SilentlyContinue |
           Measure-Object -Property Length -Sum
      $sum += $m.Sum; $cnt += $m.Count
    }
    $rows += [pscustomobject]@{ Item=$k; MB=[math]::Round($sum/1MB,1); Files=$cnt; Path='C/D/E:\$Recycle.Bin' }
    continue
  }
  $r = SizeOf $p
  if ($null -eq $r) { continue }
  $rows += [pscustomobject]@{ Item=$k; MB=[math]::Round($r[0]/1MB,1); Files=$r[1]; Path=$p }
}

$rows | Sort-Object MB -Descending | Format-Table -AutoSize -Wrap
"
