def fmt_duration(ms):
    """Milliseconds -> "2h 14m" / "41m" / "under a minute"."""
    total = max(0, int(ms or 0)) // 1000
    hours, rem = divmod(total, 3600)
    minutes = rem // 60
    if hours:
        return "%dh %dm" % (hours, minutes)
    if minutes:
        return "%dm" % minutes
    return "under a minute"


def game_display(cfg, exe):
    """Pretty name for a foreground executable."""
    if not exe:
        return None
    names = cfg.get('game_names') or {}
    for key, pretty in names.items():
        if key.lower() == exe.lower():
            return pretty
    stem = exe[:-4] if exe.lower().endswith('.exe') else exe
    return stem or None


def chat_payload(cfg):
    """Pre-formatted answers for chat commands, built from live state.

    Returns whole sentences rather than raw numbers on purpose. Streamer.bot
    can only concatenate strings in its GUI, so every decision that needs a
    conditional - is the stream live, is a match in progress, which game -
    is made here in Python where it is testable.
    """
    live = bool(LATEST.get('streaming'))
    game = LATEST.get('game')
    val_ok = bool(LATEST.get('ok'))
    mc = LATEST.get('minecraft') or {}

    if live:
        uptime_text = "live for %s" % fmt_duration(LATEST.get('uptime_ms'))
    else:
        uptime_text = "not live right now"

    game_text = game or cfg.get('chat_idle_text') or "just chatting"

    # --- !session: the most specific thing we actually know -------------
    if val_ok:
        bits = ["VALORANT"]
        if LATEST.get('map_name'):
            bits.append(str(LATEST['map_name']))
        if LATEST.get('rank'):
            bits.append(str(LATEST['rank']))
        today = LATEST.get('today') or {}
        wins, losses = today.get('wins'), today.get('losses')
        if wins is not None and losses is not None:
            rec = "today %dW %dL" % (wins, losses)
            streak, kind = today.get('streak'), today.get('streak_kind')
            if streak and streak > 1 and kind:
                rec += " (%d %s streak)" % (streak, kind)
            bits.append(rec)
        session_text = " | ".join(bits)
    elif game == "Minecraft" and mc:
        bits = ["Minecraft"]
        bits.append("%d death%s today"
                    % (mc.get('deaths', 0),
                       "" if mc.get('deaths') == 1 else "s"))
        if mc.get('advancements'):
            bits.append("%d advancements" % mc['advancements'])
        since = mc.get('since_death_s')
        if since:
            bits.append("death-free for %s" % fmt_duration(since * 1000))
        session_text = " | ".join(bits)
    elif game:
        session_text = game
    else:
        session_text = cfg.get('chat_idle_text') or "just chatting"

    if live:
        session_text = "%s | %s" % (session_text,
                                    fmt_duration(LATEST.get('uptime_ms')))

    # --- health: only meaningful while actually streaming ---------------
    health = LATEST.get('health') or {}
    level = health.get('level') or 'off'
    if not live or level == 'off':
        health_text = "not live right now"
    elif level == 'ok':
        health_text = "stream health: good"
    else:
        health_text = ("stream health: %s (%.2f%% dropped)"
                       % ("degraded" if level == 'warn' else "poor",
                          health.get('dropped_pct') or 0.0))

    return {
        "ok": True,
        "live": live,
        "uptime_text": uptime_text,
        "game_text": game_text,
        "session_text": session_text,
        "specs_text": cfg.get('specs_text') or "",
        "health_text": health_text,
    }


