# /say/<key> returns ONE sentence as text/plain. Streamer.bot's
# Fetch URL subaction drops a response body straight into a
# variable, so a plaintext endpoint means the bot says exactly
# what we serve - no JSON path syntax to get wrong, and the
# wording stays reviewable here rather than in a GUI field.
if route.startswith('/say/'):
    key = route[len('/say/'):].strip('/')
    if not cfg.get('chat_enabled', True):
        return self._text("chat commands are disabled")
    try:
        payload = chat_payload(cfg)
    except Exception as e:
        log("chat payload failed: %s" % e)
        return self._text("that information is unavailable "
                          "right now")
    text = payload.get(key + "_text")
    if not text:
        self.send_error(404, "no such say key")
        return None
    return self._text(text)

