def valorant_result_text(today, before, after):
    """One line for a finished Valorant match.

    `before`/`after` are (wins, losses, draws) tallies; whichever moved tells
    us the result without having to re-derive it from the score.
    """
    if after[0] > before[0]:
        opener = "Match won."
    elif after[1] > before[1]:
        opener = "Match lost."
    else:
        opener = "Match drawn."
    record = "Today: %dW %dL" % (today.get('wins', 0), today.get('losses', 0))
    if today.get('draws'):
        record += " %dD" % today['draws']
    streak, kind = today.get('streak'), today.get('streak_kind')
    if streak and streak > 1 and kind:
        record += " (%d %s streak)" % (streak, kind)
    return "%s %s." % (opener, record)


