    "content": "#!/usr/bin/env python3\n\"\"\"Restore the Gaming cam stack to its pre-autopilot position and lock the\ncam items in every scene that has them.\n\nWhy: obs-autopilot rewrote GRP - Cam + Inputs to the Valorant minimap-cover\nspot (15,15) on its last run. The pre-clobber values live in Main.json.bak\n(written 17:19:24, before that run). We take positions from the .bak rather\nthan recomputing a delta so the restore is exact, and only for the items the\ndiff proved had moved -- everything else in the collection is left untouched.\n\nOBS must be closed: it rewrites this file wholesale on exit.\n\"\"\"\nimport json\nimport os\nimport shutil\nimport sys\n\nSCENES = r\"C:\\Users\\Srini\\AppData\\Roaming\\obs-studio\\basic\\scenes\\Main.json\"\nBAK = SCENES + \".bak\"\n\n# Exactly the items the bak/current diff showed the autopilot had moved.\nRESTORE = {\n    (\"1 - Gaming\", \"CAM - Ambient Glow\"),\n    (\"1 - Gaming\", \"CAM - Card\"),\n    (\"1 - Gaming\", \"CAM - Frame\"),\n    (\"1 - Gaming\", \"CAM - Webcam\"),\n    (\"1 - Gaming\", \"GRP - Cam + Inputs\"),\n    (\"1 - Gaming\", \"IN - Keyboard\"),\n    (\"1 - Gaming\", \"IN - Mouse\"),\n}\n\n# Prefixes of the cam stack, locked so a stray drag in the preview cannot\n# nudge them. Note this only blocks the GUI -- obs-websocket can still move a\n# locked item, which is why the autopilot config fix is the real guard.\nLOCK_PREFIXES = (\"CAM - \", \"IN - \", \"GRP - Cam\")\n\n\ndef scene_items(doc):\n    for src in doc[\"sources\"]:\n        if src[\"id\"] != \"scene\":\n            continue\n        for item in src[\"settings\"].get(\"items\", []):\n            yield src[\"name\"], item\n\n\ndef main():\n    if not os.path.exists(BAK):\n        sys.exit(\"missing %s -- nothing to restore from\" % BAK)\n\n    cur = json.load(open(SCENES, encoding=\"utf-8\"))\n    bak = json.load(open(BAK, encoding=\"utf-8\"))\n\n    good = {(s, i[\"name\"]): i[\"pos\"] for s, i in scene_items(bak)}\n\n    missing = RESTORE - set(good)\n    if missing:\n        sys.exit(\"not in backup, refusing to guess: %s\" % sorted(missing))\n\n    restored, locked = [], []\n    for scene, item in scene_items(cur):\n        key = (scene, item[\"name\"])\n        if key in RESTORE:\n            before = (item[\"pos\"][\"x\"], item[\"pos\"][\"y\"])\n            item[\"pos\"] = dict(good[key])\n            after = (item[\"pos\"][\"x\"], item[\"pos\"][\"y\"])\n            if before != after:\n                restored.append((scene, item[\"name\"], before, after))\n        if item[\"name\"].startswith(LOCK_PREFIXES):\n            if not item.get(\"locked\"):\n                item[\"locked\"] = True\n                locked.append((scene, item[\"name\"]))\n\n    # Write via a temp file so a crash mid-write cannot leave OBS with a\n    # truncated scene collection.\n    tmp = SCENES + \".tmp\"\n    with open(tmp, \"w\", encoding=\"utf-8\") as fh:\n        json.dump(cur, fh, indent=4, ensure_ascii=False)\n    json.load(open(tmp, encoding=\"utf-8\"))  # parse-check before swapping in\n    shutil.copy2(SCENES, SCENES + \".pre-cam-patch\")\n    os.replace(tmp, SCENES)\n\n    print(\"restored %d positions:\" % len(restored))\n    for scene, name, before, after in restored:\n        print(\"  %-14s %-22s %s -> %s\" % (scene, name, before, after))\n    print(\"locked %d items:\" % len(locked))\n    for scene, name in locked:\n        print(\"  %-14s %s\" % (scene, name))\n\n\nif __name__ == \"__main__\":\n    main()\n"
  }
