def secret_migrate() -> None:
    """Move the plaintext password out of autopilot.config.json into the
    DPAPI store, non-interactively, and strip it from the JSON."""
    if not CONFIG.exists():
        sys.exit("no %s" % CONFIG)
    cfg = json.loads(CONFIG.read_text(encoding="utf-8"))
    pw = cfg.get("password")
    if not pw:
        print("no plaintext password in config -- nothing to migrate")
        return

    SECRET_DIR.mkdir(exist_ok=True)
    SECRET_FILE.write_bytes(_dpapi(pw.encode("utf-8"), encrypt=True))
    os.system('icacls "%s" /inheritance:r /grant:r "%%USERNAME%%:(R,W)" >nul 2>&1'
              % SECRET_FILE)

    # Verify the round trip BEFORE removing the only copy.
    back = _dpapi(SECRET_FILE.read_bytes(), encrypt=False).decode("utf-8")
    if back != pw:
        sys.exit("DPAPI round-trip mismatch -- refusing to strip plaintext")

    cfg["password"] = ""
    CONFIG.write_text(json.dumps(cfg, indent=2), encoding="utf-8")
    print("migrated to %s (DPAPI, user-scoped); plaintext cleared from %s"
          % (SECRET_FILE, CONFIG.name))


def resolve_password(cfg: dict | None = None) -> str:
    """Shared credential resolution, importable by other tools."""
    pw = os.environ.get("OBS_WS_PASSWORD")
    if pw:
        return pw
    if SECRET_FILE.exists():
        try:
            return _dpapi(SECRET_FILE.read_bytes(), encrypt=False).decode("utf-8")
        except OSError as e:
            print("warning: could not decrypt %s (%s)" % (SECRET_FILE, e),
                  file=sys.stderr)
    if cfg is None and CONFIG.exists():
        cfg = json.loads(CONFIG.read_text(encoding="utf-8"))
