New-Item -ItemType Directory -Force -Path $dest | Out-Null

# OBS keeps handles open on parts of its config tree while running, so a plain
# recursive copy aborts partway and leaves a silently incomplete backup. Copy
# file-by-file instead and record anything that could not be read, so an
# incomplete snapshot is always visible rather than assumed good.
$skipped = New-Object System.Collections.Generic.List[string]

function Copy-Tree {
    param([string]$Source, [string]$Target)
    if (-not (Test-Path $Source)) { return }
    New-Item -ItemType Directory -Force -Path $Target | Out-Null
    foreach ($item in Get-ChildItem -Recurse -File $Source) {
        $rel = $item.FullName.Substring($Source.Length).TrimStart('\')
        $out = Join-Path $Target $rel
        New-Item -ItemType Directory -Force -Path (Split-Path $out -Parent) | Out-Null
        try {
            Copy-Item -Force -ErrorAction Stop $item.FullName $out
        } catch {
            $skipped.Add($item.FullName)
        }
    }
}

Copy-Tree (Join-Path $obs 'basic')         (Join-Path $dest 'basic')
Copy-Tree (Join-Path $obs 'plugin_config') (Join-Path $dest 'plugin_config')
foreach ($f in 'global.ini','user.ini') {
    $src = Join-Path $obs $f
    if (Test-Path $src) {
        try { Copy-Item -Force -ErrorAction Stop $src $dest }
        catch { $skipped.Add($src) }
    }
}
Copy-Tree 'C:\Users\Srini\obs-tools'    (Join-Path $dest 'obs-tools')
Copy-Tree 'C:\Users\Srini\obs-overlays' (Join-Path $dest 'obs-overlays')

if (Get-Process obs64 -ErrorAction SilentlyContinue) {
    "OBS was RUNNING during this backup - it may not have flushed pending config to disk." |
        Set-Content (Join-Path $dest 'WARNING-obs-was-running.txt')
}

if ($skipped.Count) {
    $skipped | Set-Content (Join-Path $dest 'SKIPPED-FILES.txt')
}

