$sceneDir = Join-Path $dest 'basic\scenes'
$haveScenes = (Test-Path $sceneDir) -and (Get-ChildItem $sceneDir -Filter *.json -ErrorAction SilentlyContinue)

$files = (Get-ChildItem -Recurse -File $dest).Count
