# close-obs.ps1 - ask OBS to quit cleanly, so it flushes its config to disk.
#
# Process.CloseMainWindow() is unreliable here: plugins such as Aitum
# Multistream create their own top-level windows, and Windows may report one of
# those as the process MainWindow, so the close request never reaches OBS
# itself. This finds the real OBS window by title and sends it WM_CLOSE.
#
# This is a graceful quit, never a kill - OBS writes the scene collection on
# exit, and force-killing risks losing or corrupting it.
param([int]$TimeoutSeconds = 40)

Add-Type @'
using System;
using System.Text;
using System.Runtime.InteropServices;
public class ObsWin {
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc cb, IntPtr l);
    public delegate bool EnumWindowsProc(IntPtr h, IntPtr l);
    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
    [DllImport("user32.dll")] public static extern int GetWindowThreadProcessId(IntPtr h, out int pid);
    [DllImport("user32.dll")] public static extern IntPtr SendMessageTimeout(
        IntPtr h, uint msg, IntPtr wp, IntPtr lp, uint flags, uint timeout, out IntPtr result);
}
'@

$proc = Get-Process obs64 -ErrorAction SilentlyContinue
if (-not $proc) { Write-Output 'OBS_NOT_RUNNING'; exit 0 }

$targetPid = $proc.Id
$handles = @()
$cb = [ObsWin+EnumWindowsProc]{
    param($h, $l)
    $wpid = 0
    [ObsWin]::GetWindowThreadProcessId($h, [ref]$wpid) | Out-Null
    if ($wpid -eq $targetPid -and [ObsWin]::IsWindowVisible($h)) {
        $sb = New-Object System.Text.StringBuilder 512
        [ObsWin]::GetWindowText($h, $sb, 512) | Out-Null
        $title = $sb.ToString()
        # The real main window is the one titled "OBS <version> - Profile: ..."
        if ($title -like 'OBS *') { $script:handles += $h }
    }
    return $true
}
[ObsWin]::EnumWindows($cb, [IntPtr]::Zero) | Out-Null

if (-not $handles) { Write-Output 'OBS_MAIN_WINDOW_NOT_FOUND'; exit 1 }

$WM_CLOSE = 0x0010
foreach ($h in $handles) {
    $res = [IntPtr]::Zero
    # SMTO_ABORTIFHUNG = 0x2
    [ObsWin]::SendMessageTimeout($h, $WM_CLOSE, [IntPtr]::Zero, [IntPtr]::Zero, 0x2, 5000, [ref]$res) | Out-Null
}

for ($i = 0; $i -lt $TimeoutSeconds; $i++) {
    Start-Sleep -Seconds 1
    if (-not (Get-Process obs64 -ErrorAction SilentlyContinue)) {
        Write-Output "OBS_CLOSED after ${i}s"
        exit 0
    }
}

Write-Output 'OBS_STILL_RUNNING - not force killing (would risk the scene collection)'
exit 1

