$patterns = 'skipped frames|lagged|dropped frames|rendering lag|encoding overloaded|Could not open|failed|Error|crash|unclean shutdown|[Dd]isconnect|reconnect|stall|freeze|[Ww]arning'
$allMatches = @()
foreach ($log in $logs) {
    $ms = Select-String -Path $log.FullName -Pattern $patterns -AllMatches
