$logs = Get-ChildItem 'C:\Users\Srini\AppData\Roaming\obs-studio\logs' -Filter '*.txt' | Sort-Object LastWriteTime
$patterns = 'skipped frames|lagged frames|dropped frames|rendering lag|encoding overloaded|Could not open|crash|unclean shutdown|[Dd]isconnected|reconnect|Reconnecting|stall|freeze|Stopping recording due to'
$results = @()
foreach ($log in $logs) {
    $ms = Select-String -Path $log.FullName -Pattern $patterns -AllMatches
    foreach ($m in $ms) {
        $results += [PSCustomObject]@{
            File = $log.Name
            Line = $m.LineNumber
            Text = $m.Line.Trim()
        }
    }
}
$results | ForEach-Object { "$($_.File) [$($_.Line)]: $($_.Text)" }
Write-Host ""
Write-Host "TOTAL: $($results.Count)"

$logs = Get-ChildItem 'C:\Users\Srini\AppData\Roaming\obs-studio\logs' -Filter '*.txt' | Sort-Object LastWriteTime
$patterns = 'skipped frames|lagged frames|dropped frames|rendering lag|encoding overloaded|Could not open|crash|unclean shutdown|Stopping recording due to|frames? (skipped|lagged|dropped)|output .*stopped|Reconnecting in|disconnected unexpectedly'
$results = @()
foreach ($log in $logs) {
    $ms = Select-String -Path $log.FullName -Pattern $patterns -AllMatches
    foreach ($m in $ms) {
        if ($m.Line -match 'websocket|WebSocket|DeckLink') { continue }
        $results += [PSCustomObject]@{
            File = $log.Name
            Line = $m.LineNumber
            Text = $m.Line.Trim()
        }
    }
}
$results | ForEach-Object { "$($_.File) [$($_.Line)]: $($_.Text)" }
Write-Host ""
Write-Host "TOTAL: $($results.Count)"

$targetHost = 'aps30.contribute.live-video.net'
$port = 1935
$count = 30
$times = @()
$fails = 0

for ($i = 0; $i -lt $count; $i++) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    try {
        $client = New-Object System.Net.Sockets.TcpClient
        $connectTask = $client.ConnectAsync($targetHost, $port)
        $completed = $connectTask.Wait(3000)
        $sw.Stop()
        if ($completed -and $client.Connected) {
            $times += $sw.Elapsed.TotalMilliseconds
            $client.Close()
        } else {
            $fails++
        }
    } catch {
        $fails++
    }
    Start-Sleep -Milliseconds 200
}

if ($times.Count -gt 0) {
    $sorted = $times | Sort-Object
    $min = $sorted[0]
    $max = $sorted[-1]
    $avg = ($sorted | Measure-Object -Average).Average
    $jitter = 0
    if ($times.Count -gt 1) {
        $diffs = @()
        for ($i = 1; $i -lt $times.Count; $i++) { $diffs += [Math]::Abs($times[$i] - $times[$i-1]) }
        $jitter = ($diffs | Measure-Object -Average).Average
    }
    Write-Host ("Target: {0}:{1}" -f $targetHost, $port)
    Write-Host ("Successful connects: {0}/{1}" -f $times.Count, $count)
    Write-Host ("Failed: {0}" -f $fails)
    Write-Host ("TCP connect time (ms) - min={0:N1} avg={1:N1} max={2:N1}" -f $min, $avg, $max)
    Write-Host ("Avg jitter (ms, abs diff between consecutive): {0:N1}" -f $jitter)
    Write-Host ("Loss rate: {0:N1}%" -f (($fails / $count) * 100))
} else {
    Write-Host "All TCP connect attempts failed ($fails/$count)"
}

