def _json(self, payload):
    body = json.dumps(payload).encode()
    self.send_response(200)
    self.send_header('Content-Type', 'application/json')
    self.send_header('Cache-Control', 'no-store')
    self.send_header('Content-Length', str(len(body)))
    self.end_headers()
    self.wfile.write(body)

def do_GET(self):
    route = self.path.split('?')[0]
    if route == '/state.json':
        return self._json(LATEST)
    # obs-websocket connection details for the audio-reactive pages.
    # Serving it here keeps the password out of every browser
    # source's URL - and so out of the scene collection, which is
    # the file that actually gets shared or screenshotted. This
    # server is bound to 127.0.0.1, so it is no more exposed than
    # the config file it reads from.
    if route == '/ws.json':
        return self._json({"host": "127.0.0.1",
                           "port": cfg['port'],
                           "password": cfg['password']})
    return super().do_GET()

