def start_hud_server(cfg):
    import threading
    from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer

    class Handler(SimpleHTTPRequestHandler):
        def __init__(self, *a, **kw):
            super().__init__(*a, directory=OVERLAY_DIR, **kw)

        def do_GET(self):
            if self.path.split('?')[0] == '/state.json':
                body = json.dumps(LATEST).encode()
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.send_header('Cache-Control', 'no-store')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            return super().do_GET()

        def log_message(self, *a):
            pass       # keep the console readable

    srv = ThreadingHTTPServer(('127.0.0.1', cfg['hud_port']), Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    log("HUD server on http://127.0.0.1:%d (serving %s)"
        % (cfg['hud_port'], OVERLAY_DIR))
