class DailyRecord:
    """Win/loss for today, derived from score at the moment a match ends.

    Local-only: it counts matches it actually observed, so games played
    before autopilot started are not included.
    """

    def __init__(self):
        self.data = {"date": self._today(), "wins": 0, "losses": 0,
                     "draws": 0, "matches": []}
        self._pending = None
        try:
            on_disk = json.load(open(DAILY_PATH, encoding='utf-8'))
            if on_disk.get('date') == self._today():
                self.data = on_disk
        except Exception:
            pass

    @staticmethod
    def _today():
        return time.strftime('%Y-%m-%d')

    def _roll(self):
        if self.data.get('date') != self._today():
            log("new day - resetting W/L (was %dW %dL)"
                % (self.data.get('wins', 0), self.data.get('losses', 0)))
            self.data = {"date": self._today(), "wins": 0, "losses": 0,
                         "draws": 0, "matches": []}
            self._save()

    def _save(self):
        try:
            json.dump(self.data, open(DAILY_PATH, 'w', encoding='utf-8'), indent=2)
        except Exception as e:
            log("daily save failed: %s" % e)

    def observe(self, info):
        self._roll()
        state = info.get('state')
        queue = (info.get('queue') or '').lower()
        ally, enemy = int(info.get('ally') or 0), int(info.get('enemy') or 0)

        if state == 'INGAME':
            # Remember the latest meaningful score; presence often zeroes it
            # the instant the match ends, so the final read is unreliable.
            if queue in COUNTED_QUEUES and (ally + enemy) > 0:
                self._pending = {"ally": ally, "enemy": enemy, "queue": queue,
                                 "map": info.get('map_name') or ''}
        elif self._pending:
            p, self._pending = self._pending, None
            if p['ally'] > p['enemy']:
                self.data['wins'] += 1; result = 'W'
            elif p['ally'] < p['enemy']:
                self.data['losses'] += 1; result = 'L'
            else:
                self.data['draws'] += 1; result = 'D'
            self.data['matches'].append({
                "at": time.strftime('%H:%M'), "result": result,
                "score": "%d-%d" % (p['ally'], p['enemy']),
                "map": p['map'], "queue": p['queue']})
            self._save()
            log("match ended %s %d-%d on %s -> today %dW %dL"
                % (result, p['ally'], p['enemy'], p['map'] or '?',
                   self.data['wins'], self.data['losses']))

    def summary(self):
        self._roll()
        return {"wins": self.data['wins'], "losses": self.data['losses'],
                "draws": self.data['draws'], "date": self.data['date'],
                "matches": self.data['matches'][-8:]}

