ght: 17px; fill: currentColor; flex: none; }\n\n  /* ---------------- round flare ---------------- */\n  #flare {\n    position: fixed; inset: 0; pointer-events: none; opacity: 0;\n    transition: opacity .25s ease;\n  }\n  #flare.show { opacity: 1; animation: flare 1.5s ease-out; }\n  @keyframes flare {\n    0%   { opacity: 1; }\n    100% { opacity: 0; }\n  }\n</style>\n\n<div id=\"flare\"></div>\n\n<div id=\"mic\">\n  <svg viewBox=\"0 0 24 24\"><path d=\"M12 15a3 3 0 0 0 3-3V6a3 3 0 1 0-6 0v6a3 3 0 0 0 3 3zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.92V22h2v-3.08A7 7 0 0 0 19 12h-2zM3.3 2.3 1.9 3.7l18.4 18.4 1.4-1.4z\"/></svg>\n  MIC MUTED\n</div>\n\n<div id=\"bar\">\n  <div id=\"score\">\n    <span class=\"num\" id=\"ally\">0</span>\n    <span class=\"dash\"></span>\n    <span class=\"num\" id=\"enemy\">0</span>\n  </div>\n  <div class=\"sep\"></div>\n  <div class=\"cell\"><span class=\"k\">Map</span><span class=\"v\" id=\"map\">&mdash;</span></div>\n  <div class=\"sep\"></div>\n  <div class=\"cell\"><span class=\"k\">Mode</span><span class=\"v\" id=\"queue\">&mdash;</span></div>\n  <div class=\"sep\"></div>\n  <div class=\"cell\"><span class=\"k\">Rank</span><span class=\"v\" id=\"rank\">&mdash;</span></div>\n  <div class=\"sep\"></div>\n  <div class=\"cell\">\n    <span class=\"k\">Today</span>\n    <span class=\"v\" id=\"today\">&mdash;</span>\n    <span id=\"streak\"></span>\n  </div>\n  <div class=\"sep\" id=\"upsep\"></div>\n  <div class=\"cell\" id=\"upcell\"><span class=\"k\">Uptime</span><span class=\"v\" id=\"uptime\">&mdash;</span></div>\n  <div id=\"mp\">MATCH POINT</div>\n</div>\n\n<script>\n  const Q = new URLSearchParams(location.search);\n  document.documentElement.dataset.accent = (Q.get('accent') || 'valorant').toLowerCase();\n\n  const bar = document.getElementById('bar');\n  const mic = document.getElementById('mic');\n  const flare = document.getElementById('flare');\n  const el = id => document.getElementById(id);\n  const QUEUE_NAMES = {\n    competitive: 'Competitive', unrated: 'Unrated', swiftplay: 'Swiftplay',\n    deathmatch: 'Deathmatch', spikerush: 'Spike Rush', ggteam: 'Escalation',\n    hurm: 'Team Deathmatch', newmap: 'New Map', premier: 'Premier', '': 'Custom'\n  };\n\n  const hhmmss = ms => {\n    const t = Math.max(0, Math.floor(ms / 1000));\n    const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60;\n    const p = n => String(n).padStart(2, '0');\n    return h ? h + ':' + p(m) + ':' + p(s) : p(m) + ':' + p(s);\n  };\n\n  let lastRoundAt = 0, lastAlly = null, lastEnemy = null;\n\n  function bump(node) {\n    node.classList.add('bump');\n    setTimeout(() => node.classList.remove('bump'), 200);\n  }\n\n  function doFlare(who) {\n    const c = who === 'ally' ? 'var(--accent2)' : 'var(--accent)';\n    flare.style.background =\n      'radial-gradient(120% 70% at 50% 100%, ' +\n      'color-mix(in srgb, ' + c + ' 36%, transparent), transparent 62%)';\n    flare.classList.remove('show');\n    void flare.offsetWidth;                 // restart the animation\n    flare.classList.add('show');\n    setTimeout(() => flare.classList.remove('show'), 1500);\n  }\n\n  async function tick() {\n    let s = null;\n    try {\n      s = await (await fetch('/state.json', { cache: 'no-store' })).json();\n    } catch (e) { /* autopilot not running */ }\n\n    // --- mic badge: shown in every state, including menus ---\n    mic.classList.toggle('on', !!(s && s.mic_muted));\n\n    const live = s && s.ok && (s.state === 'INGAME' || s.state === 'PREGAME');\n    if (!live) { bar.classList.remove('on', 'mp'); return; }\n\n    const ally = Number(s.ally) || 0, enemy = Number(s.enemy) || 0;\n    if (lastAlly !== null && ally > lastAlly) bump(el('ally'));\n    if (lastEnemy !== null && enemy > lastEnemy) bump(el('enemy'));\n    lastAlly = ally; lastEnemy = enemy;\n    el('ally').textContent = ally;\n    el('enemy').textContent = enemy;\n    el('map').textContent = s.map_name || '\u2014';\n    el('queue').textContent = QUEUE_NAMES[s.queue] ?? (s.queue || '\u2014');\n    el('rank').textContent = s.rank || '\u2014';\n\n    // --- round flare, driven by autopilot's round event ---\n    const r = s.round;\n    if (r && r.at && r.at !== lastRoundAt) {\n      if (Date.now() / 1000 - r.at < 6) doFlare(r.who);\n      lastRoundAt = r.at;\n    }\n\n    // --- today + streak ---\n    const t = s.today || {};\n    const w = t.wins | 0, l = t.losses | 0, dr = t.draws | 0;\n    el('today').innerHTML =\n      '<span class=\"w\">' + w + 'W</span> &middot; <span class=\"l\">' + l + 'L</span>'\n      + (dr ? ' &middot; <span class=\"d\">' + dr + 'D</span>' : '');\n\n    const sk = el('streak'), n = t.streak | 0, kind = t.streak_kind;\n    if (n >= 2 && (kind === 'W' || kind === 'L')) {\n      sk.textContent = n + (kind === 'W' ? ' WIN STREAK' : ' LOSS STREAK');\n      sk.className = 'on ' + (kind === 'W' ? 'hot' : 'cold');\n    } else {\n      sk.className = '';\n    }\n\n    // --- uptime, only while actually streaming ---\n    if (s.streaming) {\n      el('uptime').textContent = hhmmss(s.uptime_ms || 0);\n      el('upcell').style.display = ''; el('upsep').style.display = '';\n    } else {\n      el('upcell').style.display = 'none'; el('upsep').style.display = 'none';\n    }\n\n    // 12 wins the half-based modes; flag either side sitting on match point.\n    const target = s.queue === 'swiftplay' ? 5 : 13;\n    bar.classList.toggle('mp', Math.max(ally, enemy) === target - 1\n                                && s.state === 'INGAME');\n    bar.classList.add('on');\n  }\n  tick();\n  setInterval(tick, 1000);\n</script>\n"
