    "content": "\"\"\"Report OBS inputs that are in no scene, and local files that are dead.\"\"\"\nimport asyncio, base64, hashlib, json, os\n\nfrom websockets.asyncio.client import connect\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nC = json.load(open(os.path.join(HERE, 'autopilot.config.json'), encoding='utf-8'))\n\n# one-shot utilities whose work is already applied and persisted in OBS\nONE_SHOT = ['apply_hud.py', 'resize_hud.py', 'add_badges.py', 'add_inputs.py',\n            'obs_remove_scenes.py', 'val_probe.py', 'autopilot.out', 'dup.out']\nKEEP = ['obs-autopilot.py', 'layout.py', 'autopilot-launcher.lua',\n        'autopilot.config.json', 'identity.json', 'daily.json', 'clips.log',\n        'autopilot.log', 'run-autopilot.bat', 'test_inputs.py',\n        'scan_orphans.py']\n\n\nasync def main():\n    ws = await connect(\"ws://%s:%d\" % (C['host'], C['port']))\n    hello = json.loads(await ws.recv())\n    d = {\"rpcVersion\": 1, \"eventSubscriptions\": 0}\n    a = hello['d'].get('authentication')\n    if a:\n        sec = base64.b64encode(hashlib.sha256(\n            (C['password'] + a['salt']).encode()).digest()).decode()\n        d['authentication'] = base64.b64encode(hashlib.sha256(\n            (sec + a['challenge']).encode()).digest()).decode()\n    await ws.send(json.dumps({\"op\": 1, \"d\": d}))\n    await ws.recv()\n\n    n = [0]\n\n    async def req(t, data=None):\n        n[0] += 1\n        rid = str(n[0])\n        await ws.send(json.dumps({\"op\": 6, \"d\": {\n            \"requestType\": t, \"requestId\": rid, \"requestData\": data or {}}}))\n        while True:\n            m = json.loads(await ws.recv())\n            if m.get('op') == 7 and m['d']['requestId'] == rid:\n                return m['d'].get('responseData') or {}\n\n    inputs = [i['inputName'] for i in (await req('GetInputList'))['inputs']]\n    scenes = [s['sceneName'] for s in (await req('GetSceneList'))['scenes']]\n\n    used = {}\n    for sc in scenes:\n        for it in (await req('GetSceneItemList', {\"sceneName\": sc}))['sceneItems']:\n            used.setdefault(it['sourceName'], []).append(\n                (sc, it['sceneItemEnabled']))\n\n    print(\"=== OBS inputs (%d) ===\" % len(inputs))\n    for name in sorted(inputs):\n        where = used.get(name)\n        if not where:\n            print(\"  ORPHAN   %-28s in no scene\" % name)\n        else:\n            on = sum(1 for _, e in where if e)\n            print(\"  used     %-28s %d scene(s), %d enabled\" % (name, len(where), on))\n\n    print(\"\\n=== scenes with no items ===\")\n    for sc in scenes:\n        items = (await req('GetSceneItemList', {\"sceneName\": sc}))['sceneItems']\n        if not items:\n            print(\"  EMPTY    %s\" % sc)\n\n    print(\"\\n=== obs-tools files ===\")\n    for f in sorted(os.listdir(HERE)):\n        if f.endswith('.pyc') or f == '__pycache__':\n            continue\n        tag = \"one-shot\" if f in ONE_SHOT else (\"keep\" if f in KEEP else \"review\")\n        print(\"  %-9s %s\" % (tag, f))\n\n    await ws.close()\n\n\nasyncio.run(main())\n"
  }
