"""Health check: find broken references, dead weight and needless complexity."""
import asyncio, base64, hashlib, json, os, urllib.parse

from websockets.asyncio.client import connect

HERE = os.path.dirname(os.path.abspath(__file__))
OVERLAYS = r"C:\Users\Srini\obs-overlays"
C = json.load(open(os.path.join(HERE, 'autopilot.config.json'), encoding='utf-8'))
GLOBAL_AUDIO = {'Desktop Audio', 'Mic/Aux'}

issues, notes = [], []


async def main():
    ws = await connect("ws://%s:%d" % (C['host'], C['port']), max_size=2 ** 24)
    h = json.loads(await ws.recv())
    d = {"rpcVersion": 1, "eventSubscriptions": 0}
    a = h['d'].get('authentication')
    if a:
        s = base64.b64encode(hashlib.sha256(
            (C['password'] + a['salt']).encode()).digest()).decode()
        d['authentication'] = base64.b64encode(hashlib.sha256(
            (s + a['challenge']).encode()).digest()).decode()
    await ws.send(json.dumps({"op": 1, "d": d}))
    await ws.recv()
    n = [0]

    async def req(t, data=None):
        n[0] += 1
        rid = str(n[0])
        await ws.send(json.dumps({"op": 6, "d": {
            "requestType": t, "requestId": rid, "requestData": data or {}}}))
        while True:
            m = json.loads(await ws.recv())
            if m.get('op') == 7 and m['d']['requestId'] == rid:
                return m['d'].get('responseData') or {}

    scenes = [s['sceneName'] for s in (await req('GetSceneList'))['scenes']]
    inputs = {i['inputName']: i['inputKind'] for i in (await req('GetInputList'))['inputs']}

    # where is each source used
    used, per_scene = {}, {}
    for sc in scenes:
        items = (await req('GetSceneItemList', {"sceneName": sc}))['sceneItems']
        per_scene[sc] = items
        for it in items:
            used.setdefault(it['sourceName'], []).append((sc, it['sceneItemEnabled']))

    print("=== 1. orphaned / empty ===")
    for name in sorted(inputs):
        if name not in used and name not in GLOBAL_AUDIO:
            issues.append("orphan source: %s" % name)
            print("  ORPHAN  %s" % name)
    for sc, items in per_scene.items():
        if not items:
            issues.append("empty scene: %s" % sc)
            print("  EMPTY   %s" % sc)
    print("  (none)" if not issues else "")

    print("\n=== 2. sources never enabled anywhere ===")
    for name, where in sorted(used.items()):
        if not any(e for _, e in where):
