            if got and got != str(C['port']):
                issues.append("%s -> stale websocket port %s" % (name, got))
                print("  STALE PORT    %-24s port=%s (should be %s)" % (name, got, C['port'])); bad += 1
        if '127.0.0.1:%d' % C['hud_port'] in url:
