                print("  MISSING HUD   %-24s %s" % (name, fn)); bad += 1
    print("  (none)" if not bad else "")

    print("\n=== 4. canvas vs displayed size ===")
    mism = 0
    for sc, items in per_scene.items():
        for it in items:
            nm = it['sourceName']
            if inputs.get(nm) != 'browser_source':
                continue
            st = (await req('GetInputSettings', {"inputName": nm}))['inputSettings']
            cw, ch = st.get('width'), st.get('height')
            tr = (await req('GetSceneItemTransform',
                            {"sceneName": sc, "sceneItemId": it['sceneItemId']}))['sceneItemTransform']
            bw, bh = tr['boundsWidth'], tr['boundsHeight']
            if not cw or not bw:
                continue
            ar_src, ar_box = cw / ch, bw / bh
            if abs(ar_src - ar_box) > 0.04:
                print("  ASPECT  %-24s in %-26s %sx%s -> %dx%d" % (nm, sc, cw, ch, bw, bh))
                issues.append("aspect mismatch: %s in %s" % (nm, sc)); mism += 1
    print("  (none)" if not mism else "")

    print("\n=== 5. autopilot config vs reality ===")
    for exe, scn in C['games'].items():
        if scn not in scenes:
            issues.append("games maps %s -> missing scene %r" % (exe, scn))
