    for st, scn in (C.get('valorant_scenes') or {}).items():
        if scn not in scenes:
            issues.append("valorant_scenes[%s] -> missing %r" % (st, scn))
            print("  BAD STATE  %s -> %r" % (st, scn))
    print("  all config references resolve" if not any(
        'games maps' in i or 'lists missing' in i or 'valorant_scenes' in i for i in issues) else "")

    print("\n=== 6. overlay files on disk vs referenced ===")
    referenced = set()
    for name, kind in inputs.items():
        if kind != 'browser_source':
            continue
        st = (await req('GetInputSettings', {"inputName": name}))['inputSettings']
        u = st.get('url') or ''
        fn = urllib.parse.urlparse(u).path.lstrip('/')
        if fn.endswith('.html'):
            referenced.add(os.path.basename(fn))
    on_disk = {f for f in os.listdir(OVERLAYS) if f.endswith('.html')}
    for f in sorted(on_disk - referenced):
