input.content:
/* ==================================================================
   Gotham overlay design system - shared by every overlay in this
   folder. Linked relatively, so it resolves on both the file:// pages
   and the ones served from the HUD server on 127.0.0.1:4466.

   Art direction, matched to the reference sheet:
     - chrome bevels: a metallic rim around a near-black panel
     - orange gradient display type with a dark outline
     - a spotlight cone from above, fog pooling at the bottom, rain
     - the emblem as a recurring badge, usually overlapping a corner

   Anything audio-reactive reads --glow (0..1), which obs-meter.js sets
   on <html>. Pages that never load that script still render correctly:
   --glow defaults to 0 here.
   ================================================================== */

:root {
  --glow: 0;

  /* ground */
  --ink:    #05070a;
  --ink2:   #0d1117;
  --ink3:   #161c24;

  /* chrome */
  --chrome-hi:  #eef3f9;
  --chrome-mid: #8c98a8;
  --chrome-lo:  #2b323b;

  /* the orange/amber signature */
  --amber:     #ff8a1f;
  --amber-hi:  #ffd36b;
  --amber-lo:  #c2410c;
  --bat:       #f2c232;

  /* type */
  --bone:  #e6ecf2;
  --steel: #9fb3c8;

  --display: "BatDisplay", "Bahnschrift", "DIN Condensed", "Oswald",
             "Arial Narrow", sans-serif;
}

/* A licensed display face if one is dropped into assets/; otherwise the
   stack above is used and nothing breaks. */
@font-face {
  font-family: "BatDisplay";
  src: url("assets/display.woff2") format("woff2");
  font-display: swap;
}

* { box-sizing: border-box; margin: 0; }
html, body { height: 100%; overflow: hidden; background: transparent; }
body { font-family: var(--display); color: var(--bone); }
[hidden] { display: none !important; }

/* ---------- chrome frame ----------------------------------------- */
/* A gradient "rim" element with a dark panel inset inside it. Built as
   a padded gradient rather than border-image so the corner radius and
   the highlight both follow the same curve. */
.chrome {
  position: relative;
  padding: 3px;
  border-radius: 10px;
  background: linear-gradient(145deg,
    var(--chrome-hi) 0%, var(--chrome-mid) 26%, var(--chrome-lo) 52%,
    var(--chrome-mid) 76%, var(--chrome-hi) 100%);
  box-shadow: 0 6px 26px rgba(0,0,0,.6),
              0 0 calc(var(--glow) * 26px) color-mix(in srgb, var(--amber) 45%, transparent);
}
.chrome > .panel {
  position: relative; height: 100%; width: 100%;
  border-radius: 7px;
  background: linear-gradient(170deg, var(--ink3) 0%, var(--ink) 62%);
  overflow: hidden;
}
/* a soft inner top highlight, so the panel reads as glass not paint */
.chrome > .panel::before {
  content: ""; position: absolute; left: 0; right: 0; top: 0; height: 42%;
  background: linear-gradient(to bottom, rgba(255,255,255,.07), transparent);
  pointer-events: none;
}

/* ---------- orange gradient display type -------------------------- */
.amber-text {
  background: linear-gradient(to bottom,
    var(--amber-hi) 0%, var(--amber) 46%, var(--amber-lo) 100%);
  -webkit-background-clip: text; background-clip: text;
  color: transparent;
  text-transform: uppercase; font-weight: 700;
  letter-spacing: .02em;
  filter: drop-shadow(0 2px 0 rgba(0,0,0,.55))
          drop-shadow(0 0 calc(14px + var(--glow) * 26px)
                      color-mix(in srgb, var(--amber) 55%, transparent));
}

/* ---------- spotlight cone ---------------------------------------- */
/* Thrown from just above the top edge, widening downward. Brightness
   breathes on its own and lifts with audio. */
.spotlight {
  position: absolute; left: 50%; top: -6%; translate: -50% 0;
  width: 58%; height: 86%;
  background: linear-gradient(to bottom,
    color-mix(in srgb, var(--amber-hi) calc(16% + var(--glow) * 22%), transparent) 0%,
    color-mix(in srgb, var(--amber) 7%, transparent) 46%,
    transparent 84%);
  clip-path: polygon(42% 0, 58% 0, 100% 100%, 0 100%);
  filter: blur(10px);
  animation: gothamBreathe 6.5s ease-in-out infinite;
  pointer-events: none;
}
@keyframes gothamBreathe { 50% { opacity: .68; } }

/* the bright lamp mouth at the very top of the cone */
.spotlight-source {
  position: absolute; left: 50%; top: 0; translate: -50% -50%;
  width: 16%; aspect-ratio: 3 / 1; border-radius: 50%;
  background: radial-gradient(ellipse at center,
    color-mix(in srgb, var(--amber-hi) 85%, transparent) 0%,
    transparent 70%);
  filter: blur(6px);
  opacity: calc(.7 + var(--glow) * .3);
  pointer-events: none;
}

/* ---------- fog ---------------------------------------------------- */
/* Two layers drifting in opposite directions at different speeds; the
   parallax is what stops it reading as a single sliding texture. */
.fog { position: absolute; left: 0; right: 0; bottom: 0; pointer-events: none; }
.fog i {
  position: absolute; left: -60%; right: -60%; bottom: 0; height: 100%;
  background: radial-gradient(60% 100% at 20% 100%, rgba(173,190,210,.17), transparent 70%),
              radial-gradient(52% 100% at 56% 100%, rgba(173,190,210,.13), transparent 72%),
              radial-gradient(64% 100% at 86% 100%, rgba(173,190,210,.15), transparent 70%);
  filter: blur(14px);
}
.fog i:nth-child(1) { animation: fogDriftA 34s linear infinite; opacity: .9; }
.fog i:nth-child(2) { animation: fogDriftB 52s linear infinite; opacity: .6; }
@keyframes fogDriftA { to { transform: translateX(22%); } }
@keyframes fogDriftB { to { transform: translateX(-26%); } }

/* ---------- rain ---------------------------------------------------- */
.rain {
  position: absolute; inset: -20%; pointer-events: none; opacity: .4;
  background: repeating-linear-gradient(76deg,
    color-mix(in srgb, var(--bone) 13%, transparent) 0 1px,
    transparent 1px 14px);
  animation: rainPour .9s linear infinite;
}
@keyframes rainPour { to { transform: translate3d(-58px, 210px, 0); } }

/* ---------- lens sparkle ------------------------------------------- */
/* A four-point star highlight for frame corners. */
.sparkle {
  position: absolute; width: 56px; height: 56px; pointer-events: none;
  background:
    linear-gradient(to right,  transparent 46%, #fff 50%, transparent 54%),
    linear-gradient(to bottom, transparent 46%, #fff 50%, transparent 54%);
  filter: blur(.6px) drop-shadow(0 0 8px var(--amber-hi));
  opacity: calc(.75 + var(--glow) * .25);
  animation: sparkleTwinkle 4.5s ease-in-out infinite;
}
@keyframes sparkleTwinkle { 50% { opacity: .35; transform: scale(.82); } }

/* ---------- emblem badge -------------------------------------------- */
/* object-fit:contain everywhere, so a swapped-in emblem of any aspect is
   fitted rather than stretched. */
.emblem { line-height: 0; }
.emblem img {
  display: block; width: 100%; height: 100%;
  object-fit: contain; object-position: center;
}

/* ---------- film grain / scanlines ----------------------------------- */
.grain {
  position: absolute; inset: 0; pointer-events: none; opacity: .45;
  background: repeating-linear-gradient(to bottom,
    rgba(0,0,0,.22) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
}

/* ==================================================================
 * obs-meter.js - drives --glow (0..1) from OBS's own audio meters.
 *
 * Connects to the built-in obs-websocket v5 server and subscribes to
 * InputVolumeMeters, which is a high-volume event and so must be asked
 * for explicitly. No third-party OBS plugin involved.
 *
 * Shared by the overlays that react to sound. Everything degrades
 * quietly: if the socket never connects, --glow simply stays at 0 and
 * the page still renders, just without the reactive lift.
 *
 *   OBSMeter.start({ input, port, pw, gain, floor, target, onLevel })
 *
 *   input   OBS input to watch        (default "Desktop Audio")
 *   port/pw obs-websocket            (no defaults - pass them in)
 *   gain    sensitivity multiplier    (default 1.6)
 *   floor   dBFS treated as silence   (default -58)
 *   target  element to set --glow on  (default document.documentElement)
 *   onLevel optional callback(level 0..1) for per-frame custom work
 * ================================================================== */
(function (global) {
  'use strict';

  /* ---- minimal SHA-256: crypto.subtle is unavailable on file:// ---- */
  function sha256Bytes(bytes) {
    const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
      0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
      0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
      0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
      0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
      0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
      0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
      0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
    let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    const ml = bytes.length * 8;
    const withPad = [...bytes, 0x80];
    while (withPad.length % 64 !== 56) withPad.push(0);
    for (let i = 7; i >= 0; i--) withPad.push(Math.floor(ml / 2 ** (i * 8)) & 0xff);
    const rotr = (x, n) => (x >>> n) | (x << (32 - n));
    const w = new Uint32Array(64);
    for (let off = 0; off < withPad.length; off += 64) {
      for (let i = 0; i < 16; i++)
        w[i] = (withPad[off+i*4] << 24) | (withPad[off+i*4+1] << 16) |
               (withPad[off+i*4+2] << 8) | withPad[off+i*4+3];
      for (let i = 16; i < 64; i++) {
        const s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15] >>> 3);
        const s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2] >>> 10);
        w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
      }
      let [a,b,c,d,e,f,g,h] = H;
      for (let i = 0; i < 64; i++) {
        const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
        const ch = (e & f) ^ (~e & g);
        const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
        const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
        const mj = (a & b) ^ (a & c) ^ (b & c);
        const t2 = (S0 + mj) >>> 0;
        h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
      }
      H = H.map((v,i) => (v + [a,b,c,d,e,f,g,h][i]) >>> 0);
    }
    const out = [];
    for (const v of H) out.push((v>>>24)&0xff, (v>>>16)&0xff, (v>>>8)&0xff, v&0xff);
    return out;
  }
  const b64 = a => btoa(String.fromCharCode(...a));
  const utf8 = s => [...new TextEncoder().encode(s)];
  const sha256b64 = s => b64(sha256Bytes(utf8(s)));

  function start(opts) {
    opts = opts || {};
    const INPUT  = opts.input || 'Desktop Audio';
    const PORT   = String(opts.port || '4455');
    const PW     = opts.pw || '';
    const GAIN   = parseFloat(opts.gain != null ? opts.gain : 1.6);
    const FLOOR  = parseFloat(opts.floor != null ? opts.floor : -58);
    const target = opts.target || document.documentElement;
    const onLevel = opts.onLevel;

    /* ---- fast attack so transients pop, slow release ---- */
    let level = 0, peak = 0;
    function paint() {
      level += (peak - level) * (peak > level ? 0.55 : 0.12);
      const v = Math.max(0, Math.min(1, level));
      target.style.setProperty('--glow', v.toFixed(3));
      if (onLevel) onLevel(v);
      requestAnimationFrame(paint);
    }
    target.style.setProperty('--glow', '0');
    requestAnimationFrame(paint);

    let ws, retry = 0;
    function connect() {
      try { ws = new WebSocket('ws://127.0.0.1:' + PORT); }
      catch (e) { return void setTimeout(connect, 2000); }

      ws.onmessage = ev => {
        const m = JSON.parse(ev.data);
        if (m.op === 0) {                                   // Hello
          const d = { rpcVersion: 1, eventSubscriptions: 1 << 16 };
          if (m.d.authentication) {
            const { salt, challenge } = m.d.authentication;
            d.authentication = sha256b64(sha256b64(PW + salt) + challenge);
          }
          ws.send(JSON.stringify({ op: 1, d }));
        } else if (m.op === 2) {                            // Identified
          retry = 0;
        } else if (m.op === 5 && m.d.eventType === 'InputVolumeMeters') {
          for (const inp of m.d.eventData.inputs) {
            if (inp.inputName !== INPUT) continue;
            let pk = 0;
            for (const ch of (inp.inputLevelsMul || []))
              for (const s of ch) if (s > pk) pk = s;
            const db = pk > 0 ? 20 * Math.log10(pk) : -200;
            peak = Math.max(0, Math.min(1, ((db - FLOOR) / -FLOOR) * GAIN));
          }
        }
      };
      ws.onclose = () => { retry++; setTimeout(connect, Math.min(1000 * retry, 5000)); };
      ws.onerror = () => { try { ws.close(); } catch (e) {} };
    }
    connect();
  }

  global.OBSMeter = { start };
})(window);

