<script>
const Q    = new URLSearchParams(location.search);
const MAX  = parseInt(Q.get('max') || '60', 10);
const FADE = Q.get('fade') === '1';
const HOLD = parseFloat(Q.get('hold') || '45') * 1000;
document.documentElement.dataset.accent = (Q.get('accent') || 'arena').toLowerCase();

const headEl = document.getElementById('head');
const titleTxt = Q.get('title') ?? 'CHAT';
if (titleTxt) headEl.textContent = titleTxt; else headEl.hidden = true;

const list = document.getElementById('list');
const statusEl = document.getElementById('status');
let connected = 0;
function up() { if (++connected === 1) statusEl.hidden = true; }
function setStatus(t) { if (!connected) { statusEl.textContent = t; statusEl.hidden = false; } }

/* ---- deterministic colour for users with no colour set ---- */
const PALETTE = ['#ff8a1f','#ffd36b','#6fc9ff','#35c46b','#ff6ad5','#a970ff',
                 '#ff5c5c','#7fd4a0','#f2c232','#9fb3c8'];
function pickColor(name) {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
  return PALETTE[h % PALETTE.length];
}

const esc = s => s.replace(/[&<>"]/g, c => (
  { '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' }[c]));

/* ---- render one message ----------------------------------------- */
/* body is pre-built HTML (emotes already substituted); everything that
   came off the wire is escaped before it gets here. */
function add(platform, name, bodyHtml, color, roles) {
  const el = document.createElement('div');
  el.className = 'msg';
  const pips = (roles || []).map(r => '<span class="pip ' + r + '"></span>').join('');
  el.innerHTML =
    '<span class="tag ' + platform + '">' + (platform === 'tw' ? 'TW' : 'YT') + '</span>' +
    pips +
    '<span class="who" style="color:' + (color || pickColor(name)) + '">' + esc(name) + '</span>' +
    '<span class="sep"> &middot; </span>' +
    '<span class="body">' + bodyHtml + '</span>';
  list.insertBefore(el, list.firstChild);      // newest at top

  while (list.children.length > MAX) list.removeChild(list.lastChild);
  if (FADE) setTimeout(() => {
    el.classList.add('gone');
    setTimeout(() => el.remove(), 700);
  }, HOLD);
}

/* =================================================================
 * Twitch - IRC over websocket, anonymous.
 * A justinfan* nick needs no token and no login; it can read any
 * public channel. Tags are requested so we get colour, display name
 * and emote positions.
 * ================================================================= */
function startTwitch(channel) {
  let ws, retry = 0;
  function conn() {
    try { ws = new WebSocket('wss://irc-ws.chat.twitch.tv:443'); }
    catch (e) { return void setTimeout(conn, 3000); }

    ws.onopen = () => {
      ws.send('CAP REQ :twitch.tv/tags twitch.tv/commands');
      ws.send('NICK justinfan' + (10000 + Math.floor(Math.random() * 80000)));
      ws.send('JOIN #' + channel.toLowerCase());
      retry = 0;
    };
    ws.onmessage = ev => {
      for (const line of ev.data.split('\r\n')) {
        if (!line) continue;
        if (line.startsWith('PING')) { ws.send('PONG :tmi.twitch.tv'); continue; }
        if (line.includes(' JOIN ')) { up(); continue; }
        const m = line.match(/^(?:@([^ ]+) )?:([^!]+)![^ ]+ PRIVMSG #[^ ]+ :([\s\S]*)$/);
        if (!m) continue;
        const tags = {};
        if (m[1]) for (const kv of m[1].split(';')) {
          const i = kv.indexOf('=');
          tags[kv.slice(0, i)] = kv.slice(i + 1);
        }
        const name = tags['display-name'] || m[2];
        const roles = [];
        if (tags.mod === '1' || (tags.badges || '').includes('broadcaster')) roles.push('mod');
        if (tags.subscriber === '1') roles.push('sub');
        if ((tags.badges || '').includes('vip')) roles.push('vip');
        add('tw', name, twitchBody(m[3], tags.emotes), tags.color || '', roles);
        up();
      }
    };
    ws.onclose = () => {
      retry++;
      setStatus('twitch: reconnecting');
      setTimeout(conn, Math.min(1500 * retry, 15000));
    };
    ws.onerror = () => { try { ws.close(); } catch (e) {} };
  }
  conn();
}

/* Substitute Twitch emotes. The `emotes` tag gives ranges as indices
   into the message measured in CODE POINTS, not UTF-16 units, so the
   text is split with Array.from - otherwise any emoji earlier in the
   message shifts every following emote by one. */
function twitchBody(text, emotesTag) {
  const chars = Array.from(text);
  if (!emotesTag) return esc(text);
  const spans = [];
  for (const group of emotesTag.split('/')) {
    const [id, ranges] = group.split(':');
    if (!ranges) continue;
    for (const r of ranges.split(',')) {
      const [a, b] = r.split('-').map(Number);
      if (Number.isInteger(a) && Number.isInteger(b)) spans.push({ id, a, b });
    }
  }
  spans.sort((p, q) => p.a - q.a);
  let out = '', cur = 0;
  for (const s of spans) {
    if (s.a < cur) continue;
    out += esc(chars.slice(cur, s.a).join(''));
    out += '<img class="emote" alt="" src="https://static-cdn.jtvnw.net/emoticons/v2/'
         + encodeURIComponent(s.id) + '/default/dark/2.0">';
    cur = s.b + 1;
  }
  out += esc(chars.slice(cur).join(''));
  return out;
}

/* =================================================================
 * YouTube - Data API v3 polling.
 * There is no public socket for YT live chat, so this resolves the
 * broadcast's activeLiveChatId once, then long-polls the message list
 * honouring the pollingIntervalMillis the API hands back.
 * ================================================================= */
function startYouTube(key, videoId) {
  const API = 'https://www.googleapis.com/youtube/v3/';
  let chatId = null, pageToken = null, firstPass = true;

  async function resolve() {
    const r = await fetch(API + 'videos?part=liveStreamingDetails&id='
                          + encodeURIComponent(videoId) + '&key=' + encodeURIComponent(key));
    if (!r.ok) throw new Error('videos.list HTTP ' + r.status);
    const j = await r.json();
    const it = (j.items || [])[0];
    chatId = it && it.liveStreamingDetails && it.liveStreamingDetails.activeLiveChatId;
    if (!chatId) throw new Error('no active live chat on that video');
  }

  async function poll() {
    let wait = 6000;
    try {
      if (!chatId) await resolve();
      const url = API + 'liveChat/messages?liveChatId=' + encodeURIComponent(chatId)
                + '&part=snippet,authorDetails&maxResults=200&key=' + encodeURIComponent(key)
                + (pageToken ? '&pageToken=' + encodeURIComponent(pageToken) : '');
      const r = await fetch(url);
      if (!r.ok) throw new Error('messages HTTP ' + r.status);
      const j = await r.json();
      pageToken = j.nextPageToken || null;
      wait = Math.max(2000, j.pollingIntervalMillis || 6000);
      // The first page is backlog - replaying it would dump the whole
      // pre-existing chat into the box at once.
      if (!firstPass) {
        for (const it of (j.items || [])) {
          const s = it.snippet || {}, a = it.authorDetails || {};
          const txt = s.displayMessage || (s.textMessageDetails || {}).messageText || '';
          if (!txt) continue;
          const roles = [];
          if (a.isChatModerator || a.isChatOwner) roles.push('mod');
          if (a.isChatSponsor) roles.push('sub');
          add('yt', a.displayName || 'viewer', esc(txt), '', roles);
        }
      }
      firstPass = false;
      up();
    } catch (e) {
      setStatus('youtube: ' + e.message);
      wait = 15000;                       // back off; often quota or a bad id
      chatId = null;
    }
    setTimeout(poll, wait);
  }
  poll();
}

/* =================================================================
 * demo mode - synthetic traffic so the look can be checked without
 * any channel or key configured.
 * ================================================================= */
function startDemo() {
  const who = [['tw','BludhavenBeat','#a970ff',['sub']],
