    add(w[0], w[1], esc(said[Math.floor(Math.random() * said.length)]), w[2], w[3]);
    setTimeout(next, 700 + Math.random() * 1600);
  })();
}

/* ---- boot ---- */
const tw = Q.get('twitch'), ytKey = Q.get('yt_key'), ytVid = Q.get('yt_video');
if (Q.get('demo') === '1') startDemo();
else {
  if (tw) startTwitch(tw);
  if (ytKey && ytVid) startYouTube(ytKey, ytVid);
  if (!tw && !(ytKey && ytVid)) setStatus('no channel configured');
}
