/* --lit is animated in step with the spin and drives the face
   brightness, so the plate catches light when it faces the viewer and
   falls dark as it turns away. It has to be a registered property -
   an unregistered custom property animates in discrete jumps. */
@property --lit { syntax: '<number>'; inherits: true; initial-value: 1; }

#emblem {
  width: clamp(220px, 27vw, 460px); margin: 0 auto;
  /* depth of the extrusion, in canvas-relative units so it tracks the
     emblem's own size */
  --depth: 1.15vw;
  perspective: 900px;              /* tighter = more pronounced 3D */
  perspective-origin: 50% 42%;
  animation: hover 7s ease-in-out infinite;
}
@keyframes hover { 50% { transform: translateY(-1.6%); } }

#spin {
  position: relative;
  transform-style: preserve-3d;
  /* the constant rotateX tilt is what sells it as an object sitting in
     space rather than a decal spinning flat-on to camera */
  animation: spinY 12s linear infinite, lit 12s linear infinite;
}
@keyframes spinY {
  from { transform: rotateX(9deg) rotateY(0deg); }
  to   { transform: rotateX(9deg) rotateY(360deg); }
}
/* brightest face-on (0deg, 180deg), dark edge-on (90deg, 270deg) */
@keyframes lit {
  0%   { --lit: 1.12; }
  25%  { --lit: 0.46; }
  50%  { --lit: 1.12; }
  75%  { --lit: 0.46; }
  100% { --lit: 1.12; }
}

#spin .face {
  backface-visibility: hidden; -webkit-backface-visibility: hidden;
  filter: brightness(var(--lit))
          drop-shadow(0 0 calc(30px + var(--glow) * 60px)
                      color-mix(in srgb, var(--amber) 55%, transparent))
          drop-shadow(0 0 140px color-mix(in srgb, var(--amber) 22%, transparent));
}
/* the front defines the height; the back is laid over it, turned away
   until the spin passes 90deg. Both are pushed out to the faces of the
   slab so the extrusion sits between them. */
#spin .face.front {
  position: relative; width: 100%; height: auto;
  transform: translateZ(calc(var(--depth) / 2));
}
#spin .face.back {
  position: absolute; inset: 0; width: 100%; height: 100%;
  transform: rotateY(180deg) translateZ(calc(var(--depth) / 2));
}

/* ---- the extruded edge ----
   Copies of the emblem stacked along Z between the two faces. Because
   the artwork is a transparent-cornered oval, the stack's silhouette
   is the oval, so the "side" of the medallion follows its real shape.
   They are darkened hard, so only the front and back read as artwork
   and everything between reads as machined metal. */
#spin .slice {
  position: absolute; inset: 0; width: 100%; height: 100%;
  filter: brightness(calc(var(--lit) * 0.21)) saturate(.45) contrast(1.2);
}

