input.new_string:
/* ---- emblem: licensed artwork if present, else the drawn fallback ----
   Resolved once, then applied to every layer of the medallion, so a
   fallback step can never leave the sides showing different art.

   SLICES is the extrusion depth resolution. The step between layers has
   to stay under ~1.5px or the stack shows visible gaps as it turns; 16
   across the slab is enough at the sizes this renders at. */
const SLICES = 16;
(function () {
  const spin = document.getElementById('spin');
  const front = document.getElementById('emimg');

  // build the edge stack between the two faces, back to front
  for (let i = 0; i < SLICES; i++) {
    const t = 0.5 - (i + 1) / (SLICES + 1);     // +0.5 .. -0.5 of --depth
    const s = document.createElement('img');
    s.className = 'slice';
    s.alt = '';
    s.style.transform = 'translateZ(calc(var(--depth) * ' + t.toFixed(4) + '))';
    spin.insertBefore(s, front);
  }

  const layers = [...spin.querySelectorAll('img')];
  const names = ['assets/emblem.svg', 'assets/emblem.png',
                 'assets/emblem-fallback.svg'];
  let i = 0;
  const probe = new Image();
  probe.onload  = () => layers.forEach(l => { l.src = probe.src; });
  probe.onerror = () => { if (i < names.length) probe.src = names[i++]; };
  probe.src = names[i++];
})();

/* dark enough to read as the side of the object rather than more
