        dd['authentication']=base64.b64encode(hashlib.sha256((s+a['challenge']).encode()).digest()).decode()
    await ws.send(json.dumps({"op":1,"d":dd})); await ws.recv()
    n=[0]
    async def req(t,data=None,tol=False):
