        "inputSettings":{"url":COMMON,"width":1920,"height":1080}})
    print("renamed Theme - Valorant -> Theme - Shading, repointed")

    # 2. drop the old per-game variants from their scenes
    for sc in LIVE:
        items=(await req('GetSceneItemList',{"sceneName":sc}))['sceneItems']
        for it in items:
            if it['sourceName'] in OLD:
                await req('RemoveSceneItem',{"sceneName":sc,"sceneItemId":it['sceneItemId']})
                print("  removed %-18s from %s" % (it['sourceName'], sc))

    # 3. ensure the shared source is in every live scene, sitting just
    #    above the captures and below cam / HUD / alerts
    for sc in LIVE:
        items=(await req('GetSceneItemList',{"sceneName":sc}))['sceneItems']
        names=[i['sourceName'] for i in items]
        if "Theme - Shading" not in names:
            r=await req('CreateSceneItem',{"sceneName":sc,"sourceName":"Theme - Shading",
                                           "sceneItemEnabled":True})
            iid=r['sceneItemId']
            print("  added to %s" % sc)
        else:
            iid=[i['sceneItemId'] for i in items if i['sourceName']=="Theme - Shading"][0]
        # full-canvas transform
        await req('SetSceneItemTransform',{"sceneName":sc,"sceneItemId":iid,
            "sceneItemTransform":{"positionX":0,"positionY":0,
                                  "boundsType":"OBS_BOUNDS_STRETCH",
                                  "boundsWidth":1920,"boundsHeight":1080}})
        # index = directly above the capture layer
        items=(await req('GetSceneItemList',{"sceneName":sc}))['sceneItems']
        caps=[i for i in items if i['sourceName'].startswith('Capture')]
        target=max(i['sceneItemIndex'] for i in caps)+1 if caps else 1
        await req('SetSceneItemIndex',{"sceneName":sc,"sceneItemId":iid,"sceneItemIndex":target})

    # 4. delete the now-unused sources
    for nm in OLD:
