    "new_string": "MC_PATH = os.path.join(HERE, 'minecraft-today.json')

# Vanilla death messages, reduced to the fragments that identify one. Kept
# as fragments rather than full messages because the subject is the player's
# name and the object varies (mob, item, player), so anchoring on the verb
# is what survives both. Checked longest-first so "was killed by magic"
# cannot be swallowed by "was killed by".
MC_DEATH_BITS = [
    "was slain by", "was shot by", "was pummeled by", "was fireballed by",
    "was killed by magic", "was killed trying to hurt", "was killed by",
    "was blown up by", "was impaled by", "was skewered by", "was stung to death",
    "was squashed by", "was squished too much", "was poked to death",
    "was pricked to death", "was struck by lightning", "was burnt to a crisp",
    "was obliterated by", "was doomed to fall", "was frozen to death",
    "was roasted in dragon's breath", "walked into a cactus",
    "walked into the danger zone", "walked into fire", "went up in flames",
    "burned to death", "tried to swim in lava", "discovered the floor was lava",
    "suffocated in a wall", "starved to death", "withered away", "froze to death",
    "drowned", "blew up", "hit the ground too hard", "fell from a high place",
    "fell off a ladder", "fell off some vines", "fell out of the world",
    "experienced kinetic energy", "didn't want to live in the same world as",
]
MC_ADVANCE_BITS = [
    "has made the advancement", "has completed the challenge",
    "has reached the goal",
]


def _mc_log_path(cfg):
    """Resolve the Java client log, or None if there is nothing to watch."""
    explicit = (cfg.get('minecraft_log') or '').strip()
    if explicit:
        return explicit if os.path.exists(explicit) else None
    default = os.path.join(os.environ.get('APPDATA', ''), '.minecraft',
                           'logs', 'latest.log')
    return default if os.path.exists(default) else None


class MinecraftRecord:
    """Deaths and advancements for today, tailed from the Java client log."""

    def __init__(self):
        self.data = {"date": self._today(), "deaths": 0, "advancements": 0,
                     "last_death": "", "last_advancement": "",
                     "last_death_at": 0}
        try:
            on_disk = json.load(open(MC_PATH, encoding='utf-8'))
            if on_disk.get('date') == self._today():
                self.data = on_disk
        except Exception:
            pass

    @staticmethod
    def _today():
        return time.strftime('%Y-%m-%d')

    def _roll(self):
        if self.data.get('date') != self._today():
            log("new day - resetting Minecraft counters (was %d deaths)"
                % self.data.get('deaths', 0))
            self.data = {"date": self._today(), "deaths": 0, "advancements": 0,
                         "last_death": "", "last_advancement": "",
                         "last_death_at": 0}
            self._save()

    def _save(self):
        try:
            json.dump(self.data, open(MC_PATH, 'w', encoding='utf-8'), indent=2)
        except Exception as e:
            log("minecraft save failed: %s" % e)

    def death(self, msg):
        self._roll()
        self.data['deaths'] += 1
        self.data['last_death'] = msg
        self.data['last_death_at'] = time.time()
        self._save()
        log("minecraft death #%d: %s" % (self.data['deaths'], msg))

    def advancement(self, name):
        self._roll()
        self.data['advancements'] += 1
        self.data['last_advancement'] = name
        self._save()
        log("minecraft advancement: %s" % name)

    def summary(self):
        self._roll()
        d = dict(self.data)
        # "death-free for" is the bit that actually creates tension on
        # stream, so it is derived here rather than in the overlay.
        d['since_death_s'] = (int(time.time() - self.data['last_death_at'])
                              if self.data.get('last_death_at') else None)
        return d


async def minecraft_watcher(cfg, stop):
    """Tail the Java client log for death and advancement messages.

    Minecraft truncates latest.log on every launch, so this tracks the
    inode/size and re-seeks when the file shrinks or is replaced - otherwise
    the tail would sit past EOF forever after a game restart.
    """
    if not cfg.get('minecraft_enabled', True):
        return
    rec = MinecraftRecord()
    LATEST['minecraft'] = rec.summary()
    fh = None
    path_seen = None
    try:
        while not stop.is_set():
            path = _mc_log_path(cfg)
            if not path:
                # not installed yet, or a custom launcher - check back
                # occasionally rather than spinning
                LATEST['minecraft'] = dict(rec.summary(), waiting=True)
                await asyncio.sleep(30)
                continue

            try:
                if fh is None or path != path_seen:
                    if fh:
                        fh.close()
                    fh = open(path, 'r', encoding='utf-8', errors='replace')
                    fh.seek(0, os.SEEK_END)    # only new lines matter
                    path_seen = path
                    log("minecraft: watching %s" % path)

                # relaunch truncates the file - re-read from the start
                if os.path.getsize(path) < fh.tell():
                    fh.seek(0)

                for line in fh:
                    line = line.rstrip('\n')
                    if '/INFO]' not in line:
                        continue
                    body = line.split(']: ', 1)[-1].strip()
                    if not body:
                        continue
                    low = body.lower()
                    adv = next((b for b in MC_ADVANCE_BITS if b in low), None)
                    if adv:
                        name = body.split('[', 1)[-1].rstrip(']') if '[' in body else body
                        rec.advancement(name)
                        continue
                    if any(b in low for b in MC_DEATH_BITS):
                        rec.death(body)

                LATEST['minecraft'] = rec.summary()
            except Exception as e:
                log("minecraft watcher: %s" % e)
                if fh:
                    try:
                        fh.close()
                    except Exception:
                        pass
                fh = None
            await asyncio.sleep(1.0)
    finally:
        if fh:
            try:
                fh.close()
            except Exception:
                pass


def start_hud_server(cfg):"
  }
