  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60);
  if (h) return h + 'h ' + String(m).padStart(2,'0') + 'm';
  if (m) return m + 'm ' + String(sec % 60).padStart(2,'0') + 's';
  return sec + 's';
}

async function tick() {
  try {
    const r = await fetch('/state.json', { cache: 'no-store' });
    const s = await r.json();
    const mc = s.minecraft;

    // The key is absent entirely if autopilot is older than this feature;
    // `waiting` means it is running but Minecraft is not installed/launched.
    if (!mc) { el('waiting').hidden = false; el('waiting').textContent = 'tracker not available'; }
    else if (mc.waiting) { el('waiting').hidden = false; el('waiting').textContent = 'waiting for minecraft'; }
    else el('waiting').hidden = true;

    if (mc) {
      el('deathv').textContent = mc.deaths ?? 0;
      if (lastDeaths !== null && (mc.deaths ?? 0) > lastDeaths) {
        el('deathv').classList.remove('bump');
        void el('deathv').offsetWidth;          // restart the animation
        el('deathv').classList.add('bump');
      }
      lastDeaths = mc.deaths ?? 0;

      el('streakv').textContent = human(mc.since_death_s);
      el('lastv').textContent = mc.last_death || '—';

      const adv = mc.last_advancement || '';
      el('advv').textContent = adv || '—';
      if (lastAdv !== null && adv && adv !== lastAdv) {
        el('advrow').classList.remove('earned');
        void el('advrow').offsetWidth;
        el('advrow').classList.add('earned');
      }
      lastAdv = adv;
    }
  } catch (e) {
    el('waiting').hidden = false;
    el('waiting').textContent = 'hud server offline';
  }
  setTimeout(tick, 1000);
}
tick();
</script>
